import { Toolbar as Base } from '@base-ui/react/toolbar'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * ActionBar.
 *
 * The strip of actions that belongs to what is on screen: Save and Cancel at
 * the foot of a form, the bulk actions above a table, the formatting buttons
 * over an editor. `sticky` is the point of it - a long form whose Save button
 * is a thousand pixels below the field being edited has a Save button the
 * reader has to go looking for.
 *
 * Built on Base UI's Toolbar, which supplies the part that is easy to get
 * wrong: `role="toolbar"` and arrow-key navigation, so the whole bar is one
 * tab stop and the arrows move between its buttons. That matters more here
 * than anywhere else - an action bar sits at the end of a form, and without it
 * a reader tabbing out of the last field lands in a queue of five buttons
 * instead of on Save.
 *
 * The buttons are the product's own: this draws the strip, not what is in it.
 * `ActionBarButton` exists only to join a `Button` to the toolbar's keyboard
 * handling, via `render`.
 */

export const actionBarVariants = cva('flex items-center gap-2', {
  variants: {
    /* Where it sits, and therefore which edge grows a border.
     *
     * The border is on the side facing the content, so the bar reads as
     * attached to the page rather than floating over it - and only when it is
     * stuck, because a bar in the middle of a page needs no seam. */
    position: {
      bottom: 'sticky bottom-0 border-t border-line bg-bg/95 py-3 backdrop-blur',
      top: 'sticky top-0 border-b border-line bg-bg/95 py-3 backdrop-blur',
      /* Not stuck at all: a strip in the flow of the page. */
      static: '',
    },
    justify: {
      start: 'justify-start',
      end: 'justify-end',
      between: 'justify-between',
    },
  },
  defaultVariants: { position: 'static', justify: 'start' },
})

export interface ActionBarProps extends Base.Root.Props, VariantProps<typeof actionBarVariants> {}

/**
 * The bar.
 *
 * `aria-label` is worth passing when a page has more than one: "Formatting"
 * and "Bulk actions" are different toolbars, and a screen reader announcing
 * "toolbar" twice tells the reader nothing about which one they are in.
 */
export function ActionBar({ position, justify, className, ...props }: ActionBarProps) {
  return (
    <Base.Root
      className={cn(actionBarVariants({ position, justify }), className)}
      // A stuck bar has to clear what scrolls under it; the theme's own
      // stacking order is what says how high, rather than a number invented
      // here that would disagree with every overlay in the set.
      style={position === 'bottom' || position === 'top' ? { zIndex: 'var(--z-sticky)' } : undefined}
      {...props}
    />
  )
}

/** A button in the bar. Give it the set's own `Button` through `render`, so
 * the toolbar's arrow keys reach it and the button keeps its variants. */
export const ActionBarButton = Base.Button

/** A rule between groups of actions. Decorative, and announced as a separator
 * rather than as a control. */
export function ActionBarSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('mx-1 h-5 w-px shrink-0 bg-line', className)} {...props} />
}

/** A group of related actions inside the bar - the three alignment buttons, a
 * pair of toggles. Groups the arrows walk as one. */
export function ActionBarGroup({ className, ...props }: Base.Group.Props) {
  return <Base.Group className={cn('flex items-center gap-1', className)} {...props} />
}

/** Pushes what follows to the far end. A plain spacer, so a bar can put Cancel
 * beside Save and everything else to the left without a wrapper. */
export function ActionBarSpacer() {
  return <div className="flex-1" aria-hidden />
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import {
  weekdayRows,
  weeks,
  type ActivityEntry,
  type Cell,
  type Weekday,
} from './activity-weeks'

/*
 * A year of activity, one square per day.
 *
 * The shape everyone recognises: weeks as columns, weekdays as rows, time
 * running left to right, and a value carried by how dark a square is. Two
 * products of the line asked for it by name before it existed.
 *
 * **A cell has four meanings and only one of them is a number.** Nothing
 * recorded, a value, something still under way, and a date outside the range
 * asked for are four different facts. A grid that paints the first as the
 * palest shade of the second tells the reader somebody did nothing on a day
 * nobody reported - a claim invented by the drawing. So each has its own
 * treatment: a value is filled from the heat ramp, nothing recorded is the
 * bare empty square, something under way is outlined rather than filled
 * (there is no figure to shade, and any fill would be a number nobody gave),
 * and a padding square is drawn faintest of all, because the caller never
 * asked about it.
 *
 * **The legend is not decoration.** The scale is relative - the darkest square
 * is the busiest day in *this* grid, not a standard - so the grid says what
 * its own ceiling is. Without that, five shades look like an absolute measure
 * of a full day, which is a thing this component has no opinion about.
 *
 * **Colour is never the only channel.** Every square carries its date and its
 * figure in words, on a `title` and as its accessible name: a grid of five
 * shades says nothing to a screen reader, and little to anyone who does not
 * separate five blues.
 */

export const activityHeatmapVariants = cva('inline-flex flex-col gap-2', {
  variants: {
    size: {
      /* The year view, where a square is small enough that 53 columns fit. */
      sm: '[--cell:10px] [--gap:2px]',
      /* A quarter or a month, where there is room to hover comfortably. */
      md: '[--cell:14px] [--gap:3px]',
    },
  },
  defaultVariants: { size: 'md' },
})

export const activityCellVariants = cva('rounded-[3px]', {
  variants: {
    kind: {
      /* The bare square. Not the faintest step of the ramp - that is a value,
       * and this is the absence of one. */
      none: 'bg-soft',
      value: '',
      /* Outlined rather than filled: under way has no total to shade. */
      partial: 'border border-dashed border-accent/60',
      /* Drawn, because the column has to be seven tall, but never as data:
       * the caller did not ask about this date. */
      outside: 'bg-softer/40',
    },
    step: {
      1: 'bg-heat-1',
      2: 'bg-heat-2',
      3: 'bg-heat-3',
      4: 'bg-heat-4',
      5: 'bg-heat-5',
    },
  },
  defaultVariants: { kind: 'none' },
})

export interface ActivityHeatmapProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    VariantProps<typeof activityHeatmapVariants> {
  /** What is known about each date. Dates with no entry are drawn as nothing
   * recorded, which is a different fact from a value of zero. */
  entries: ActivityEntry[]
  /** First date of the range, `YYYY-MM-DD`. */
  from: string
  /** Last date. */
  to: string
  /** The day a week starts on, Sunday-first like `Date#getUTCDay`. Monday by
   * default. It decides which row a date lands on, so it is stated rather than
   * guessed from a locale this cannot see. */
  weekStartsOn?: Weekday
  /** The ceiling the shades are measured against. Defaults to the largest
   * value present; state it to compare two grids by eye. */
  busiest?: number
  /** What the grid as a whole is, for a reader who cannot see it. */
  label: string
  /** What one square says. Given the cell, returns the sentence that becomes
   * its hover title and its accessible name - the caller owns it because only
   * the caller knows whether a value is hours, words or commits. */
  describe: (cell: Cell) => string
  /** Row labels, one per weekday in drawing order. Omitted entirely rather
   * than defaulted: a weekday name is a word in a language this cannot pick. */
  weekdayLabel?: (weekday: Weekday) => ReactNode
}

export function ActivityHeatmap({
  entries,
  from,
  to,
  weekStartsOn = 1,
  busiest,
  label,
  describe,
  weekdayLabel,
  size,
  className,
  ...props
}: ActivityHeatmapProps) {
  const columns = weeks(entries, { from, to, weekStartsOn, busiest })
  const rows = weekdayRows(weekStartsOn)

  return (
    <div className={cn(activityHeatmapVariants({ size }), className)} {...props}>
      <div className="flex gap-[var(--gap)]" role="img" aria-label={label}>
        {weekdayLabel !== undefined && (
          <div
            className="mr-1 flex flex-col gap-[var(--gap)] text-[10px] leading-[var(--cell)] text-faint"
            aria-hidden
          >
            {rows.map((weekday) => (
              <span key={weekday} className="h-[var(--cell)]">
                {weekdayLabel(weekday)}
              </span>
            ))}
          </div>
        )}

        {columns.map((column) => (
          <div key={column[0]!.date} className="flex flex-col gap-[var(--gap)]">
            {column.map((cell) => (
              <span
                key={cell.date}
                title={describe(cell)}
                className={cn(
                  'size-[var(--cell)]',
                  activityCellVariants({
                    kind: cell.kind,
                    step: cell.step as 1 | 2 | 3 | 4 | 5 | undefined,
                  }),
                )}
              />
            ))}
          </div>
        ))}
      </div>
    </div>
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cn } from 'dowel-ui'
import { activityCellVariants } from './activity-heatmap'
import { STEPS } from './activity-weeks'

/*
 * What the shades mean, in the same tokens the grid paints with.
 *
 * Separate from the grid because a caller showing three grids on one screen
 * wants one legend, and because the words in it are the product's.
 */
export interface ActivityLegendProps extends HTMLAttributes<HTMLDivElement> {
  /** The word at the faint end - "less", usually. */
  less: ReactNode
  /** The word at the dark end. */
  more: ReactNode
  /** What the darkest square stands for, in words: the scale is relative, and
   * without this the shades read as an absolute measure. Omitted when there is
   * no value in the grid to be busiest. */
  busiest?: ReactNode
  /** The other three meanings, each named. Omitted one at a time by a caller
   * whose data cannot produce that kind. */
  none?: ReactNode
  partial?: ReactNode
}

export function ActivityLegend({
  less,
  more,
  busiest,
  none,
  partial,
  className,
  ...props
}: ActivityLegendProps) {
  return (
    <div
      className={cn('flex flex-wrap items-center gap-x-5 gap-y-2 text-[11px] text-faint', className)}
      {...props}
    >
      <span className="flex items-center gap-1.5">
        <span>{less}</span>
        {Array.from({ length: STEPS }, (_, index) => (
          <span
            key={index}
            className={cn('size-3', activityCellVariants({ kind: 'value', step: (index + 1) as 1 | 2 | 3 | 4 | 5 }))}
          />
        ))}
        <span>{more}</span>
        {busiest !== undefined && <span className="ml-1">· {busiest}</span>}
      </span>

      {none !== undefined && (
        <span className="flex items-center gap-1.5">
          <span className={cn('size-3', activityCellVariants({ kind: 'none' }))} />
          {none}
        </span>
      )}

      {partial !== undefined && (
        <span className="flex items-center gap-1.5">
          <span className={cn('size-3', activityCellVariants({ kind: 'partial' }))} />
          {partial}
        </span>
      )}
    </div>
  )
}

/*
 * Laying a run of dates out in weeks, with no React in it.
 *
 * Split out for the reason `table-sort` and `track-segments` are - a product
 * that draws this somewhere other than the DOM needs the arithmetic, not a
 * component. One of the line's consumers draws it in a terminal.
 *
 * The rule the whole grid rests on, and the one worth stating loudest:
 * **a cell has four meanings and only one of them is a number.** Nothing
 * recorded, a value, a day still in progress, and a date outside the range
 * asked for are four different facts. A grid that paints "nothing recorded" as
 * the palest shade of "a value" tells the reader somebody did nothing on a day
 * nobody reported - which is a claim invented by the drawing.
 */

/** What one square of the grid is. */
export type CellKind =
  /** No entry for this date. Not zero - no data at all. */
  | 'none'
  /** An entry with a figure behind it. */
  | 'value'
  /** Under way, with no total yet: today's row, a day still open. */
  | 'partial'
  /** A date the grid draws to keep its shape, outside the range asked for. */
  | 'outside'

/** What the caller knows about one date. */
export interface ActivityEntry {
  /** `YYYY-MM-DD`. A label, never a moment: no zone shifts a date here. */
  date: string
  /** The figure. `null` for a day under way, which has no total yet. */
  value: number | null
}

export interface Cell {
  date: string
  kind: CellKind
  value: number | null
  /** Which of the five steps this lands on, 1-5; `null` unless `kind` is
   * `value`. Discrete rather than continuous, because five shades can be told
   * apart and matched against a legend where a smooth gradient can only say
   * "more" and "less". */
  step: number | null
  /** Saturday or Sunday, read from the date itself.
   *
   * Only the weekend, never "a day off": which days someone actually rests is
   * a calendar this does not have, and guessing would mark an ordinary
   * Saturday shift as unusual. */
  weekend: boolean
}

/** Five steps, and the reason there are five: a legend a reader can count. */
export const STEPS = 5

/** Sunday-first, because that is what `Date#getUTCDay` counts from. */
export type Weekday = 0 | 1 | 2 | 3 | 4 | 5 | 6

const DAY = 86_400_000

function parse(date: string): number {
  return Date.parse(`${date}T00:00:00Z`)
}

function format(time: number): string {
  return new Date(time).toISOString().slice(0, 10)
}

/** Every date from `from` to `to` inclusive, as `YYYY-MM-DD`.
 *
 * Stepped through UTC so no local zone can shift a day: a date here is a
 * label, not a moment. */
export function datesBetween(from: string, to: string): string[] {
  const start = parse(from)
  const end = parse(to)
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) return []

  const dates: string[] = []
  for (let time = start; time <= end; time += DAY) dates.push(format(time))
  return dates
}

export function isWeekend(date: string): boolean {
  const day = new Date(parse(date)).getUTCDay()
  return day === 0 || day === 6
}

export interface WeeksOptions {
  /** First date of the range the caller asked for. */
  from: string
  /** Last date. */
  to: string
  /** The day a week starts on. Monday in most of the world, Sunday in the US -
   * and it changes which column a date lands in, so it is stated rather than
   * guessed from a locale the grid cannot see. */
  weekStartsOn?: Weekday
  /** The ceiling the steps are measured against. Defaults to the largest value
   * present.
   *
   * Shared rather than per-column, so two grids can be compared: scaled to
   * itself, a quiet month and a heavy one each get their own darkest square,
   * which is the one thing a heatmap is for. */
  busiest?: number
}

/**
 * The range as columns of weeks, each column seven cells from the top.
 *
 * Columns rather than rows because that is the shape the grid is read in: a
 * week is a column, a weekday is a row, and time runs left to right.
 *
 * The first and last columns are padded to seven with `outside` cells, so
 * every column is the same height and a weekday stays on its own row. They are
 * not "no data" - the caller never asked about them - and drawing them as
 * empty squares would add days to the range that the reader did not request.
 */
export function weeks(entries: ActivityEntry[], options: WeeksOptions): Cell[][] {
  const { from, to, weekStartsOn = 1 } = options
  const dates = datesBetween(from, to)
  if (dates.length === 0) return []

  const byDate = new Map(entries.map((entry) => [entry.date, entry]))

  const values = entries
    .map((entry) => entry.value)
    .filter((value): value is number => value !== null && Number.isFinite(value))
  const busiest = options.busiest ?? (values.length > 0 ? Math.max(...values) : 0)

  const cellFor = (date: string): Cell => {
    const entry = byDate.get(date)
    const weekend = isWeekend(date)

    if (entry === undefined) return { date, kind: 'none', value: null, step: null, weekend }
    if (entry.value === null) return { date, kind: 'partial', value: null, step: null, weekend }

    return { date, kind: 'value', value: entry.value, step: stepFor(entry.value, busiest), weekend }
  }

  const outside = (date: string): Cell => ({
    date,
    kind: 'outside',
    value: null,
    step: null,
    weekend: isWeekend(date),
  })

  /* Where the first date sits in its own week, so the run starts on the right
   * row rather than at the top of the first column. */
  const columnOf = (date: string) => (new Date(parse(date)).getUTCDay() - weekStartsOn + 7) % 7

  const columns: Cell[][] = []
  let column: Cell[] = []

  // Pad the head, back-dating the squares so each one is the date it stands
  // for - a reader hovering the first column should not find a blank.
  const lead = columnOf(dates[0]!)
  for (let i = lead; i > 0; i--) column.push(outside(format(parse(dates[0]!) - i * DAY)))

  for (const date of dates) {
    column.push(cellFor(date))
    if (column.length === 7) {
      columns.push(column)
      column = []
    }
  }

  if (column.length > 0) {
    const last = parse(dates.at(-1)!)
    for (let i = 1; column.length < 7; i++) column.push(outside(format(last + i * DAY)))
    columns.push(column)
  }

  return columns
}

/**
 * Which step a value lands on, 1 to `STEPS`.
 *
 * The floor is 1 rather than 0: any value at all is a value, and a square
 * indistinguishable from an empty one would file a twenty-minute day under
 * "nothing recorded" - the confusion this module exists to prevent. A value of
 * zero is the exception, and it is the caller's own statement: zero measured is
 * not the same as nothing measured, and it still earns the faintest step.
 */
export function stepFor(value: number, busiest: number): number {
  /* No ceiling to measure against. That happens two ways and they mean
   * opposite things: a caller who stated no `busiest` and whose only values
   * are zero (every day measured, every day empty - the faintest step, because
   * that is what they are), or a caller who stated a ceiling of zero while
   * sending a real figure (the ceiling is wrong, and the figure is all the
   * grid has - the darkest, so it is not hidden). */
  if (!(busiest > 0)) return value > 0 ? STEPS : 1
  const share = Math.min(1, Math.max(0, value / busiest))
  return Math.max(1, Math.ceil(share * STEPS))
}

/** The weekday rows, in the order the grid draws them, as offsets from Sunday.
 *
 * Returned rather than assumed so a caller labelling the rows and a grid
 * drawing them cannot disagree about which row is Monday. */
export function weekdayRows(weekStartsOn: Weekday = 1): Weekday[] {
  return [0, 1, 2, 3, 4, 5, 6].map((offset) => ((weekStartsOn + offset) % 7) as Weekday)
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Alert.
 *
 * A message that stays on the screen, in the flow of the page, about the thing
 * next to it: this field could not be saved, this profile has no axes yet,
 * this export is out of date.
 *
 * Not a Toast, and the difference is worth stating because products keep
 * reaching for the wrong one. A toast is for something that just happened and
 * then goes away; an alert is for a condition that is still true and will
 * still be true after a reload. If dismissing it would be a lie, it is an
 * alert.
 *
 * Not a Banner either: a banner spans the application and speaks about the
 * whole of it. This speaks about what it sits beside.
 *
 * `role` is the caller's decision, and the default is deliberately quiet. An
 * alert that appears in response to something the reader just did should be
 * `role="alert"` so it is announced; one that is simply part of the page
 * should not be, or a screen reader interrupts itself reading the furniture.
 */

export const alertVariants = cva(
  ['flex gap-2.5 rounded-md border p-3 text-sm', '[&_svg]:mt-0.5 [&_svg]:size-4 [&_svg]:shrink-0'],
  {
    variants: {
      tone: {
        neutral: 'border-line bg-soft text-dim',
        good: 'border-good/40 bg-good-soft text-good',
        warn: 'border-warn/40 bg-warn-soft text-warn',
        bad: 'border-bad/40 bg-bad-soft text-bad',
        info: 'border-info/40 bg-info-soft text-info',
      },
    },
    defaultVariants: { tone: 'neutral' },
  },
)

export interface AlertProps
  // `title` on a div is the browser's tooltip and is a string; here it is the
  // heading, and can be anything a product wants to draw.
  extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>,
    VariantProps<typeof alertVariants> {
  /** Drawn before the text. The product's own, because an icon that means
   * "warning" here should be the one it means everywhere else in the product. */
  icon?: ReactNode
  /** The heading. Optional: a one-line alert does not need one. */
  title?: ReactNode
  /** Anything that goes at the end - a link to the thing that fixes it, a
   * dismiss button the product owns. */
  action?: ReactNode
}

export function Alert({ tone, icon, title, action, className, children, ...props }: AlertProps) {
  return (
    <div className={cn(alertVariants({ tone }), className)} {...props}>
      {icon}
      <div className="min-w-0 flex-1">
        {title !== undefined && <div className="font-semibold">{title}</div>}
        {children !== undefined && (
          <div className={cn('text-xs', title !== undefined && 'mt-0.5')}>{children}</div>
        )}
      </div>
      {action !== undefined && <div className="shrink-0">{action}</div>}
    </div>
  )
}

