import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Columns over a baseline: one period, one bar.
 *
 * Bars rather than a line, and the distinction is the data's not the
 * drawing's: a line says the value exists between the points, a column says
 * each period is its own sum. Hours worked in a week is a sum - there is no
 * "Wednesday afternoon" reading between two weeks - so it is a column.
 *
 * **The chart owns its height in pixels.** That is not a style choice, it is
 * the defect this component exists to prevent. The first consumer drew its
 * bars as a percentage of the parent, inside a flex row sized from its own
 * content: the child had no base to be a percentage of, every bar computed to
 * zero, and the chart shipped as a row of bare axis labels. No test and no API
 * check could see it - the owner found it by looking, and it cost a patch
 * release. Here the plot is a stated number of pixels and a bar is a
 * percentage of *that*.
 *
 * **An absent period is not a short one.** A week with nothing recorded and a
 * week of twenty minutes are different facts, and a bar of no height says
 * neither - it reads as a bar that failed to render. So a gap keeps its place
 * in the row and is drawn as a mark of its own.
 *
 * Interaction is one `title` per column rather than a tooltip layer: this is a
 * small chart that sits inside a panel, and the numbers it holds also belong
 * in the list beside it. A reader who needs them exactly should not have to
 * hover to find out.
 */

export const barChartVariants = cva('flex items-end gap-1 border-b border-chart-axis', {
  variants: {
    size: {
      /* Inside a panel, beside other things. */
      sm: '[--plot:72px]',
      /* On its own, where the shape is the subject. */
      md: '[--plot:112px]',
    },
  },
  defaultVariants: { size: 'md' },
})

export const barVariants = cva('mx-auto w-3/5 max-w-6 rounded-t-[4px]', {
  variants: {
    tone: {
      accent: 'bg-accent',
      /* For a bar that is one of several series, or one the caller is
       * highlighting against the rest. */
      series: 'bg-series-1',
      good: 'bg-good',
      warn: 'bg-warn',
      bad: 'bg-bad',
      /* The rest of the field, when one bar is the story: emphasis is the
       * most underused form in a chart of eight equal colours. */
      muted: 'bg-line-2',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export interface BarDatum {
  /** Distinguishes this column from its neighbours. */
  key: string
  /** The period's own sum. `null` is a period with nothing recorded, which is
   * not the same as a sum of zero and is not drawn as a bar. */
  value: number | null
  /** What goes under the column. Kept short - these labels sit at a width the
   * chart does not control. */
  label: ReactNode
  tone?: NonNullable<VariantProps<typeof barVariants>['tone']>
  /** What the column says, for a reader hovering it and for a screen reader.
   * Required per bar, because a rectangle announces nothing. */
  title: string
}

export interface BarChartProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    VariantProps<typeof barChartVariants> {
  bars: BarDatum[]
  /** The top of the scale. Defaults to the tallest bar present; state it to
   * compare two charts, or to hold a scale still while the data moves. */
  max?: number
  /** What the whole chart is, in words. */
  label: string
}

/** The shortest a bar may be drawn, as a percentage of the plot.
 *
 * A twenty-minute week against a forty-hour one is half a percent, which
 * rounds to nothing: the period was recorded and would simply not be there. */
const MIN_BAR = 3

export function BarChart({ bars, max, label, size, className, ...props }: BarChartProps) {
  const values = bars.map((bar) => bar.value).filter((value): value is number => value !== null)
  /* A ceiling of at least one, so a chart of nothing but zeroes divides
   * safely and draws a row of floors rather than nothing at all. */
  const ceiling = Math.max(max ?? 0, ...values, 1)

  return (
    <div className={cn(barChartVariants({ size }), className)} role="img" aria-label={label} {...props}>
      {bars.map((bar) => (
        <div key={bar.key} className="flex min-w-0 flex-1 flex-col items-center gap-1.5">
          {/* The track carries the height itself. See the note above: a
            * percentage against a parent that has no height of its own
            * resolves to zero, and the chart disappears without failing. */}
          <div className="flex h-[var(--plot)] w-full items-end" title={bar.title}>
            {bar.value === null ? (
              /* A gap, drawn as one. A bar of no height is indistinguishable
               * from a bar that did not render, and closing the gap up would
               * turn an absence into continuity - the one thing a trend must
               * not do. */
              <div className="mx-auto h-1 w-3/5 max-w-6 rounded-t-[4px] border-x border-t border-line-2" />
            ) : (
              <div
                className={cn(barVariants({ tone: bar.tone }))}
                style={{ height: `${Math.max((bar.value / ceiling) * 100, MIN_BAR)}%` }}
              />
            )}
          </div>
          <span className="w-full truncate text-center text-[10px] text-faint tabular-nums">
            {bar.label}
          </span>
        </div>
      ))}
    </div>
  )
}

/*
 * A line across the plot, at a value on the same scale.
 *
 * For the number every bar is read against - a median, a target, an agreed
 * norm. A chart without its baseline invites the reader to invent one, and the
 * one they invent is usually the tallest bar.
 *
 * Drawn as a solid hairline rather than a dash: a dashed rule reads as
 * "projected" or "threshold" when it is neither, and the doctrine is explicit
 * that grid and axis lines are solid.
 */
export interface BaselineProps extends HTMLAttributes<HTMLDivElement> {
  /** Where it sits, on the same scale as the bars. */
  value: number
  /** The same ceiling the chart is drawn against. */
  max: number
  /** What the line is, beside it. */
  children?: ReactNode
}

export function Baseline({ value, max, children, className, ...props }: BaselineProps) {
  if (!(max > 0) || value < 0 || value > max) return null

  return (
    <div
      className={cn('pointer-events-none absolute inset-x-0 flex items-center gap-2', className)}
      style={{ bottom: `${(value / max) * 100}%` }}
      {...props}
    >
      {/* The rule stops short of the label rather than running under it: a
        * hairline crossing its own caption reads as a strikethrough. */}
      <div className="h-px flex-1 bg-chart-grid" />
      {children !== undefined && (
        <span className="shrink-0 text-[10px] leading-none text-faint tabular-nums">{children}</span>
      )}
    </div>
  )
}

/*
 * The box a chart and its baseline share.
 *
 * Two things it does, and both are the component's job rather than the
 * caller's. It establishes the positioning context the baseline needs - left
 * to the caller that is a `relative` remembered or forgotten, and forgotten it
 * puts the rule at the bottom of the page. And it keeps a gutter on the right
 * for the baseline's label, which otherwise sits on top of the last columns:
 * the label is outside the plot, so the plot has to end before it starts.
 */
export interface ChartFrameProps extends HTMLAttributes<HTMLDivElement> {
  /** Room on the right for the baseline's label. Omit it where there is no
   * baseline, or where the label is short enough to live in the panel's own
   * padding. */
  gutter?: boolean
  children: ReactNode
}

export function ChartFrame({ gutter = true, className, ...props }: ChartFrameProps) {
  return <div className={cn('relative', gutter && 'pr-16', className)} {...props} />
}

import type { ButtonHTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { useRender } from '@base-ui/react/use-render'
// `cn` comes from the package rather than being copied in beside the
// component (ADR 0002): a helper every primitive shares should update
// centrally, and a project installing a component already has the package for
// the theme. shadcn's own components import it from `@/lib/utils`; that is a
// per-project alias, and a copied file cannot know what it points at.
import { cn } from 'dowel-ui'

/*
 * Button.
 *
 * Five variants, because that is what the line's products actually reach for:
 * one primary action per screen, a quiet default, a soft accent for something
 * selected, a destructive one, and an icon-only.
 *
 * Every colour and every size is a token. There are no `dark:` utilities and
 * no raw values - the theme swaps underneath, so the same class list is
 * correct in both themes and in every product's accent.
 */
export const buttonVariants = cva(
  [
    'inline-flex cursor-pointer items-center justify-center gap-1.5 whitespace-nowrap',
    'font-medium transition-colors',
    // Disabled is a state, not a colour: the button keeps its own hue and
    // loses contact instead, which reads the same whatever the accent is.
    'disabled:pointer-events-none disabled:opacity-50',
    '[&_svg]:shrink-0',
  ],
  {
    variants: {
      variant: {
        primary: 'rounded-md bg-accent font-semibold text-on-accent hover:bg-accent-2',
        ghost: 'rounded-md border border-line text-dim hover:border-line-2 hover:text-text',
        soft: 'rounded-md bg-accent-soft text-accent hover:bg-accent-soft/60',
        danger: 'rounded-md text-bad hover:bg-bad-soft',
        icon: 'rounded-md text-dim hover:bg-soft hover:text-text',
      },
      size: {
        sm: 'h-7 px-2.5 text-xs',
        md: 'h-9 px-3.5 text-sm',
        'icon-sm': 'size-7 [&_svg]:size-3.5',
        'icon-md': 'size-8 [&_svg]:size-4',
      },
    },
    defaultVariants: { variant: 'ghost', size: 'md' },
  },
)

export interface ButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /**
   * Render something else with the button's clothes on - a link, most often.
   *
   * Takes the element itself rather than a boolean: `render={<a href="…" />}`.
   * A function is also accepted, for the rare case that needs the props
   * before deciding what to build with them.
   */
  render?: useRender.RenderProp
}

export function Button({ variant, size, render, className, type, ...props }: ButtonProps) {
  return useRender({
    render,
    defaultTagName: 'button',
    props: {
      // A `<button>` inside a form submits it unless told otherwise, which
      // surprises everyone once. When rendering as something else the
      // attribute is meaningless and would land on an `<a>`, so it is only
      // set for the element that has it - `render` is what says which.
      ...(render === undefined && type === undefined ? { type: 'button' } : { type }),
      className: cn(buttonVariants({ variant, size }), className),
      ...props,
    },
  })
}

/*
 * The arithmetic a calendar runs on, with no React in it.
 *
 * Split out of the Calendar because the size gate asked the right question:
 * the file was two and a half times over its ceiling, and the reason was that
 * it held two things - the sums, and the grid that draws them. These are the
 * sums, and they are what DatePicker, DateRangePicker and any product doing
 * its own date work import.
 *
 * Everything here takes and returns `YYYY-MM-DD`, and never a `Date`. A
 * birthday has no timezone; a release date has no hour. Put one in a `Date`
 * and it becomes a moment - and moments cross midnight when they are
 * serialised, which is how a date reaches a server a day early. The string is
 * what a database column holds and what JSON carries.
 *
 * `Date` appears inside, in two places only: to ask `Intl` for a name, and to
 * add days. Both are wrapped here, so no caller ever holds one.
 *
 * No date library, deliberately. `react-day-picker` is good and would bring
 * `date-fns` and `@date-fns/tz` behind it - the first heavy dependency in a
 * set that is otherwise Base UI or nothing. `Intl` already knows the part a
 * library would be consulted for: which day the week starts on here, and what
 * the months are called. The rest is the arithmetic below, and it is only
 * hard when a date is stored as a moment.
 */

/** A calendar date: `2026-09-02`. Not a moment - no time, no zone. */
export type IsoDate = string

/** Whether a string is a calendar date this component can work with, and one
 * that actually exists. `2026-02-31` parses arithmetically and is not a day. */
export function isIsoDate(value: string): value is IsoDate {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false
  const [year, month, day] = value.split('-').map(Number) as [number, number, number]
  if (month < 1 || month > 12 || day < 1) return false
  return day <= daysInMonth(year, month)
}

/** How many days that month has. The leap rule in full, because the
 * hundred-year exception is the part that gets left out. */
export function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0
    return leap ? 29 : 28
  }
  return [4, 6, 9, 11].includes(month) ? 30 : 31
}

/** Today, as a calendar date in the reader's own timezone.
 *
 * Deliberately not `new Date().toISOString().slice(0, 10)`, which is the
 * common spelling and is wrong: that converts to UTC first, so anyone east of
 * Greenwich late in the evening gets tomorrow. */
export function today(): IsoDate {
  const now = new Date()
  return format(now.getFullYear(), now.getMonth() + 1, now.getDate())
}

function format(year: number, month: number, day: number): IsoDate {
  return `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
}

interface Parts {
  year: number
  month: number
  day: number
}

export function parts(date: IsoDate): Parts {
  const [year, month, day] = date.split('-').map(Number) as [number, number, number]
  return { year, month, day }
}

/** The same date shifted by whole days. Goes through a `Date` at noon rather
 * than midnight: a shift over a daylight-saving boundary at midnight can land
 * on the same calendar day it started from. */
export function addDays(date: IsoDate, days: number): IsoDate {
  const { year, month, day } = parts(date)
  const moved = new Date(year, month - 1, day, 12)
  moved.setDate(moved.getDate() + days)
  return format(moved.getFullYear(), moved.getMonth() + 1, moved.getDate())
}

/** The same day-of-month in another month, clamped when it does not exist
 * there: a step back from 31 March lands on 28 February, not on 3 March. */
export function addMonths(date: IsoDate, months: number): IsoDate {
  const { year, month, day } = parts(date)
  const zero = year * 12 + (month - 1) + months
  const nextYear = Math.floor(zero / 12)
  const nextMonth = (zero % 12) + 1
  return format(nextYear, nextMonth, Math.min(day, daysInMonth(nextYear, nextMonth)))
}

/** Which weekday a date falls on, as `Intl` numbers them: 1 is Monday, 7 is
 * Sunday. `Date` numbers Sunday 0, which does not sort and does not match
 * what `getWeekInfo` returns. */
export function weekday(date: IsoDate): number {
  const { year, month, day } = parts(date)
  const js = new Date(year, month - 1, day, 12).getDay()
  return js === 0 ? 7 : js
}

/** Which day the week starts on here: 1 Monday, 7 Sunday.
 *
 * `getWeekInfo` is the current spelling and `weekInfo` the older one; some
 * engines have neither, and Monday is the majority answer worldwide. */
export function firstDayOfWeek(locale: string | undefined): number {
  try {
    const info = new Intl.Locale(locale ?? navigator.language) as Intl.Locale & {
      getWeekInfo?: () => { firstDay: number }
      weekInfo?: { firstDay: number }
    }
    return info.getWeekInfo?.().firstDay ?? info.weekInfo?.firstDay ?? 1
  } catch {
    return 1
  }
}

/** The grid of a month: whole weeks, starting on the locale's first day, with
 * the days either side included so every row has seven.
 *
 * Returned as dates rather than as numbers, so a cell never has to be told
 * which month it belongs to - it knows, and a click on a trailing day works
 * without a special case. */
export function monthGrid(month: IsoDate, locale?: string): IsoDate[][] {
  const { year, month: monthNumber } = parts(month)
  const first = format(year, monthNumber, 1)
  const start = firstDayOfWeek(locale)

  // How far back the grid starts: the distance from the first of the month
  // back to the most recent week start.
  const lead = (weekday(first) - start + 7) % 7
  const origin = addDays(first, -lead)

  const weeks: IsoDate[][] = []
  let cursor = origin
  // Six rows always, so the calendar does not change height between months -
  // a popup that resizes as you page through it is one that moves under the
  // pointer.
  for (let week = 0; week < 6; week += 1) {
    const row: IsoDate[] = []
    for (let day = 0; day < 7; day += 1) {
      row.push(cursor)
      cursor = addDays(cursor, 1)
    }
    weeks.push(row)
  }
  return weeks
}

/** The weekday initials, in the order this locale lays them out. */
export function weekdayNames(locale: string | undefined, start: number): string[] {
  const names = new Intl.DateTimeFormat(locale, { weekday: 'short' })
  // Any week works; this one begins on a Monday.
  const monday = Date.UTC(2024, 0, 1)
  return Array.from({ length: 7 }, (_, index) => {
    const offset = (start - 1 + index) % 7
    return names.format(new Date(monday + offset * 86_400_000))
  })
}

import { useMemo, useState, type KeyboardEvent } from 'react'
import { cn } from 'dowel-ui'
import {
  addDays,
  addMonths,
  firstDayOfWeek,
  monthGrid,
  parts,
  today,
  weekday,
  weekdayNames,
  type IsoDate,
} from './calendar-math'

/*
 * Calendar - a month of days.
 *
 * The sums live next door in `calendar-math`, which has no React in it; this
 * is the grid that draws them and the keyboard that moves around it.
 *
 * One tab stop for the whole grid, arrows within - the arrangement a radio
 * group has, and the reason a calendar is usable at all: forty-two tab stops
 * is not a control. Arrows move a cursor and only Enter chooses, so a product
 * listening for a change does not receive five dates on the way to the sixth.
 */

export interface CalendarProps {
  /** The selected day, or `undefined` for none. */
  value?: IsoDate
  onValueChange?: (value: IsoDate) => void
  /** Which month is shown. Uncontrolled unless given. */
  month?: IsoDate
  onMonthChange?: (month: IsoDate) => void
  /** Bounds, inclusive. A day outside them cannot be chosen. */
  min?: IsoDate
  max?: IsoDate
  /** For a range: the other end, so the days between can be shaded. */
  rangeEnd?: IsoDate
  /** Formats the names. Left alone it is the reader's own. */
  locale?: string
  /** What the grid is called, for a screen reader. */
  'aria-label'?: string
  /** Names the buttons that page the months. Required: they are icons, and an
   * icon with no name is a button that announces nothing. */
  previousMonthLabel: string
  nextMonthLabel: string
  className?: string
}

export function Calendar({
  value,
  onValueChange,
  month,
  onMonthChange,
  min,
  max,
  rangeEnd,
  locale,
  previousMonthLabel,
  nextMonthLabel,
  className,
  'aria-label': ariaLabel,
}: CalendarProps) {
  const [ownMonth, setOwnMonth] = useState<IsoDate>(() => value ?? today())
  const shown = month ?? ownMonth

  /* Which day the keyboard is on. It is not the selection: arrowing around a
   * calendar moves a cursor, and only Enter chooses - otherwise every arrow
   * key would fire `onValueChange` and a product listening for it would save
   * five dates on the way to the sixth. */
  const [focused, setFocused] = useState<IsoDate>(() => value ?? today())

  const weeks = useMemo(() => monthGrid(shown, locale), [shown, locale])
  const start = firstDayOfWeek(locale)
  const names = useMemo(() => weekdayNames(locale, start), [locale, start])
  const heading = useMemo(
    () => new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(
      new Date(parts(shown).year, parts(shown).month - 1, 1),
    ),
    [shown, locale],
  )
  const dayNumber = useMemo(() => new Intl.DateTimeFormat(locale, { day: 'numeric' }), [locale])
  const fullDate = useMemo(
    () => new Intl.DateTimeFormat(locale, { dateStyle: 'long' }),
    [locale],
  )

  const outOfBounds = (date: IsoDate) =>
    (min !== undefined && date < min) || (max !== undefined && date > max)

  const goToMonth = (next: IsoDate) => {
    if (month === undefined) setOwnMonth(next)
    onMonthChange?.(next)
  }

  const moveFocus = (next: IsoDate) => {
    setFocused(next)
    // Paging follows the cursor: arrowing off the end of a month shows the
    // next one rather than moving to a day nobody can see.
    if (parts(next).month !== parts(shown).month || parts(next).year !== parts(shown).year) {
      goToMonth(next)
    }
  }

  const onKeyDown = (event: KeyboardEvent) => {
    const jump: Record<string, () => IsoDate> = {
      ArrowRight: () => addDays(focused, 1),
      ArrowLeft: () => addDays(focused, -1),
      ArrowDown: () => addDays(focused, 7),
      ArrowUp: () => addDays(focused, -7),
      PageDown: () => addMonths(focused, 1),
      PageUp: () => addMonths(focused, -1),
      Home: () => addDays(focused, -((weekday(focused) - start + 7) % 7)),
      End: () => addDays(focused, 6 - ((weekday(focused) - start + 7) % 7)),
    }

    const move = jump[event.key]
    if (move) {
      event.preventDefault()
      moveFocus(move())
      return
    }

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      if (!outOfBounds(focused)) onValueChange?.(focused)
    }
  }

  const now = today()

  return (
    <div className={cn('w-64 select-none', className)}>
      <div className="mb-2 flex items-center justify-between gap-1">
        <button
          type="button"
          aria-label={previousMonthLabel}
          onClick={() => goToMonth(addMonths(shown, -1))}
          className={cn(
            'flex size-7 items-center justify-center rounded-md text-dim',
            'transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" className="size-4" aria-hidden>
            <path
              d="M10 3L5 8l5 5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>

        {/* The month is announced when it changes, so paging with the arrows
          * says where you have arrived rather than moving silently. */}
        <div aria-live="polite" className="text-sm font-medium text-text">
          {heading}
        </div>

        <button
          type="button"
          aria-label={nextMonthLabel}
          onClick={() => goToMonth(addMonths(shown, 1))}
          className={cn(
            'flex size-7 items-center justify-center rounded-md text-dim',
            'transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" className="size-4" aria-hidden>
            <path
              d="M6 3l5 5-5 5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      </div>

      {/* One tab stop for the whole grid, and the arrows move within it - the
        * arrangement a radio group has, and the reason a calendar is usable at
        * all: forty-two tab stops is not a control. */}
      <div
        role="grid"
        aria-label={ariaLabel}
        tabIndex={0}
        onKeyDown={onKeyDown}
        className={cn(
          'rounded-md',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        )}
      >
        <div role="row" className="mb-1 grid grid-cols-7">
          {names.map((name) => (
            <div
              key={name}
              role="columnheader"
              aria-label={name}
              className="py-1 text-center text-2xs uppercase tracking-caption text-faint"
            >
              {name}
            </div>
          ))}
        </div>

        {weeks.map((week) => (
          <div role="row" key={week[0]} className="grid grid-cols-7">
            {week.map((date) => {
              const outside = parts(date).month !== parts(shown).month
              const disabled = outOfBounds(date)
              const selected =
                value !== undefined &&
                (rangeEnd === undefined
                  ? date === value
                  : date === value || date === rangeEnd)
              const inRange =
                value !== undefined && rangeEnd !== undefined && date > value && date < rangeEnd

              return (
                <div role="gridcell" key={date} aria-selected={selected || undefined}>
                  <button
                    type="button"
                    // Not a tab stop: the grid is the control. Announced with
                    // its full date, because "14" on its own is not a date.
                    tabIndex={-1}
                    disabled={disabled}
                    aria-label={fullDate.format(new Date(parts(date).year, parts(date).month - 1, parts(date).day))}
                    aria-current={date === now ? 'date' : undefined}
                    onClick={() => {
                      setFocused(date)
                      if (!disabled) onValueChange?.(date)
                    }}
                    className={cn(
                      'flex h-8 w-full items-center justify-center rounded-md text-sm tabular-nums',
                      'transition-colors',
                      outside ? 'text-faint' : 'text-text',
                      inRange && 'bg-accent-soft',
                      selected && 'bg-accent font-medium text-on-accent',
                      !selected && !disabled && 'hover:bg-soft',
                      date === now && !selected && 'font-medium text-accent',
                      date === focused && 'ring-1 ring-line-2',
                      disabled && 'cursor-not-allowed opacity-40',
                    )}
                  >
                    {dayNumber.format(new Date(parts(date).year, parts(date).month - 1, parts(date).day))}
                  </button>
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

import type { HTMLAttributes, MouseEvent } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Chip.
 *
 * A badge you can act on: a filter that can be removed, a tag with a count, a
 * selected value in a field. The difference from a Badge is entirely about
 * whether something happens when you click it - and if something does, that
 * part is a real `<button>` with a real label, not a decorative cross.
 *
 * `onRemove` is the reason this exists separately. Every product wrote the
 * same removable tag and every one of them made the cross a `<span>`, which
 * the keyboard cannot reach and a screen reader does not announce.
 */
export const chipVariants = cva(
  'inline-flex items-center gap-1 rounded-full border py-0.5 pl-2.5 text-xs whitespace-nowrap transition-colors',
  {
    variants: {
      variant: {
        outline: 'border-line text-dim',
        accent: 'border-transparent bg-accent-soft text-accent',
        soft: 'border-transparent bg-soft text-dim',
      },
      /** Padding on the right depends on whether a remove button sits there. */
      removable: {
        true: 'pr-1',
        false: 'pr-2.5',
      },
    },
    defaultVariants: { variant: 'outline', removable: false },
  },
)

export interface ChipProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, 'onSelect'>,
    Omit<VariantProps<typeof chipVariants>, 'removable'> {
  /** Shown after the label, for a count. */
  count?: number
}

/*
 * Removable, or not - and if removable, named.
 *
 * The two props travel together as a union rather than as two optionals, so
 * the type says what the component means: a remove button exists only when
 * there is a word for it. There is no default word on purpose. A string the
 * component invents is a string the product cannot translate, and it would
 * ship in English to every reader who does not read English.
 */
type Removable =
  | { onRemove: () => void; removeLabel: string }
  | { onRemove?: never; removeLabel?: never }

export function Chip({
  variant,
  count,
  onRemove,
  removeLabel,
  className,
  children,
  ...props
}: ChipProps & Removable) {
  return (
    <span className={cn(chipVariants({ variant, removable: Boolean(onRemove) }), className)} {...props}>
      {children}

      {count !== undefined && <span className="text-faint tabular-nums">{count}</span>}

      {onRemove && (
        <button
          type="button"
          aria-label={removeLabel}
          onClick={(event: MouseEvent<HTMLButtonElement>) => {
            // A chip is often inside something else that is also clickable.
            event.stopPropagation()
            onRemove()
          }}
          className={cn(
            'grid size-4 place-items-center rounded-full text-faint transition-colors',
            'hover:bg-line hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          )}
        >
          <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
            <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </span>
  )
}

import { useId, useState, type ReactNode } from 'react'
import { cn, lineProducts } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * ColorField.
 *
 * Picking a colour for something the product stores: a tag, a project, a
 * calendar. Note what that is *not* - it is not choosing the appearance of the
 * interface. The theme decides that, from one accent, and a field that let a
 * reader repaint the chrome would undo the argument the whole system rests on.
 *
 * So the palette comes first and the free field second. The swatches are the
 * line's own fourteen accents plus the four semantic tokens, which is the
 * vocabulary a product already speaks; a value picked there is a *name*
 * (`kilna`, `good`), not a hex, and it keeps meaning the right thing when the
 * theme changes underneath it.
 *
 * Free hex is available because the owner asked for it, and it is worth
 * saying why that does not contradict "no raw colours in components": the rule
 * is about a component hardcoding its own appearance. A colour the reader
 * chose for their own tag is the product's *data* - the same kind of thing as
 * the tag's name - and data does not come from a token vocabulary.
 *
 * The swatch is a real `<input type="radio">` per colour, in a `radiogroup`.
 * That is what makes the arrows walk the palette, what makes the choice
 * announce itself, and what makes the whole group one tab stop.
 */

/** The four semantic colours, which mean the same thing in every product. */
const SEMANTIC = ['good', 'warn', 'bad', 'info'] as const

/** Whether a string is a colour this field would accept as free input. Six
 * digits or three, with the hash - the two forms a reader actually types. */
export function isHexColor(value: string): boolean {
  return /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(value)
}

export interface ColorFieldProps {
  /** The chosen colour: a token name, or a hex string. */
  value: string
  onValueChange: (value: string) => void
  /** Whether the reader may type a colour of their own. */
  allowCustom?: boolean
  /** Names the palette for a screen reader. */
  'aria-label'?: string
  'aria-labelledby'?: string
  /** How a swatch is named. Takes the colour's name, so the product can say
   * "Lime" in its own language rather than shipping ours. */
  swatchLabel?: (name: string) => string
  /** The label on the free-entry box, when `allowCustom` is on. */
  customLabel?: ReactNode
  disabled?: boolean
  className?: string
}

export function ColorField({
  value,
  onValueChange,
  allowCustom,
  swatchLabel,
  customLabel,
  disabled,
  className,
  ...aria
}: ColorFieldProps) {
  const name = useId()
  const customId = useId()

  /* What is in the free box while it is being typed.
   *
   * It is not `value`: half of `#3fa9` is not a colour, and pushing every
   * keystroke up would either reject the reader mid-word or paint the product
   * a colour they were passing through. The box commits when what is in it is
   * a colour. */
  const [draft, setDraft] = useState(isHexColor(value) ? value : '')

  const swatches = [
    ...lineProducts.map((product) => ({ token: product.name, css: product.accent })),
    ...SEMANTIC.map((token) => ({ token, css: `var(--${token})` })),
  ]

  return (
    <div className={cn('flex flex-col gap-2', disabled && 'pointer-events-none opacity-50', className)}>
      <div role="radiogroup" {...aria} className="flex flex-wrap gap-1.5">
        {swatches.map((swatch) => {
          const chosen = value === swatch.token
          return (
            <label
              key={swatch.token}
              className={cn(
                'relative grid size-7 cursor-pointer place-items-center rounded-md border transition-colors',
                chosen ? 'border-accent' : 'border-line hover:border-dim',
                // The ring has to be on the label: the input itself is hidden,
                // so `focus-visible` on it would never be seen.
                'focus-within:outline-2 focus-within:outline-offset-1 focus-within:outline-accent',
              )}
            >
              <input
                type="radio"
                name={name}
                value={swatch.token}
                checked={chosen}
                disabled={disabled}
                onChange={() => onValueChange(swatch.token)}
                className="sr-only"
              />
              <span
                aria-hidden
                className="size-5 rounded"
                /* The one place a colour is set from a value rather than a
                 * class, because the value *is* the colour - a palette that
                 * could not show its own colours would be a list of words. */
                style={{ background: swatch.css }}
              />
              <span className="sr-only">{swatchLabel?.(swatch.token) ?? swatch.token}</span>
            </label>
          )
        })}
      </div>

      {allowCustom && (
        <div className="flex items-center gap-2">
          <label htmlFor={customId} className="text-xs text-dim">
            {customLabel}
          </label>
          <input
            id={customId}
            value={draft}
            disabled={disabled}
            /* No placeholder of its own.
             *
             * The obvious one is a specimen hex, and the lint rule that
             * forbids raw colours flags it - correctly, by the letter. Rather
             * than widen a gate that catches real violations for the sake of
             * one string, the format is shown by the monospace box and named
             * by `customLabel`, which is the product's word anyway. */
            spellCheck={false}
            onChange={(event) => {
              const next = event.target.value
              setDraft(next)
              // Committed only once it is a colour. Anything else is a word in
              // progress, and the product should not be repainted by one.
              if (isHexColor(next)) onValueChange(next)
            }}
            className={cn(fieldClasses, 'h-8 w-28 font-mono text-xs')}
          />
          <span
            aria-hidden
            className="size-5 shrink-0 rounded border border-line"
            style={{ background: isHexColor(draft) ? draft : 'transparent' }}
          />
        </div>
      )}
    </div>
  )
}

import type { Ref } from 'react'
import { Combobox as Base } from '@base-ui/react/combobox'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { selectItemVariants, selectPopupVariants } from './select'

/*
 * Combobox.
 *
 * A Select you can type in. The list narrows as the query is typed, which is
 * the only difference that matters and the reason to reach for this one: a
 * Select stops being usable somewhere around thirty options, and a country
 * picker or a tag field is well past that.
 *
 * Everything the Select comment says about the native element applies here
 * too - there is no `<select>` under it, and the input is a real `<input
 * role="combobox">` so autofill, spellcheck and the phone keyboard still
 * work.
 *
 * Filtering is Base UI's: give the root an `items` array and it matches the
 * query against them with `Intl.Collator`, so accents and case behave the way
 * a reader in that language expects rather than the way `toLowerCase` does.
 * `filter` replaces the comparison; `filter={null}` turns it off for a list
 * that is filtered on a server.
 *
 * The chips are Base UI's too - Chips, Chip, ChipRemove - and that is worth
 * saying because inventing them is the obvious move and it goes wrong in one
 * specific way: hand-made chips end up as `<div>`s with an X that only a
 * pointer can reach, and the multi-select becomes keyboard-inaccessible at
 * exactly the point where it holds the most state. Base UI's are focusable,
 * walk with the arrows, and delete with Backspace.
 *
 * `Empty` renders only when nothing matched, and announces itself politely.
 * Its element stays mounted for that announcement to work, so it must not be
 * hidden with `display: none` or removed conditionally - which is why it is a
 * component here rather than a `{items.length === 0 && …}` in the product.
 */

/* Two bases, chosen by `bare`, rather than one base and an override.
 *
 * Inside `ComboboxChips` the container is the field, so the input has no
 * border, no background and no focus ring of its own - a bordered box inside a
 * bordered box reads as two controls, and two focus rings appear as one thick
 * one. The obvious way to write that is `fieldClasses` plus a few `-none`
 * classes, and it does not work: `tailwind-merge` does not treat
 * `focus-visible:outline-none` as conflicting with
 * `focus-visible:outline-2 … outline-accent`, so both survive and the later
 * one in the stylesheet wins. The same trap took `w-full` versus `w-auto`
 * earlier in this file.
 *
 * So the variant picks which set applies instead of trying to subtract from
 * one - nothing is left to a merge that has no opinion. */
export const comboboxInputVariants = cva('', {
  variants: {
    size: {
      sm: 'h-8 text-xs',
      md: 'h-9',
      lg: 'h-10 text-base',
    },
    bare: {
      true: 'h-7 w-auto min-w-24 flex-1 bg-transparent px-1 text-sm text-text placeholder:text-faint outline-none',
      false: fieldClasses,
    },
  },
  defaultVariants: { size: 'md', bare: false },
})

/** The list, and a row in it, are Select's - imported rather than copied.
 *
 * The two popups are the same object seen twice: a dropdown of options, one
 * of which can be chosen. A reader who uses both on one screen should not be
 * able to tell which is which until they type. Two `cva` calls that started
 * identical do not stay that way - one gets the padding fix - and then the
 * form has two dropdowns that are almost the same. */
export const comboboxPopupVariants = selectPopupVariants
export const comboboxItemVariants = selectItemVariants

/** The root. `items` is what gets filtered; `multiple` turns the value into an
 * array and makes the chips meaningful. */
export const Combobox = Base.Root

/** The wrapper for an input with something beside it - a clear button, an
 * icon, the chips. */
export const ComboboxInputGroup = Base.InputGroup

/** The button that opens the list without typing, for a reader who wants to
 * see everything there is. */
export const ComboboxTrigger = Base.Trigger

/** The chevron. Decorative. */
export const ComboboxIcon = Base.Icon

/** A labelled group of rows. */
export const ComboboxGroup = Base.Group

/** The rows of one group, as a render function over that group's items.
 *
 * A `List` is the listbox and there is one per combobox, so a grouped list is
 * a `List` over the groups with a `Collection` inside each - not a `List`
 * inside a `List`. Mapping by hand instead works, but the component then has
 * to be told how to match an item to a value, which is a second place for that
 * knowledge to live. */
export const ComboboxCollection = Base.Collection

/** The tick, drawn only on a chosen row. */
export const ComboboxItemIndicator = Base.ItemIndicator

/** A polite live region for the state of an asynchronous list. Stays mounted,
 * like `Empty`, so the announcement actually fires. */
export const ComboboxStatus = Base.Status

/** The container the chips sit in. Its children are plain nodes, not a render
 * function - the chosen values are mapped by `ComboboxValue` inside it.
 *
 * It wears the field's clothes and lays the chips out in a row that wraps,
 * which is the whole difference between a control and a list: unstyled, the
 * chips stack one per line and the box grows into a column of pills with the
 * input stranded underneath. The input sits on the same line as the last
 * chip and takes the rest of the width, so a half-filled field still looks
 * like a field. */
export function ComboboxChips({
  ref,
  className,
  ...props
}: Base.Chips.Props & { ref?: Ref<HTMLDivElement> }) {
  return (
    <Base.Chips
      // Taken out of `...props` and passed on deliberately: a product needs a
      // handle on this box to anchor the list to it, because the input inside
      // is only as wide as what has been typed.
      ref={ref}
      className={cn(
        fieldClasses,
        'flex min-h-9 flex-wrap items-center gap-1 py-1',
        'focus-within:outline-2 focus-within:outline-offset-0 focus-within:outline-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The current value, as a render function of it. This is what turns a
 * `multiple` value into one chip per entry. */
export const ComboboxValue = Base.Value

/** `size` is taken from the native `<input size>` - a width in characters,
 * which nothing here wants - and given to the variant instead. */
export interface ComboboxInputProps
  extends Omit<Base.Input.Props, 'size'>,
    VariantProps<typeof comboboxInputVariants> {}

/** Where the query is typed. A real `<input role="combobox">`.
 *
 * Inside `ComboboxChips` it drops its own border and background: the
 * container is the field there, and a bordered input inside a bordered box
 * reads as two controls. */
export function ComboboxInput({ size, bare, className, ...props }: ComboboxInputProps) {
  // `bare` is pulled out and handed to `cva`. Left in `...props` it would be
  // spread onto the `<input>` as an unknown attribute and change nothing -
  // which is exactly what it did: the variant existed, the prop was passed,
  // and the class list came out without a trace of either.
  return <Base.Input className={cn(comboboxInputVariants({ size, bare }), className)} {...props} />
}

const iconButtonClasses = cn(
  'rounded-sm p-1 text-faint transition-colors hover:text-text',
  'focus-visible:outline-2 focus-visible:outline-accent',
  'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
)

/** Empties the value. Base UI hides it while there is nothing to clear. */
export function ComboboxClear({ className, ...props }: Base.Clear.Props) {
  return <Base.Clear className={cn(iconButtonClasses, className)} {...props} />
}

export interface ComboboxPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof comboboxPopupVariants> {
  /** Preferred side of the input. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the input, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /**
   * What to line the list up with. Defaults to the input that owns it.
   *
   * Pass the `ComboboxChips` box when there is one: with chips, the input is
   * only as wide as what has been typed - an empty one measured 214px inside
   * a 288px field - so a list anchored to it hangs short of the box a reader
   * sees. Base UI publishes the anchor's width as `--anchor-width`, which is
   * how the mismatch is visible from outside.
   */
  anchor?: Base.Positioner.Props['anchor']
  /** Where to portal to. Defaults to the document body. */
  container?: Base.Portal.Props['container']
}

/** The list. Portalled and positioned against the input, or the given anchor. */
export function ComboboxPopup({
  size,
  side,
  align,
  sideOffset = 4,
  anchor,
  container,
  className,
  children,
  ...props
}: ComboboxPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        anchor={anchor}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(comboboxPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The rows, as a list. Undressed: it is a wrapper, and the popup around it
 * already carries the border and the padding. */
export const ComboboxList = Base.List

/** A row. */
export function ComboboxItem({ className, ...props }: Base.Item.Props) {
  return <Base.Item className={cn(comboboxItemVariants(), className)} {...props} />
}

/** What is shown when nothing matched. The words are the product's. */
export function ComboboxEmpty({ className, ...props }: Base.Empty.Props) {
  return <Base.Empty className={cn('px-2 py-3 text-center text-sm text-faint', className)} {...props} />
}

/** One chosen value, in a multiple combobox. Focusable, so it can be reached
 * and removed without a pointer. */
export function ComboboxChip({ className, ...props }: Base.Chip.Props) {
  return (
    <Base.Chip
      className={cn(
        'flex items-center gap-1 rounded-sm bg-soft px-1.5 py-0.5 text-xs text-text',
        'outline-none data-[highlighted]:bg-accent-soft data-[highlighted]:text-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The X on a chip. A real button, which is what makes Backspace and Enter
 * both work on it. */
export function ComboboxChipRemove({ className, ...props }: Base.ChipRemove.Props) {
  return <Base.ChipRemove className={cn(iconButtonClasses, 'p-0', className)} {...props} />
}

/** The caption above a group. */
export function ComboboxGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import type { ReactNode } from 'react'
import { Combobox as Base } from '@base-ui/react/combobox'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { comboboxItemVariants } from './combobox'
import { Kbd } from './kbd'

/*
 * CommandPalette.
 *
 * One box that finds anything: the shortcut opens it, typing narrows a list,
 * Enter runs what is highlighted.
 *
 * It is a Combobox rather than a Dialog with a field in it, and that is Base
 * UI's own arrangement rather than a shortcut taken here: put the input
 * *inside* the popup and the popup becomes `role="dialog"` on its own, with
 * the input still announced as the combobox that owns the list. The filtering,
 * the highlight, the arrow keys and the type-ahead are the ones Combobox
 * already has - there is no second implementation of any of it.
 *
 * What is left for the product is everything that makes a palette that
 * product's: what the items are, how they are grouped, what running one does.
 * `items` is deliberately `unknown[]` - a palette lists commands, works,
 * settings and recent files in the same box, and a type that admitted only
 * strings would push every product into the same stringly-typed workaround.
 */

export const commandPalettePopupVariants = cva(
  [
    'flex w-[min(36rem,calc(100vw-2rem))] flex-col overflow-hidden',
    'rounded-xl border border-line bg-raise text-text shadow-float',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        md: 'max-h-[24rem]',
        lg: 'max-h-[32rem]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled by `open`/`onOpenChange`, because what opens a palette
 * is a shortcut somewhere else in the application. */
export const CommandPalette = Base.Root

/** A row. The same clothes as a Combobox row, on purpose: a palette is a list
 * of choices, and two lists of choices in one product should not differ.
 *
 * They did differ, for as long as this was a bare re-export: the comment said
 * "the same clothes" and the component wore none, so the rows inherited the
 * popup's 16px and stood a third taller than every other list in the set. A
 * live run caught it - the palette looked like a different product. */
export function CommandPaletteItem({ className, ...props }: Base.Item.Props) {
  return <Base.Item className={cn(comboboxItemVariants(), className)} {...props} />
}

/** The list. Takes a render function over the filtered items. */
export function CommandPaletteList({ className, ...props }: Base.List.Props) {
  return <Base.List className={cn('overflow-y-auto p-1', className)} {...props} />
}

/** Shown when nothing matches. The words are the product's.
 *
 * Base UI keeps it mounted so the announcement fires, which means its padding
 * is spent whether or not it has anything to say - and a palette with six
 * results had a 48px hole under the field. It collapses when empty instead. */
export function CommandPaletteEmpty({ className, ...props }: Base.Empty.Props) {
  return (
    <Base.Empty
      className={cn('px-2 py-3 text-center text-sm text-faint empty:hidden empty:p-0', className)}
      {...props}
    />
  )
}

/** A labelled group, for a palette that lists more than one kind of thing. */
export const CommandPaletteGroup = Base.Group

/** The caption above a group. */
export const CommandPaletteGroupLabel = Base.GroupLabel

/** The rows of one group, as a render function over that group's items.
 *
 * A palette that lists works, versions and notes together is a `List` over the
 * groups with a `Collection` inside each. Mapping a group's rows by hand also
 * works, but then the palette has to be told how to match an item to a value -
 * and for rows fetched fresh from a server, identity comparison never does. */
export const CommandPaletteCollection = Base.Collection

export interface CommandPalettePopupProps
  extends Omit<Base.Popup.Props, 'aria-label'>,
    VariantProps<typeof commandPalettePopupVariants> {
  /**
   * What the palette is called, for a screen reader. Required, and required
   * for a reason particular to this component: the popup is a dialog, and a
   * dialog is named by its own visible title - which a palette does not have,
   * because the field is the first thing in it.
   *
   * So the name has to come from outside, it has to be the product's word, and
   * nothing else can supply it. A palette without one is announced as "dialog"
   * and nothing more; making the prop required is what stops that shipping.
   */
  'aria-label': string
  /** Where to portal to. Defaults to the document body. */
  container?: Base.Portal.Props['container']
}

/** The palette itself: a dim over the page, and the box in the upper third of
 * it - where the eye already is, rather than dead centre. */
export function CommandPalettePopup({
  size,
  container,
  className,
  children,
  ...props
}: CommandPalettePopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Backdrop
        className={cn(
          'fixed inset-0 bg-black/55 backdrop-blur-[2px]',
          '[z-index:var(--z-overlay)]',
          '[transition:opacity_var(--duration-quick)_var(--ease-out)]',
          'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        )}
      />
      <Base.Positioner
        className="[z-index:var(--z-palette)]"
        /* The anchor is a point at the top of the viewport, given explicitly.
         *
         * A positioner places a popup against an anchor and hides itself with
         * an inline `opacity: 0` until it has measured one. A palette has no
         * trigger to point at - it is opened by a keystroke - so without this
         * the measure never resolves: the popup sits in the DOM at the right
         * size, fully transparent, rendering nothing and reporting no error.
         * Found by reading the computed style off the positioner rather than
         * the popup, which was opaque the whole time.
         *
         * A zero-height rectangle a fifth of the way down puts the palette
         * where the eye already is rather than dead centre. */
        anchor={{
          getBoundingClientRect: () => {
            const width = typeof window === 'undefined' ? 0 : window.innerWidth
            const top = typeof window === 'undefined' ? 0 : window.innerHeight * 0.18
            return new DOMRect(width / 2, top, 0, 0)
          },
        }}
        positionMethod="fixed"
        side="bottom"
        align="center"
        sideOffset={0}
        alignOffset={0}
      >
        <Base.Popup
          className={cn(commandPalettePopupVariants({ size }), className)}
          {...props}
        >
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface CommandPaletteInputProps extends Base.Input.Props {
  /** Shown at the right of the field, as `['Esc']`. Decorative. */
  hint?: string[]
}

/** The field. Sits inside the popup, which is what makes the popup a dialog
 * and the field its combobox. */
export function CommandPaletteInput({ hint, className, ...props }: CommandPaletteInputProps) {
  return (
    <div className="flex items-center gap-2 border-b border-line px-3">
      <MagnifierIcon />
      <Base.Input
        className={cn(
          'h-11 w-full bg-transparent text-sm text-text placeholder:text-faint',
          'focus-visible:outline-none',
          className,
        )}
        {...props}
      />
      {hint && <Kbd keys={hint} aria-hidden className="shrink-0" />}
    </div>
  )
}

/** The row's own layout: an icon, what it is, and where it lives. */
export function CommandPaletteRow({
  icon,
  hint,
  className,
  children,
  ...props
}: {
  icon?: ReactNode
  hint?: ReactNode
  className?: string
  children: ReactNode
} & Omit<React.HTMLAttributes<HTMLDivElement>, 'children'>) {
  return (
    <div className={cn('flex w-full items-center gap-2.5', className)} {...props}>
      {icon}
      <span className="min-w-0 flex-1 truncate">{children}</span>
      {hint !== undefined && <span className="shrink-0 text-2xs text-faint">{hint}</span>}
    </div>
  )
}

export { comboboxItemVariants as commandPaletteItemVariants }

function MagnifierIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width="15"
      height="15"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      aria-hidden
      className="shrink-0 text-faint"
    >
      <circle cx="7" cy="7" r="4.5" />
      <path d="M10.5 10.5L14 14" strokeLinecap="round" />
    </svg>
  )
}

import { AlertDialog as Base } from '@base-ui/react/alert-dialog'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * ConfirmDialog.
 *
 * The dialog for a choice that cannot be taken back - deleting, discarding,
 * revoking. It looks almost exactly like Dialog, and that is deliberate: the
 * difference is not clothes, it is what the popup is allowed to do.
 *
 * A Dialog is dismissed by clicking away, because a Dialog is a place the user
 * wandered into. This one is not: Base UI's `AlertDialog` announces itself as
 * `role="alertdialog"`, which tells a screen reader the popup is interrupting
 * rather than presenting, and it forces `modal` and `disablePointerDismissal`
 * on - `AlertDialog.Root` omits both from Dialog's props, so there is nothing
 * to turn off. A press outside does nothing at all.
 *
 * `Escape` still closes it, and that is deliberate rather than an oversight: a
 * popup with no keyboard way out is a trap. The difference is between a
 * deliberate keypress and clicking absentmindedly beside a dialog.
 *
 * So the rule for choosing between the two is not how important the content
 * feels. It is whether dismissing it by a stray click would be a loss.
 */

export const confirmDialogPopupVariants = cva(
  [
    'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
    'rounded-xl border border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(22rem,calc(100vw-2rem))]',
        md: 'w-[min(26rem,calc(100vw-2rem))]',
        lg: 'w-[min(34rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `ConfirmDialogTrigger`. */
export const ConfirmDialog = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const ConfirmDialogTrigger = Base.Trigger

/** What closes it - and the only thing that does, which is why a confirm
 * dialog with no `ConfirmDialogClose` inside it is a trap. */
export const ConfirmDialogClose = Base.Close

/** The scrim. Darker than the Dialog's, because what is behind it is not just
 * out of reach for a moment - it is waiting on an answer. */
export function ConfirmDialogBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/60 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface ConfirmDialogPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof confirmDialogPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The dialog itself, announced as `alertdialog`. Portalled, so it is not
 * clipped by whatever it was opened from. */
export function ConfirmDialogPopup({
  size,
  container,
  backdrop = true,
  className,
  children,
  ...props
}: ConfirmDialogPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <ConfirmDialogBackdrop />}
      <Base.Popup
        className={cn(
          confirmDialogPopupVariants({ size }),
          '[z-index:var(--z-modal)]',
          className,
        )}
        {...props}
      >
        {children}
      </Base.Popup>
    </Base.Portal>
  )
}

/** The question. Base UI points the popup's `aria-labelledby` at it, so this
 * is what a screen reader reads out when the dialog interrupts. */
export function ConfirmDialogTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** What the answer costs, and the popup's `aria-describedby`. On this dialog
 * it is close to required: the title asks, the description says what happens. */
export function ConfirmDialogDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the two answers go. Right-aligned, because the choice belongs where
 * the eye leaves the sentence. */
export function ConfirmDialogActions({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-5 flex justify-end gap-2', className)} {...props} />
}

import { ContextMenu as Base } from '@base-ui/react/context-menu'
import { menuItemVariants, menuPopupVariants } from './menu'
import { cn } from 'dowel-ui'

/*
 * ContextMenu.
 *
 * The same list of actions as Menu, opened the other way round: by right
 * click, or by a long press on a touch screen, over an *area* rather than
 * from a button. So the trigger is not a control - it is the region the menu
 * belongs to, a row, a canvas, a file tile - and it renders a `<div>`.
 *
 * That difference is the whole component. Everything below the Root is Menu's
 * own: Base UI re-exports the Portal, Positioner, Popup, Item and the rest
 * from the menu package, so the popup that opens here is literally the same
 * popup, with the same keyboard, the same type-ahead and the same submenus.
 *
 * Which is why the clothes are imported rather than copied. Two `cva` calls
 * that started identical drift within a release - one gets a padding fix, the
 * other does not - and then a product has two menus that are almost the same,
 * which is worse than two that differ on purpose.
 *
 * What Base UI does *not* give this one is `openOnHover`, `modal` or a
 * `handle`: a context menu is opened by a gesture over an anchor point, not
 * by a trigger element it can be attached to from elsewhere.
 */

/** The root. It positions against the pointer, so there is nothing to anchor
 * and nothing to control but `onOpenChange`. */
export const ContextMenu = Base.Root

/** The area that opens it. A `<div>`, not a button: give it `render` to make
 * it the row or the canvas it belongs to rather than a wrapper. */
export const ContextMenuTrigger = Base.Trigger

/** A labelled group of items, for a menu long enough to need headings. */
export const ContextMenuGroup = Base.Group

/** A submenu, opened from a `ContextMenuSubTrigger` inside the parent. */
export const ContextMenuSub = Base.SubmenuRoot

export interface ContextMenuPopupProps extends Base.Popup.Props {
  /** How wide the popup starts. The same three as Menu's. */
  size?: 'sm' | 'md' | 'lg'
  /** Where to portal to. Defaults to the document body, which keeps the menu
   * from being clipped by the very row it was opened over. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled, and positioned against the point that was clicked
 * rather than against an element. */
export function ContextMenuPopup({
  size,
  container,
  className,
  children,
  ...props
}: ContextMenuPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner className="[z-index:var(--z-menu)]">
        <Base.Popup className={cn(menuPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface ContextMenuItemProps extends Base.Item.Props {
  /** `danger` draws the destructive one apart, in the colour of something
   * that cannot be undone. */
  tone?: 'default' | 'danger'
}

/** An action. */
export function ContextMenuItem({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.Item className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that opens a submenu. Drawn like any other, because it is one. */
export function ContextMenuSubTrigger({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.SubmenuTrigger className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that carries a tick. The state is the caller's. */
export function ContextMenuCheckboxItem({ tone, className, ...props }: ContextMenuItemProps) {
  return <Base.CheckboxItem className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** The tick itself, drawn only when the item is checked. */
export const ContextMenuCheckboxIndicator = Base.CheckboxItemIndicator

/** A line between groups of items. Decorative, and marked as such. */
export function ContextMenuSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

/** The caption above a group. */
export function ContextMenuGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import { useCallback, useEffect, useRef, useState, type HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Copyable.
 *
 * Any text that someone will eventually want to copy - an id, a path, a hash,
 * a token - copied with one click. The rule comes from nitid: if a value is
 * worth showing, it is worth being able to take away, and selecting a
 * monospaced id by hand is a small daily tax.
 *
 * Two things this gets right that the hand-written version usually does not.
 * It is a `<button>`, so the keyboard can reach it and a screen reader says
 * what it does. And the confirmation is announced, not only drawn: a tick that
 * appears silently tells a sighted user it worked and tells nobody else.
 *
 * The clipboard can refuse - it needs a secure context and, in some browsers,
 * a permission. A refusal is reported rather than swallowed, because a button
 * that looks like it worked and did not is worse than one that says it failed.
 */
export interface CopyableProps extends Omit<HTMLAttributes<HTMLButtonElement>, 'onCopy'> {
  /** What lands on the clipboard. Defaults to the visible text. */
  value?: string
  /** The visible text. */
  children: string
  /** What the button is called, for a screen reader. Required, and
   * deliberately without a default: a string the component invents is a
   * string the product cannot translate, and it would ship in English to
   * every reader who does not read English. */
  label: string
  /** What is announced after a successful copy. Required for the same
   * reason. */
  copiedLabel: string
  /** Told what happened, for a product that wants its own toast. */
  onCopy?: (ok: boolean) => void
}

export function Copyable({
  value,
  children,
  label,
  copiedLabel,
  onCopy,
  className,
  ...props
}: CopyableProps) {
  const [copied, setCopied] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)

  // A component that sets state on a timer has to stop when it goes away, or
  // it wakes up in a tree that no longer exists.
  useEffect(() => () => clearTimeout(timer.current), [])

  const copy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(value ?? children)
      setCopied(true)
      onCopy?.(true)
      clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), 1600)
    } catch {
      // No secure context, or permission refused. Say so rather than pretend.
      onCopy?.(false)
    }
  }, [value, children, onCopy])

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={copied ? copiedLabel : label}
      className={cn(
        'group inline-flex max-w-full items-center gap-1.5 rounded-sm px-1 py-0.5 text-left',
        'font-mono text-xs text-dim transition-colors',
        'hover:bg-soft hover:text-text',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        className,
      )}
      {...props}
    >
      <span className="truncate">{children}</span>

      <span className={cn('shrink-0 transition-colors', copied ? 'text-good' : 'text-faint')} aria-hidden>
        {copied ? <Tick /> : <Clipboard />}
      </span>

      {/* Drawn confirmation is invisible to a screen reader; this is the part
          that actually says it worked. */}
      <span role="status" aria-live="polite" className="sr-only">
        {copied ? copiedLabel : ''}
      </span>
    </button>
  )
}

function Clipboard() {
  return (
    <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden>
      <rect x="5.5" y="2.5" width="8" height="10" rx="1.5" />
      <path d="M10.5 2.5v-.5a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h.5" />
    </svg>
  )
}

function Tick() {
  return (
    <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
      <path d="M3 8.5l3.5 3.5L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

import { useMemo, useState } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { Popover, PopoverPopup, PopoverTrigger } from './popover'
import { Calendar } from './calendar'
import { isIsoDate, type IsoDate } from './calendar-math'

/*
 * DatePicker - a field that opens a month.
 *
 * The trigger is a button rather than a text input, and that is the decision
 * worth stating. A typable date field has to answer "what does `03/04/26`
 * mean" in a locale it cannot be sure of, and it answers wrong for half the
 * world; a button showing the date spelled out has no such question. Where
 * typing genuinely matters - a birth date, forty years back - the calendar is
 * the wrong control anyway and a product should reach for a plain field.
 *
 * The value is a calendar date as a string, `YYYY-MM-DD`, for the reasons the
 * Calendar states: a date with a timezone is a moment, and moments cross
 * midnight when they are serialised.
 *
 * What is shown is `Intl`'s own long form - "2 September 2026" here, "September
 * 2, 2026" in the United States - because a date written the reader's way is
 * one they do not have to decode.
 */

export interface DatePickerProps {
  /** The chosen day, or `undefined` for none. */
  value?: IsoDate
  onValueChange?: (value: IsoDate) => void
  /** Bounds, inclusive. */
  min?: IsoDate
  max?: IsoDate
  /** What the trigger says when nothing is chosen. The product's word, since
   * a default here would be English inside a primitive. */
  placeholder: string
  /** Names the two month-paging buttons inside the calendar. */
  previousMonthLabel: string
  nextMonthLabel: string
  /** How the date is written and which day starts the week. The reader's own
   * unless stated. */
  locale?: string
  disabled?: boolean
  name?: string
  'aria-label'?: string
  className?: string
}

export function DatePicker({
  value,
  onValueChange,
  min,
  max,
  placeholder,
  previousMonthLabel,
  nextMonthLabel,
  locale,
  disabled = false,
  name,
  className,
  'aria-label': ariaLabel,
}: DatePickerProps) {
  const [open, setOpen] = useState(false)

  const shown = useMemo(() => {
    if (value === undefined || !isIsoDate(value)) return undefined
    const [year, month, day] = value.split('-').map(Number) as [number, number, number]
    return new Intl.DateTimeFormat(locale, { dateStyle: 'long' }).format(
      new Date(year, month - 1, day),
    )
  }, [value, locale])

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        disabled={disabled}
        aria-label={ariaLabel}
        className={cn(
          fieldClasses,
          'flex h-9 cursor-pointer items-center gap-2 text-left',
          'disabled:cursor-not-allowed',
          className,
        )}
      >
        <svg viewBox="0 0 16 16" className="size-4 shrink-0 text-faint" fill="none" aria-hidden>
          <rect x="2" y="3" width="12" height="11" rx="2" stroke="currentColor" strokeWidth="1.3" />
          <path d="M2 6.5h12M5.5 2v2M10.5 2v2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
        </svg>
        <span className={cn('truncate', shown === undefined && 'text-faint')}>
          {shown ?? placeholder}
        </span>
      </PopoverTrigger>

      {/* The value also goes into a form, because a button is not a field and
        * a form submitting the screen would otherwise lose the date. */}
      {name !== undefined && <input type="hidden" name={name} value={value ?? ''} />}

      <PopoverPopup arrow={false} className="w-auto p-3">
        <Calendar
          value={value}
          min={min}
          max={max}
          locale={locale}
          aria-label={ariaLabel ?? placeholder}
          previousMonthLabel={previousMonthLabel}
          nextMonthLabel={nextMonthLabel}
          onValueChange={(next) => {
            onValueChange?.(next)
            // Choosing a day is the whole errand: the popup closes rather
            // than waiting for a second dismissing click.
            setOpen(false)
          }}
        />
      </PopoverPopup>
    </Popover>
  )
}

import { useMemo, useState } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { Popover, PopoverPopup, PopoverTrigger } from './popover'
import { Calendar } from './calendar'
import { isIsoDate, type IsoDate } from './calendar-math'

/*
 * DateRangePicker - two days, chosen in two clicks.
 *
 * The interesting part is the state between them. After the first click there
 * is a start and no end, and that is not an incomplete range to be hidden or
 * a range of one day - it is the normal middle of the interaction, and the
 * calendar has to show it: the first day marked, the days under the pointer
 * shading as the reader moves, the popup staying open. Products that skip it
 * end up with a picker that seems to do nothing until the second click.
 *
 * So the value is a pair where either end may be absent, and the component is
 * explicit about which half it is waiting for. `onValueChange` fires on both
 * clicks - a product watching it sees the half-made range, which is what lets
 * it show "from 2 September" while the reader is still deciding.
 *
 * The second click can land before the first. Clicking the 20th and then the
 * 10th means the 10th to the 20th, because that is plainly what was meant;
 * refusing it would be correct and unhelpful.
 */

export interface DateRange {
  /** The first day, inclusive. */
  start?: IsoDate
  /** The last day, inclusive. Absent while the range is half made. */
  end?: IsoDate
}

export interface DateRangePickerProps {
  value?: DateRange
  onValueChange?: (value: DateRange) => void
  min?: IsoDate
  max?: IsoDate
  /** What the trigger says when nothing is chosen. */
  placeholder: string
  /** Names the two month-paging buttons inside the calendar. */
  previousMonthLabel: string
  nextMonthLabel: string
  locale?: string
  disabled?: boolean
  'aria-label'?: string
  className?: string
}

export function DateRangePicker({
  value,
  onValueChange,
  min,
  max,
  placeholder,
  previousMonthLabel,
  nextMonthLabel,
  locale,
  disabled = false,
  className,
  'aria-label': ariaLabel,
}: DateRangePickerProps) {
  const [open, setOpen] = useState(false)

  const range = value ?? {}
  const waitingForEnd = range.start !== undefined && range.end === undefined

  const shown = useMemo(() => {
    const write = (date: IsoDate) => {
      const [year, month, day] = date.split('-').map(Number) as [number, number, number]
      return new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }).format(
        new Date(year, month - 1, day),
      )
    }
    if (range.start === undefined || !isIsoDate(range.start)) return undefined
    if (range.end === undefined) return write(range.start)
    // An en dash rather than a hyphen: this is a span, and the two read
    // differently at a glance in a row of dates.
    return `${write(range.start)} – ${write(range.end)}`
  }, [range.start, range.end, locale])

  const choose = (date: IsoDate) => {
    // A fresh click starts a new range whenever there is nothing waiting -
    // including right after a completed one, which is what a reader means by
    // clicking again.
    if (!waitingForEnd) {
      onValueChange?.({ start: date })
      return
    }

    const start = range.start!
    // Backwards is fine: the reader plainly meant the span between them.
    const next: DateRange = date < start ? { start: date, end: start } : { start, end: date }
    onValueChange?.(next)
    setOpen(false)
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        disabled={disabled}
        aria-label={ariaLabel}
        className={cn(
          fieldClasses,
          'flex h-9 cursor-pointer items-center gap-2 text-left',
          'disabled:cursor-not-allowed',
          className,
        )}
      >
        <svg viewBox="0 0 16 16" className="size-4 shrink-0 text-faint" fill="none" aria-hidden>
          <rect x="2" y="3" width="12" height="11" rx="2" stroke="currentColor" strokeWidth="1.3" />
          <path d="M2 6.5h12M5.5 2v2M10.5 2v2" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
        </svg>
        <span className={cn('truncate', shown === undefined && 'text-faint')}>
          {shown ?? placeholder}
        </span>
      </PopoverTrigger>

      <PopoverPopup arrow={false} className="w-auto p-3">
        <Calendar
          value={range.start}
          rangeEnd={range.end}
          min={min}
          max={max}
          locale={locale}
          aria-label={ariaLabel ?? placeholder}
          previousMonthLabel={previousMonthLabel}
          nextMonthLabel={nextMonthLabel}
          onValueChange={choose}
        />
      </PopoverPopup>
    </Popover>
  )
}

import { Dialog as Base } from '@base-ui/react/dialog'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Dialog.
 *
 * The parts are exposed rather than wrapped in one component with `title` and
 * `footer` props. The products that did it the other way ended up passing
 * `footer={<>…</>}` within a week, which is a slot with extra steps - and a
 * dialog that owns its own close button owns a word for it, which is a word
 * the product cannot translate.
 *
 * Behaviour is Base UI's: the focus trap, the return of focus to whatever
 * opened it, `Escape`, the scroll lock, and the `aria-labelledby` that ties
 * the popup to its own title. None of that is worth rewriting, and all of it
 * is wrong in the ways nobody notices until someone is navigating by keyboard.
 *
 * What is ours is the clothes, and the enter and leave: the popup arrives with
 * `data-open` and leaves with `data-closed`, both of which Base UI sets, so
 * the animation is a class list rather than a state machine.
 */

export const dialogPopupVariants = cva(
  [
    'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
    'rounded-xl border border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // The width was capped from the start and the height was not, so a dialog
    // with more in it than the window is tall centred itself and hung off both
    // ends - the top out of reach above the viewport, the buttons below it.
    // Found on a release editor in kilna, which is exactly the shape that does
    // it: half a dozen fields and a row of actions.
    'max-h-[calc(100dvh-2rem)] overflow-y-auto overscroll-contain',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(24rem,calc(100vw-2rem))]',
        md: 'w-[min(28rem,calc(100vw-2rem))]',
        lg: 'w-[min(40rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `Dialog.Trigger`. */
export const Dialog = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const DialogTrigger = Base.Trigger

/** What closes it - the same, for a cancel button or an X. */
export const DialogClose = Base.Close

/** The scrim. Dark because a modal is a modal: what is behind it is out of
 * reach, and saying so with contrast is the only thing that reads at a
 * glance. */
export function DialogBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/50 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface DialogPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof dialogPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by whatever it was opened from. Pass an
   * element to put it somewhere else - inside a dialog that is already open,
   * or into a container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The dialog itself. Portalled, so it is not clipped by whatever it was
 * opened from. */
export function DialogPopup({
  size,
  container,
  backdrop = true,
  className,
  children,
  ...props
}: DialogPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <DialogBackdrop />}
      <Base.Popup
        className={cn(dialogPopupVariants({ size }), '[z-index:var(--z-modal)]', className)}
        {...props}
      >
        {children}
      </Base.Popup>
    </Base.Portal>
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * dialog with one is named for a screen reader without anyone arranging it. */
export function DialogTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function DialogDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the actions go. Right-aligned, because the primary action of a
 * dialog belongs where the eye leaves the sentence. */
export function DialogActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-5 flex justify-end gap-2', className)} {...props} />
}

import { Drawer as Base } from '@base-ui/react/drawer'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Drawer.
 *
 * A panel that slides in from an edge and holds the screen while it is there -
 * a filter sheet, a detail pane, a form too long to centre. Modal like Dialog,
 * placed like nothing else.
 *
 * Base UI positions none of it. Unlike Popover there is no Positioner and no
 * anchor to measure against; the edge it comes from is entirely CSS, which is
 * what the `side` variant is. It drives three things at once and they have to
 * agree: where the Viewport pushes the panel, which border it grows against,
 * and which way it is translated while opening and closing.
 *
 * `swipeDirection` is the other half and cannot be inferred here: it lives on
 * the root, while `side` lives on the popup, so the two are set together by
 * hand - `side="right"` with `swipeDirection="right"`, `side="bottom"` with
 * `down`, which is Base UI's default. Left unmatched, the drawer slides in
 * from one edge and is flicked away towards another.
 *
 * The transitions key off `data-starting-style` and `data-ending-style` rather
 * than `data-closed`. That is Base UI's own convention for the drawer, and the
 * reason is that a drawer is dragged as well as animated: the popup carries a
 * live `--drawer-swipe-movement-*` while a finger is on it, and the transform
 * has to compose with that rather than replace it.
 */

/** The Viewport: fixed to the whole window, pushing the popup to one edge.
 *
 * It is separate from the popup because a drawer that is its own positioner
 * cannot be scrolled independently of where it sits - and the panel needs to
 * scroll while the edge it is pinned to does not move. */
const drawerViewportVariants = cva('fixed inset-0 flex', {
  variants: {
    side: {
      right: 'justify-end',
      left: 'justify-start',
      bottom: 'items-end',
    },
  },
  defaultVariants: { side: 'right' },
})

export const drawerPopupVariants = cva(
  [
    'flex flex-col overflow-y-auto overscroll-contain',
    'border-line bg-raise p-5 text-text shadow-float',
    'focus-visible:outline-none',
    // Composed with the live swipe offset rather than replacing it, so a
    // half-dragged drawer animates from where the finger left it.
    '[transition:transform_var(--duration-base)_var(--ease-out)]',
    'will-change-transform',
  ],
  {
    variants: {
      /* Where it comes from. The three the products of the line reach for:
       * a right-hand pane, its mirror, and a bottom sheet. */
      side: {
        right: [
          'h-full w-[min(24rem,calc(100vw-3rem))] border-l',
          '[transform:translateX(var(--drawer-swipe-movement-x))]',
          'data-[starting-style]:[transform:translateX(100%)]',
          'data-[ending-style]:[transform:translateX(100%)]',
        ],
        left: [
          'h-full w-[min(24rem,calc(100vw-3rem))] border-r',
          '[transform:translateX(var(--drawer-swipe-movement-x))]',
          'data-[starting-style]:[transform:translateX(-100%)]',
          'data-[ending-style]:[transform:translateX(-100%)]',
        ],
        bottom: [
          'max-h-[80vh] w-full rounded-t-xl border-t',
          '[transform:translateY(var(--drawer-swipe-movement-y))]',
          'data-[starting-style]:[transform:translateY(100%)]',
          'data-[ending-style]:[transform:translateY(100%)]',
        ],
      },
    },
    defaultVariants: { side: 'right' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `DrawerTrigger`. */
export const Drawer = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const DrawerTrigger = Base.Trigger

/** What closes it - the same, for a cancel button or an X. */
export const DrawerClose = Base.Close

/** The scrim. Dark because a drawer is modal: what is behind it is out of
 * reach, and saying so with contrast is the only thing that reads at a
 * glance. */
export function DrawerBackdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop
      className={cn(
        'fixed inset-0 bg-black/50 backdrop-blur-[2px]',
        '[z-index:var(--z-overlay)]',
        '[transition:opacity_var(--duration-base)_var(--ease-out)]',
        'data-[closed]:opacity-0 data-[starting-style]:opacity-0',
        className,
      )}
      {...props}
    />
  )
}

export interface DrawerPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof drawerPopupVariants> {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
  /** Whether to draw the scrim. On by default, and it should stay on for
   * anything a person actually uses: the dim is what says the page behind is
   * out of reach. Turn it off where the popup is shown alongside other things
   * on purpose - a component gallery, a screenshot - because a scrim is
   * `position: fixed` and covers everything, not only its own container. */
  backdrop?: boolean
}

/** The panel. Portalled, and wrapped in its own viewport so the edge it is
 * pinned to holds still while the contents scroll. */
export function DrawerPopup({
  container,
  backdrop = true,
  side,
  className,
  children,
  ...props
}: DrawerPopupProps) {
  return (
    <Base.Portal container={container}>
      {backdrop && <DrawerBackdrop />}
      <div className={cn(drawerViewportVariants({ side }), '[z-index:var(--z-modal)]')}>
        <Base.Viewport className="flex w-full">
          <Base.Popup
            className={cn(drawerPopupVariants({ side }), className)}
            {...props}
          >
            {children}
          </Base.Popup>
        </Base.Viewport>
      </div>
    </Base.Portal>
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * drawer with one is named for a screen reader without anyone arranging it. */
export function DrawerTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-base font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function DrawerDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

/** Where the actions go. Pushed to the bottom of the panel rather than sitting
 * under the content, because a drawer is tall and its buttons should not
 * wander up the page when there is little in it. */
export function DrawerActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('mt-auto flex justify-end gap-2 pt-5', className)} {...props} />
}

import { useState, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * DurationField - a length of time, typed the way people say it.
 *
 * The alternative is what products keep building: two number boxes labelled
 * "hours" and "minutes", which means two tab stops, two validations, and a
 * reader who has to divide 90 minutes in their head before typing. Here they
 * write `1h 30m`, or `90m`, or `1.5h`, and it means the same thing.
 *
 * The value is **minutes**, a plain number. Not a string, not a Duration
 * object: the products of this line store durations as minutes already, and
 * a field whose value has to be parsed by its caller has moved the problem
 * rather than solved it.
 *
 * Parsing is deliberately generous and formatting is strict. Anything a
 * person plausibly types is accepted - `2h`, `2 h`, `2:30`, `150`, `2h30`,
 * with or without spaces - and what comes back on blur is always the one
 * canonical spelling. That asymmetry is the whole design: being strict on
 * input means rejecting people, being loose on output means the column of
 * values never lines up.
 *
 * Empty is `null`, like NumberField: "no duration" and "zero minutes" are
 * different answers, and a task with no estimate is not a task estimated at
 * nothing.
 */

/** Minutes from whatever was typed, or `null` for empty, or `undefined` when
 * it cannot be read as a duration at all.
 *
 * Exported because the parsing *is* the component - a test that goes through
 * the DOM checks React's state handling, and what needs checking is this. */
export function parseDuration(text: string): number | null | undefined {
  const input = text.trim().toLowerCase()
  if (input === '') return null

  // `2:30` - the clock spelling, which is unambiguous and worth taking.
  const clock = /^(\d+):([0-5]?\d)$/.exec(input)
  if (clock) return Number(clock[1]) * 60 + Number(clock[2])

  // A bare number is minutes. `90` is an hour and a half, not ninety hours:
  // the field is most often used for something that takes minutes, and a
  // reader typing hours writes the `h`.
  if (/^\d+(?:[.,]\d+)?$/.test(input)) return Math.round(Number(input.replace(',', '.')))

  /* The general form: any number of `<number><unit>` pairs. A decimal is
   * allowed on the hours (`1.5h`) because people write it, and a comma counts
   * as a decimal point because half the world uses one. */
  const pattern = /(\d+(?:[.,]\d+)?)\s*([hm])/g
  let total = 0
  let matched = false
  let consumed = 0

  for (const match of input.matchAll(pattern)) {
    matched = true
    consumed += match[0].length
    const amount = Number(match[1]!.replace(',', '.'))
    total += match[2] === 'h' ? amount * 60 : amount
  }

  // Everything that is not whitespace has to have been part of a pair -
  // otherwise `1h banana` would quietly parse as an hour.
  if (!matched || consumed !== input.replace(/\s+/g, '').length) return undefined

  return Math.round(total)
}

/** The one spelling a duration is written back as: `1h 30m`, `45m`, `2h`.
 *
 * Zero is `0m` rather than blank, because a duration of zero is an answer -
 * blank is what `null` renders as. */
export function formatDuration(minutes: number): string {
  const whole = Math.max(0, Math.round(minutes))
  const hours = Math.floor(whole / 60)
  const rest = whole % 60
  if (hours === 0) return `${rest}m`
  if (rest === 0) return `${hours}h`
  return `${hours}h ${rest}m`
}

export interface DurationFieldProps {
  /** Minutes, or `null` for empty. */
  value: number | null
  onValueChange: (value: number | null) => void
  /** What a reader sees before they type. A duration in the canonical
   * spelling is the best hint there is, so this is the product's to give. */
  placeholder?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  id?: string
  ref?: Ref<HTMLInputElement>
  'aria-label'?: string
  'aria-describedby'?: string
  className?: string
}

export function DurationField({
  value,
  onValueChange,
  className,
  ref,
  ...props
}: DurationFieldProps) {
  /* The field holds text while it is being typed and a number the rest of the
   * time. Without the local copy, typing `1h 3` would reformat under the
   * cursor after every keystroke - the classic controlled-input-with-parsing
   * bug, where the field fights the person using it. */
  const [text, setText] = useState(() => (value === null ? '' : formatDuration(value)))
  const [editing, setEditing] = useState(false)

  /* The `value` this box last saw from outside, adjusted during render rather
   * than in an effect - React's own pattern for a state that has to follow a
   * prop, and the one the `set-state-in-effect` rule points at.
   *
   * The comparison has to be against what was last *seen*, not against
   * `value`. After a commit the two differ in exactly the case that must be
   * left alone: `commit` writes `1h 30m` and tells the parent, the parent
   * still holds `null` for a tick, and comparing with `value` would clear the
   * box under the reader. Asking "has the outside changed?" answers it. */
  const [seen, setSeen] = useState<number | null>(value)

  if (value !== seen) {
    setSeen(value)
    // A value that changed while someone is typing is remembered, not shown:
    // reformatting under the cursor is the bug the local copy exists for.
    if (!editing) setText(value === null ? '' : formatDuration(value))
  }

  const commit = () => {
    setEditing(false)
    const parsed = parseDuration(text)
    if (parsed === undefined) {
      // Unreadable: put back what the value actually is rather than leaving
      // the box saying something the form does not believe.
      setText(value === null ? '' : formatDuration(value))
      return
    }
    setText(parsed === null ? '' : formatDuration(parsed))
    if (parsed !== value) onValueChange(parsed)
  }

  return (
    <input
      {...props}
      ref={ref}
      type="text"
      inputMode="text"
      value={text}
      onFocus={() => setEditing(true)}
      onChange={(event) => setText(event.target.value)}
      onBlur={commit}
      onKeyDown={(event) => {
        if (event.key === 'Enter') {
          event.preventDefault()
          commit()
        }
      }}
      className={cn(fieldClasses, 'h-9 tabular-nums', className)}
    />
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * What a screen says when there is nothing on it.
 *
 * Three kinds of nothing, and a product that draws the same panel for all
 * three is telling the reader the wrong thing twice:
 *
 *   **empty** - there is nothing here yet, and that is normal. The panel says
 *   what would be here and offers the one action that makes it appear.
 *
 *   **filtered** - there is plenty here, just none of it matching. The way out
 *   is to widen the filter, not to create anything.
 *
 *   **error** - it could not be fetched. Nothing is missing; something failed,
 *   and the way out is to try again.
 *
 * They differ in what the reader should do next, which is exactly what an
 * empty screen is for, so they are a variant rather than three components.
 *
 * `action` is the whole point of the component: **an empty screen with no way
 * out is a dead end.** It is optional in the type because a panel inside a
 * larger screen can borrow the way out from its surroundings - but a full-page
 * empty state without one is a bug the reader cannot report.
 *
 * The mark is the line's hexagon, drawn in the current text colour rather than
 * a product's accent. A full-strength logo in an empty panel shouts; this is a
 * watermark, and it is `aria-hidden` because it says nothing a reader needs.
 */

export const emptyStateVariants = cva(
  'flex flex-col items-center justify-center gap-3 rounded-xl p-8 text-center',
  {
    variants: {
      variant: {
        empty: 'border border-dashed border-line-2',
        filtered: 'border border-dashed border-line-2',
        // Solid rather than dashed: a dashed border reads as a placeholder for
        // something that belongs there, and a failure is not that.
        error: 'border border-bad/40 bg-bad-soft/30',
      },
    },
    defaultVariants: { variant: 'empty' },
  },
)

/** The line's hexagon, at whatever size the caller asks for.
 *
 * Inlined rather than fetched: it is decorative, so it should not cost a
 * request, and it has to take the theme's colour - a file could not. */
export function EmptyMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 100 100" aria-hidden className={cn('size-14', className)}>
      <polygon
        points="50,5 89,27.5 89,72.5 50,95 11,72.5 11,27.5"
        fill="none"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinejoin="round"
      />
    </svg>
  )
}

/** The same hexagon, cut by a slash. For a filter that matched nothing: the
 * shape is there, the contents are not. */
export function FilteredMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 100 100" aria-hidden className={cn('size-14', className)}>
      <polygon
        points="50,5 89,27.5 89,72.5 50,95 11,72.5 11,27.5"
        fill="none"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinejoin="round"
      />
      <line x1="22" y1="78" x2="78" y2="22" stroke="currentColor" strokeWidth={6} strokeLinecap="round" />
    </svg>
  )
}

/** A hexagon with a corner broken out of it. For something that failed. */
export function ErrorMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 100 100" aria-hidden className={cn('size-14', className)}>
      <polyline
        points="50,5 89,27.5 89,72.5 50,95 11,72.5 11,27.5 50,5"
        fill="none"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinejoin="round"
        strokeLinecap="round"
        // The gap is the break: the outline is drawn as a line rather than a
        // closed shape so one edge can be missing.
        strokeDasharray="150 34"
      />
    </svg>
  )
}

export interface EmptyStateProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>,
    VariantProps<typeof emptyStateVariants> {
  /** What is not here, in the product's words. */
  title: ReactNode
  /** Why, or what to do about it. */
  body?: ReactNode
  /** The one thing worth doing here. An empty screen with no way out is a
   * dead end. */
  action?: ReactNode
  /** Something other than the default mark - a product's own illustration. */
  mark?: ReactNode
}

export function EmptyState({
  variant = 'empty',
  title,
  body,
  action,
  mark,
  className,
  ...props
}: EmptyStateProps) {
  const defaultMark =
    variant === 'error' ? (
      <ErrorMark className="text-bad/60" />
    ) : variant === 'filtered' ? (
      <FilteredMark className="text-line-2" />
    ) : (
      <EmptyMark className="text-line-2" />
    )

  return (
    <div className={cn(emptyStateVariants({ variant }), className)} {...props}>
      {mark ?? defaultMark}
      <div>
        <p className={cn('font-medium', variant === 'error' && 'text-bad')}>{title}</p>
        {body !== undefined && <p className="mt-1 text-sm text-dim">{body}</p>}
      </div>
      {action}
    </div>
  )
}

import { Component, type ErrorInfo, type ReactNode } from 'react'
import { Button } from './button'
import { EmptyState } from './empty-state'

/*
 * The screen that appears instead of a crash.
 *
 * A class component, and the only one in the set - not a style choice: React
 * gives no hook for catching a render error, and `componentDidCatch` exists
 * nowhere else. Anything that claims otherwise catches events, not renders.
 *
 * What it is for is narrow and worth stating, because products reach for it as
 * a general error handler and it is not one: it catches errors **thrown while
 * rendering**, below itself. A failed fetch is not that - it is a value the
 * component receives and shows, which is `QueryState`. An error in an event
 * handler is not that either; nothing catches those but the handler.
 *
 * So this is the last line: something that should never have thrown did, and
 * the alternative is a white page with the product's own name at the top.
 *
 * The fallback is deliberately plain and deliberately says the message. The
 * reader cannot fix it, but the reader is who files it - and a screen that
 * hides the one string worth quoting turns a bug report into a guess. It is
 * folded away behind a summary, because it is evidence rather than an
 * instruction.
 */

export interface ErrorBoundaryProps {
  children: ReactNode
  /** Draw something else instead of the default screen.
   *
   * Given the error and a way to clear it, because a fallback that cannot
   * retry is a dead end with extra steps. */
  fallback?: (error: Error, reset: () => void) => ReactNode
  /** Change this to clear the error - a route, usually.
   *
   * Without it a boundary that has caught once stays caught: the reader
   * navigates away from the broken screen and the crash follows them, because
   * nothing told the boundary the reason had gone. */
  resetKey?: unknown
  /** Somewhere to send it. The product owns whether that is a log, a file or a
   * service - the boundary only knows it happened. */
  onError?: (error: Error, info: ErrorInfo) => void
  /** The words on the default screen. Required, and not defaulted: they are
   * the only text here, and English inside a primitive is text no product can
   * translate. */
  labels: ErrorBoundaryLabels
}

export interface ErrorBoundaryLabels {
  /** "Something went wrong." */
  title: string
  /** What the reader can do about it. */
  body: string
  /** The summary that unfolds the message, e.g. "Details". */
  details: string
  /** The retry button, e.g. "Try again". */
  retry: string
}

interface State {
  error: Error | null
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, State> {
  state: State = { error: null }

  static getDerivedStateFromError(error: Error): State {
    return { error }
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    this.props.onError?.(error, info)
  }

  componentDidUpdate(previous: ErrorBoundaryProps): void {
    // Clearing on a changed key, rather than on any re-render: a boundary that
    // resets whenever its parent renders re-runs the throwing child
    // immediately, and the screen flickers between the crash and the fallback
    // for as long as the cause is there.
    if (this.state.error !== null && previous.resetKey !== this.props.resetKey) {
      this.setState({ error: null })
    }
  }

  private reset = (): void => {
    this.setState({ error: null })
  }

  render(): ReactNode {
    const { error } = this.state
    if (error === null) return this.props.children

    const { fallback, labels } = this.props
    if (fallback) return fallback(error, this.reset)

    return (
      <EmptyState
        variant="error"
        title={labels.title}
        body={labels.body}
        action={
          <div className="flex w-full flex-col items-center gap-3">
            <details className="w-full text-left">
              <summary className="cursor-pointer text-xs text-faint">{labels.details}</summary>
              {/* Selectable and monospaced, because its job is to be copied
                * into a bug report verbatim. */}
              <pre className="mt-2 max-h-40 overflow-auto rounded-md bg-softer p-3 font-mono text-xs text-dim">
                {error.message}
              </pre>
            </details>
            <Button variant="primary" onClick={this.reset}>
              {labels.retry}
            </Button>
          </div>
        }
      />
    )
  }
}

import type { ReactElement, ReactNode } from 'react'
import { Field as Base } from '@base-ui/react/field'
import { cn } from 'dowel-ui'

/*
 * Field - the label, the control, and what the form has to say about it.
 *
 * Every form is the same four parts repeated: a name for the control, the
 * control, sometimes a hint, and sometimes an error. Written by hand each
 * time, they drift - the label loses its `htmlFor`, the hint is a `<div>` no
 * screen reader mentions, the error appears in red and is announced by
 * nothing at all. This is that arrangement, once.
 *
 * The wiring is the point, and Base UI does it: the label points at the
 * control, the description and the error are named by `aria-describedby`, and
 * the control is marked invalid while an error is showing. None of that is
 * visible when it works, which is exactly why a product stops doing it.
 *
 * `error` is a string this is given, not a rule this enforces. dowel has no
 * opinion about where the string came from - Base UI's own `validate`, a
 * schema, react-hook-form, or a server that just said no - because a design
 * system that picked a form library would be choosing for products that
 * already chose. The one thing it insists on is that an error, once it
 * exists, is announced and points at the field it belongs to.
 *
 * The label is always rendered. A field whose name is only a placeholder
 * loses that name the moment someone types, and a placeholder is not a label
 * to anything that reads the page aloud; `labelHidden` takes it off the
 * screen and leaves it in the accessibility tree.
 */

export interface FieldProps {
  /** What the control is called. Always rendered; `labelHidden` only takes it
   * off the screen. */
  label: ReactNode
  /** The control itself - Input, Textarea, Select, Checkbox, anything.
   *
   * A single element rather than arbitrary nodes, because it is handed to
   * Base UI to carry the field's id and its `aria-*` wiring. Two children, or
   * a bare string, would leave the label naming nothing. */
  children: ReactElement
  /** A hint under the control. Hidden while an error is showing: two lines of
   * small print under one field is one line too many, and the error is the
   * one that matters. */
  help?: ReactNode
  /** What is wrong, if anything. Its presence is what marks the control
   * invalid - there is no separate `invalid` prop to keep in step. */
  error?: ReactNode
  /** Keep the label for screen readers but take it off the screen. For a
   * field whose meaning is obvious in context - a search box in a toolbar. */
  labelHidden?: boolean
  className?: string
  /** Marks the field required, which is a statement about the form rather
   * than about validation: the label gets the mark a reader looks for. */
  required?: boolean
  /** The control's `name`, forwarded so a `Form` can attach a server error to
   * this field by name. */
  name?: string
  disabled?: boolean
}

export function Field({
  label,
  children,
  help,
  error,
  labelHidden = false,
  className,
  required = false,
  name,
  disabled = false,
}: FieldProps) {
  const invalid = error !== undefined && error !== null && error !== false

  return (
    <Base.Root
      name={name}
      disabled={disabled}
      // Base UI marks the control invalid from its own validity state; this
      // says so for an error that arrived from anywhere else.
      invalid={invalid || undefined}
      className={cn('flex flex-col gap-1.5', className)}
    >
      <Base.Label
        className={cn(
          'text-2xs font-medium uppercase tracking-caption text-faint',
          // Off the screen, still in the accessibility tree. Not
          // `display: none`, which would take it out of both.
          labelHidden && 'sr-only',
        )}
      >
        {label}
        {required && (
          <span aria-hidden className="ml-0.5 text-bad">
            *
          </span>
        )}
      </Base.Label>

      {/* The control is handed to Base UI rather than merely nested inside
        * it. This is the whole component: a plain child renders a label whose
        * `for` points at an id nothing carries, so the label looks wired and
        * names nothing - which is exactly the bug this exists to prevent, and
        * it is invisible in a screenshot. `render` gives the child the id,
        * `aria-labelledby` and `aria-describedby` instead. */}
      <Base.Control render={children} />

      {/* The error wins the one line under the control. `match` is not used:
        * the string is already the decision - this renders whatever it was
        * handed rather than asking the browser what is wrong. */}
      {invalid ? (
        <Base.Error className="text-xs text-bad" match>
          {error}
        </Base.Error>
      ) : (
        help !== undefined && <Base.Description className="text-xs text-dim">{help}</Base.Description>
      )}
    </Base.Root>
  )
}

import { useCallback, useId, useRef, useState, type DragEvent, type ReactNode } from 'react'
import { cn } from 'dowel-ui'

/*
 * FileDrop.
 *
 * A place to put files: drag them onto it, or press it and pick them. It takes
 * files and hands them over - it does not upload them. Where they go, with
 * which credentials, retried how - that is the product's transport, and a
 * primitive that owned it would be wrong for every product whose upload does
 * not look like the one it guessed.
 *
 * The boundary is the same one `Field` draws around validation: the component
 * knows the shape of the interaction, the product knows what the interaction
 * means.
 *
 * The parts that are easy to get wrong, and are therefore here:
 *
 * - **A real `<input type="file">` underneath.** Not a div with a click
 *   handler. The native input is what makes the keyboard work, what the
 *   operating system's file picker attaches to, and what a screen reader
 *   announces as a file field. It is visually hidden, not `display: none` -
 *   hidden that way it is unfocusable, and the label stops reaching it.
 * - **The drag counter.** `dragleave` fires when the pointer crosses onto a
 *   *child* of the drop zone, so a zone that toggles on leave flickers as the
 *   pointer moves over its own text. Counting enters and leaves is the fix,
 *   and it is the single commonest defect in hand-written drop zones.
 * - **`dragover` must be prevented.** Without it the browser navigates to the
 *   file instead of dropping it - the drop appears to do nothing, and the page
 *   is replaced by a PDF.
 * - **Rejected files are reported, not swallowed.** A file dropped and
 *   silently ignored looks like a broken page. What is wrong with it is the
 *   product's word, so `onReject` hands back the file and the reason.
 */

/** Why a file was not accepted. The product turns this into a sentence. */
export type FileRejection = {
  file: File
  reason: 'type' | 'size' | 'count'
}

export interface FileDropProps {
  /** Called with the files that passed the filters. */
  onFiles: (files: File[]) => void
  /** Called with the ones that did not, so the product can say why. */
  onReject?: (rejections: FileRejection[]) => void
  /** What to take, in the form `<input accept>` uses: `image/*`, `.pdf,.docx`. */
  accept?: string
  /** Largest file, in bytes. */
  maxSize?: number
  /** How many at once. Without it, any number. */
  maxFiles?: number
  /** Whether several may be chosen in the picker. */
  multiple?: boolean
  disabled?: boolean
  /** What the zone says. The product's words, in the product's language. */
  children?: ReactNode
  className?: string
  id?: string
  /** Names the field for a screen reader, when there is no visible label. */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-describedby'?: string
}

/** Whether a file matches an `accept` list. Handles the three forms the
 * attribute takes: an extension, a full type, and a wildcard type. */
function matchesAccept(file: File, accept: string | undefined): boolean {
  if (!accept) return true
  return accept
    .split(',')
    .map((entry) => entry.trim().toLowerCase())
    .filter(Boolean)
    .some((entry) => {
      if (entry.startsWith('.')) return file.name.toLowerCase().endsWith(entry)
      if (entry.endsWith('/*')) return file.type.toLowerCase().startsWith(entry.slice(0, -1))
      return file.type.toLowerCase() === entry
    })
}

export function FileDrop({
  onFiles,
  onReject,
  accept,
  maxSize,
  maxFiles,
  multiple,
  disabled,
  children,
  className,
  id,
  ...aria
}: FileDropProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  const generatedId = useId()
  const inputId = id ?? generatedId

  /* Nested elements each fire their own enter and leave as the pointer crosses
   * them, so a boolean would flicker while the pointer moves across the zone's
   * own label. The depth counter is what makes "still inside" answerable. */
  const [depth, setDepth] = useState(0)
  const over = depth > 0

  const take = useCallback(
    (list: FileList | null) => {
      if (!list) return
      const incoming = Array.from(list)
      const accepted: File[] = []
      const rejected: FileRejection[] = []

      for (const file of incoming) {
        if (!matchesAccept(file, accept)) rejected.push({ file, reason: 'type' })
        else if (maxSize !== undefined && file.size > maxSize) rejected.push({ file, reason: 'size' })
        else if (maxFiles !== undefined && accepted.length >= maxFiles)
          rejected.push({ file, reason: 'count' })
        else accepted.push(file)
      }

      if (accepted.length) onFiles(accepted)
      if (rejected.length) onReject?.(rejected)
    },
    [accept, maxFiles, maxSize, onFiles, onReject],
  )

  const onDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setDepth(0)
    if (disabled) return
    take(event.dataTransfer.files)
  }

  return (
    <div
      onDragEnter={(event) => {
        event.preventDefault()
        setDepth((d) => d + 1)
      }}
      onDragLeave={(event) => {
        event.preventDefault()
        setDepth((d) => Math.max(0, d - 1))
      }}
      // Without preventing this, the browser opens the dropped file instead,
      // and the page the reader was filling in is simply gone.
      onDragOver={(event) => event.preventDefault()}
      onDrop={onDrop}
      // Presentational: the input inside is the control, and wrapping it in a
      // second interactive element would give a screen reader two.
      className={cn(
        'rounded-lg border border-dashed border-line bg-raise p-6 text-center transition-colors',
        over && !disabled && 'border-accent bg-accent-soft',
        disabled && 'pointer-events-none opacity-50',
        className,
      )}
    >
      <label htmlFor={inputId} className={cn('block', !disabled && 'cursor-pointer')}>
        {children}
      </label>
      <input
        ref={inputRef}
        id={inputId}
        type="file"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        {...aria}
        onChange={(event) => {
          take(event.target.files)
          // Cleared so that choosing the same file twice in a row still fires
          // a change - otherwise the second attempt silently does nothing.
          event.target.value = ''
        }}
        /* Visually hidden, not `hidden`: it stays focusable, keeps its place
         * in the tab order, and the label above still points at a real
         * control. `display: none` would take all three away. */
        className="sr-only"
      />
    </div>
  )
}

import type { InputHTMLAttributes, Ref } from 'react'
import { cn } from 'dowel-ui'

/*
 * Input.
 *
 * A single-line field. It is a plain `<input>` with the line's clothes on, so
 * everything a browser gives an input for free - autofill, spellcheck, the
 * right keyboard on a phone, `type="email"` validation - still works.
 *
 * The focus ring is the accent, drawn outside the border rather than replacing
 * it: a field that only changes colour on focus is invisible to anyone who
 * cannot distinguish those two colours.
 */
export const fieldClasses = cn(
  'w-full rounded-md border border-line bg-transparent px-2.5 py-1.5',
  'text-sm text-text placeholder:text-faint',
  'transition-colors hover:border-line-2',
  'focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-accent',
  // A field nobody can type in should look like one.
  'disabled:cursor-not-allowed disabled:opacity-50',
  // `aria-invalid` rather than a prop: the attribute is what a screen reader
  // reads, so making it the source of the colour keeps the two in step.
  'aria-invalid:border-bad aria-invalid:focus-visible:outline-bad',
)

export interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  /** React 19 passes `ref` as a plain prop; it is declared so callers can
   * reach the element to focus it or read its selection. */
  ref?: Ref<HTMLInputElement>
}

export function Input({ className, ref, ...props }: InputProps) {
  return <input ref={ref} className={cn(fieldClasses, 'h-9', className)} {...props} />
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Kbd.
 *
 * A key, as printed in a menu or a hint: `Ctrl` `K`. It is a `<kbd>` element
 * because that is what the element is for - a screen reader announces it as
 * keyboard input rather than reading a stray capital letter.
 *
 * The platform substitution is the useful part. A shortcut written `Ctrl+K` is
 * wrong on a Mac, where the same shortcut is `⌘K`, and every product either
 * hard-codes one of them or writes the branch again.
 */

/** Whether this machine writes shortcuts the Apple way. */
function isApplePlatform(): boolean {
  if (typeof navigator === 'undefined') return false
  return /mac|iphone|ipad|ipod/i.test(navigator.platform || navigator.userAgent)
}

/** What a key is called here. `Mod` is the one that differs: command on Apple
 * platforms, control everywhere else. */
export function keyLabel(key: string, apple: boolean = isApplePlatform()): string {
  const shared: Record<string, string> = {
    Enter: '↵',
    Escape: 'Esc',
    ArrowUp: '↑',
    ArrowDown: '↓',
    ArrowLeft: '←',
    ArrowRight: '→',
    Backspace: '⌫',
    Tab: '⇥',
    Space: '␣',
  }
  const perPlatform: Record<string, [apple: string, other: string]> = {
    Mod: ['⌘', 'Ctrl'],
    Alt: ['⌥', 'Alt'],
    Shift: ['⇧', 'Shift'],
  }

  const platform = perPlatform[key]
  if (platform) return apple ? platform[0] : platform[1]
  return shared[key] ?? key
}

export interface KbdProps extends HTMLAttributes<HTMLElement> {
  /** Keys of a shortcut, in order: `['Mod', 'K']`. Given this, the component
   * writes the separators and the platform's own names. */
  keys?: string[]
}

export function Kbd({ keys, className, children, ...props }: KbdProps) {
  const cap = cn(
    'inline-flex min-w-5 items-center justify-center rounded-sm border border-line bg-soft',
    'px-1 py-0.5 font-mono text-2xs leading-none text-dim',
  )

  if (!keys) {
    return (
      <kbd className={cn(cap, className)} {...props}>
        {children}
      </kbd>
    )
  }

  return (
    <span className={cn('inline-flex items-center gap-0.5', className)} {...props}>
      {keys.map((key) => (
        <kbd key={key} className={cap}>
          {keyLabel(key)}
        </kbd>
      ))}
    </span>
  )
}

import { createContext, useContext, type HTMLAttributes, type ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * A list of facts: a name, and what it is.
 *
 * The shape every product builds out of two `<div>`s in a flex row, and the
 * reason it is worth having once: it is a `<dl>`, and the pairing is what a
 * screen reader announces. Two divs read as four unrelated pieces of text -
 * "Created", "2 hours ago", "Owner", "Ines" - and nothing says which value
 * belongs to which name. The right element says it for free.
 *
 * Two layouts, and both exist because the same list sits in two places: beside
 * something (a panel of properties, names in one column) and under a heading
 * (a card, name above value). A product moving a panel should not have to
 * change component.
 *
 * The layouts need *different markup*, and that is why the row reads the
 * layout from context rather than taking a prop:
 *
 *   **rows** puts `<dt>`/`<dd>` directly in the grid, so every value lines up
 *   in one column. Wrap each pair in a `<div>` and each pair becomes its own
 *   box - the values then sit at a different place on every line, which is
 *   exactly the ragged look this component exists to stop.
 *
 *   **stacked** wraps each pair, because without a wrapper the column gaps
 *   fall between `dt` and `dd` as readily as between pairs, and a list of six
 *   facts reads as twelve unrelated lines.
 *
 * Both are valid `<dl>`: the spec allows `dt`/`dd` as direct children, and
 * allows a `<div>` per pair. What it does not allow is any other element
 * between them, which is why the pair is a component rather than something the
 * caller assembles.
 */

export const keyValueVariants = cva('text-sm', {
  variants: {
    layout: {
      rows: 'grid grid-cols-[minmax(0,auto)_minmax(0,1fr)] items-baseline gap-x-4 gap-y-2',
      stacked: 'flex flex-col gap-3',
    },
  },
  defaultVariants: { layout: 'rows' },
})

type Layout = NonNullable<VariantProps<typeof keyValueVariants>['layout']>

/* The row has to know the layout to know whether to wrap. Context rather than
 * a prop on every row: a list whose rows disagree with it is not a thing
 * anyone wants, and repeating the value at each row is how they come to. */
const LayoutContext = createContext<Layout>('rows')

export interface KeyValueProps
  extends HTMLAttributes<HTMLDListElement>,
    VariantProps<typeof keyValueVariants> {}

export function KeyValue({ layout, className, ...props }: KeyValueProps) {
  return (
    <LayoutContext.Provider value={layout ?? 'rows'}>
      <dl className={cn(keyValueVariants({ layout }), className)} {...props} />
    </LayoutContext.Provider>
  )
}

export interface KeyValueRowProps {
  /** The name of the fact. */
  label: ReactNode
  /** What it is. A node rather than a string: half the values in a real panel
   * are a Badge, a RelativeTime or a link. */
  children: ReactNode
  className?: string
}

/** One pair. */
export function KeyValueRow({ label, children, className }: KeyValueRowProps) {
  const layout = useContext(LayoutContext)

  const value = <dd className="min-w-0 text-text">{children}</dd>

  // Wrapped, so the column's gap falls between pairs rather than inside one,
  // and the caller's class dresses the pair as a whole.
  if (layout === 'stacked') {
    return (
      <div className={cn('flex flex-col gap-0.5', className)}>
        <dt className="text-dim">{label}</dt>
        {value}
      </div>
    )
  }

  /* Directly in the grid, so every value shares one column - there is no
   * wrapper here to carry the caller's class, so it dresses the term. That is
   * the half a caller styles: the value's own appearance comes from whatever
   * it renders. */
  return (
    <>
      <dt className={cn('text-dim', className)}>{label}</dt>
      {value}
    </>
  )
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { boundsOf, pathOf, runs, ticksFor, yOf, type Bounds, type Point } from './line-scale'

/*
 * A quantity over time, where it continues between the readings.
 *
 * The distinction against its neighbours is the data's, not the drawing's. A
 * column says each period is its own sum - hours worked in a week, and there
 * is no Wednesday-afternoon figure between two weeks. A line says the value
 * existed the whole time and was sampled: an account balance, a price, a
 * temperature. Drawing a sum as a line claims readings nobody took; drawing a
 * level as columns throws away the thing being watched.
 *
 * Sparkline is the same shape with the axes taken away, for beside a figure.
 * This one has them, because a balance without a scale is a squiggle.
 *
 * **A hole breaks the line.** Interpolating across invents a reading; closing
 * the gap up moves every later point and makes the axis lie about when things
 * happened. Both are quieter than the truth, which is why the truth has to be
 * drawn deliberately.
 *
 * **The floor is not zero unless the caller says so**, and that is a departure
 * from BarChart on purpose. A bar's length is the quantity, so its baseline
 * has to be zero. A line's subject is change, and a balance between 4,900 and
 * 5,100 on a zero-based axis is a flat rule. The ticks are what keep this
 * honest: they say where the bottom is.
 *
 * The plot owns its height in pixels, for the reason BarChart does - a
 * percentage against a parent with no height of its own resolves to zero, and
 * the chart disappears without failing.
 */

export const lineChartVariants = cva('relative w-full', {
  variants: {
    size: {
      sm: '[--plot:96px]',
      md: '[--plot:160px]',
    },
    /* Room on the right for the tick labels. Drawn inside the plot they sit on
     * top of whatever the line is doing there - found by looking, with `$5,200`
     * crossed out by its own series. A gutter costs a little width and cannot
     * collide. */
    gutter: {
      true: 'pr-12',
      false: '',
    },
  },
  defaultVariants: { size: 'md', gutter: true },
})

export const lineVariants = cva('fill-none', {
  variants: {
    tone: {
      accent: 'stroke-accent',
      series: 'stroke-series-1',
      good: 'stroke-good',
      bad: 'stroke-bad',
      muted: 'stroke-dim',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export interface LineChartProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    VariantProps<typeof lineChartVariants>,
    VariantProps<typeof lineVariants> {
  /** The readings, in order. `value: null` is a measurement not taken. */
  points: Point[]
  /** Override any edge of the plot. `min: 0` for a count, where zero is the
   * truth rather than a flattening. */
  bounds?: Partial<Bounds>
  /** What the chart as a whole says, for a reader who cannot see it. */
  label: string
  /** How many value ticks to aim for. They land on round numbers, so the count
   * is a wish rather than a promise. `0` draws none. */
  ticks?: number
  /** Turns a tick into its label. Without it the number is drawn as it is -
   * which is right for a count and wrong for money or a duration. */
  formatTick?: (value: number) => string
  /** The labels under the axis - usually the first and last reading. Two or
   * three, not one per point: the axis is not a place for a list. */
  footer?: ReactNode
}

export function LineChart({
  points,
  bounds: stated,
  label,
  ticks = 4,
  formatTick,
  footer,
  tone,
  size,
  className,
  ...props
}: LineChartProps) {
  const bounds = boundsOf(points, stated)

  /* Nothing measured is not a chart of zeroes: an empty plot with its axis is
   * the honest drawing, and the caller says so in words beside it. */
  if (bounds === null) {
    return (
      <div
        className={cn(lineChartVariants({ size, gutter: false }), className)}
        role="img"
        aria-label={label}
        {...props}
      >
        <div className="h-[var(--plot)] w-full border-b border-chart-axis" />
      </div>
    )
  }

  const drawn = runs(points, bounds)
  const rules = ticks > 0 ? ticksFor(bounds, ticks) : []

  return (
    <div
      className={cn(lineChartVariants({ size, gutter: rules.length > 0 }), className)}
      role="img"
      aria-label={label}
      {...props}
    >
      <div className="relative h-[var(--plot)] w-full border-b border-chart-axis">
        {rules.map((tick) => {
          const y = yOf(tick, bounds)
          if (y === null) return null
          return (
            <div key={tick} className="pointer-events-none absolute inset-x-0" style={{ top: `${y}%` }}>
              {/* Solid hairline: a dashed rule reads as a threshold or a
                * projection, and this is neither. */}
              <div className="h-px w-full bg-chart-grid" />
              {/* Outside the plot, in the gutter the variant reserves: a label
                * drawn over the series is a label crossed out by it. */}
              <span className="absolute -top-1.5 left-full pl-1.5 text-[10px] leading-none text-faint tabular-nums">
                {formatTick ? formatTick(tick) : tick}
              </span>
            </div>
          )
        })}

        {/* `preserveAspectRatio="none"` is what lets the plot be a box of the
          * caller's shape while the maths stays in percentages: x and y scale
          * independently, which would bend a shape but cannot bend a line
          * whose every segment is straight. The stroke is drawn in absolute
          * units so it does not stretch with the box. */}
        <svg
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          className="absolute inset-0 h-full w-full overflow-visible"
          aria-hidden
        >
          {drawn.map((run) => (
            <path
              key={run[0]!.at}
              d={pathOf(run)}
              vectorEffect="non-scaling-stroke"
              strokeWidth={2}
              strokeLinecap="round"
              strokeLinejoin="round"
              className={cn(lineVariants({ tone }))}
            />
          ))}
        </svg>
      </div>

      {footer !== undefined && (
        <div className="mt-1 flex justify-between text-[10px] text-faint tabular-nums">{footer}</div>
      )}
    </div>
  )
}

/*
 * The arithmetic behind LineChart, with no React in it.
 *
 * Split out like `track-segments` and `activity-weeks`: a product labelling
 * its own points, or checking its own domain sums, should not import a
 * component to get at the numbers.
 *
 * Two things live here and neither is obvious. Turning a series with holes in
 * it into drawable runs, and choosing the ticks on an axis - which is a
 * question about what reads as a round number, not about dividing a range into
 * equal parts.
 */

/** One reading. `value: null` is a measurement that was not taken - which is
 * not a reading of zero, and not a reason to move the ones after it. */
export interface Point {
  /** Position along the axis. Same units throughout: a timestamp, an index. */
  at: number
  value: number | null
}

export interface Bounds {
  /** The value the left edge stands for. */
  from: number
  /** The right edge. */
  to: number
  /** The bottom of the plot. */
  min: number
  /** The top. */
  max: number
}

/** A point placed in the box, in percentages: x from the left, y from the top
 * (SVG's own direction, so a larger value has a smaller y). */
export interface Placed {
  x: number
  y: number
  at: number
  value: number
}

/**
 * The bounds a series is drawn against.
 *
 * The y range does NOT start at zero by default, and that is a deliberate
 * departure from the bar's rule. A bar's length *is* the quantity, so its
 * baseline has to be zero or the length lies. A line's job is the shape of a
 * change, and a balance moving between 4,900 and 5,100 flattens into a
 * horizontal rule on a zero-based axis - the very thing the reader opened the
 * chart to see. What keeps it honest is that the axis is labelled: the ticks
 * say where the bottom is, so nobody reads the floor as nothing.
 *
 * A caller who wants zero states it, and for a quantity that is a count rather
 * than a level - requests, errors - they should.
 */
export function boundsOf(points: Point[], stated: Partial<Bounds> = {}): Bounds | null {
  const drawn = points.filter((point): point is Point & { value: number } => point.value !== null)
  if (drawn.length === 0) return null

  const values = drawn.map((point) => point.value)
  const positions = points.map((point) => point.at)

  const from = stated.from ?? Math.min(...positions)
  const to = stated.to ?? Math.max(...positions)

  let min = stated.min ?? Math.min(...values)
  let max = stated.max ?? Math.max(...values)

  /* A flat series has no range to scale against, and dividing by it would put
   * every point at the same y - or at NaN. Given a band around the value, the
   * line sits in the middle of the plot and reads as what it is: unchanging. */
  if (!(max > min)) {
    const pad = Math.abs(max) > 0 ? Math.abs(max) * 0.1 : 1
    min = max - pad
    max = max + pad
  }

  return { from, to, min, max }
}

/**
 * The series as runs of consecutive readings.
 *
 * A hole breaks the line rather than being drawn through or closed up, and the
 * three options are worth naming because two of them lie:
 *
 *   **Interpolating across** invents a reading nobody took - the one thing a
 *   chart of measurements must never do.
 *
 *   **Dropping the point** keeps the line whole and moves every later reading
 *   to the left, so the axis stops matching the data: a chart that says the
 *   value was 40 in March when it was 40 in April.
 *
 *   **Breaking the line** leaves the gap visible, keeps every other point
 *   where it belongs, and invents nothing. So that is what happens here.
 *
 * A run of one point is kept: it has no line, but it has a dot, and dropping
 * it would hide a reading that exists.
 */
export function runs(points: Point[], bounds: Bounds): Placed[][] {
  const span = bounds.to - bounds.from
  const height = bounds.max - bounds.min
  if (!(span > 0) || !(height > 0)) return []

  const out: Placed[][] = []
  let run: Placed[] = []

  for (const point of points) {
    if (point.value === null) {
      if (run.length > 0) out.push(run)
      run = []
      continue
    }

    const clamped = Math.min(Math.max(point.value, bounds.min), bounds.max)
    run.push({
      x: ((point.at - bounds.from) / span) * 100,
      // SVG's y grows downward, so the largest value sits at the top.
      y: ((bounds.max - clamped) / height) * 100,
      at: point.at,
      value: point.value,
    })
  }

  if (run.length > 0) out.push(run)
  return out
}

/** A run as an SVG path, in the same percentages.
 *
 * Straight segments rather than a curve: a spline through measured points
 * overshoots between them, inventing highs and lows that were never recorded -
 * the same lie as interpolating across a gap, drawn more prettily. */
export function pathOf(run: Placed[]): string {
  return run
    .map((point, index) => `${index === 0 ? 'M' : 'L'}${point.x.toFixed(2)} ${point.y.toFixed(2)}`)
    .join(' ')
}

/**
 * Ticks for the value axis, on round numbers.
 *
 * Not the range cut into equal parts: 4,900 to 5,100 in four gives 4,950 and
 * 5,050, which nobody reads as a landmark. A tick's job is to be recognised
 * instantly, so the step is the nearest 1, 2, 5 or 10 above what the range
 * needs, and the ticks are the multiples of it inside the range.
 *
 * Returns nothing when a step would not fit - a range too narrow for a round
 * number is better with no ticks than with invented ones.
 */
export function ticksFor(bounds: Bounds, wanted = 4): number[] {
  const height = bounds.max - bounds.min
  if (!(height > 0) || wanted < 1) return []

  const rough = height / wanted
  const magnitude = 10 ** Math.floor(Math.log10(rough))
  const step = [1, 2, 5, 10].map((n) => n * magnitude).find((candidate) => candidate >= rough)
  if (step === undefined) return []

  const ticks: number[] = []
  for (let tick = Math.ceil(bounds.min / step) * step; tick <= bounds.max; tick += step) {
    // Floating point leaves 0.30000000000000004 where 0.3 was meant; the step
    // is what decides how many decimals are real.
    const decimals = Math.max(0, -Math.floor(Math.log10(step)))
    ticks.push(Number(tick.toFixed(decimals)))
  }

  return ticks
}

/** Where a value sits in the plot, as a percentage from the top - for a tick's
 * rule, or a threshold drawn across the line. */
export function yOf(value: number, bounds: Bounds): number | null {
  const height = bounds.max - bounds.min
  if (!(height > 0)) return null
  if (value < bounds.min || value > bounds.max) return null
  return ((bounds.max - value) / height) * 100
}

import { Menu as Base } from '@base-ui/react/menu'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Menu.
 *
 * A list of actions that opens from a button - the row menu, the overflow
 * menu, the one behind the three dots. The products all wrote this by hand,
 * and all of them wrote the same three hundred lines: a click-outside
 * listener, an Escape handler, and a `stopPropagation` on every item so that
 * choosing an action does not also open the row underneath.
 *
 * None of that is what makes a menu hard. What makes it hard is the keyboard:
 * arrows that wrap, Home and End, type-ahead that finds an item by its first
 * letters, a submenu that opens on the right key and closes when the pointer
 * leaves diagonally. Base UI has all of it.
 *
 * The items are exposed rather than taken as an array of `{ label, onSelect }`.
 * An array is enough until the first separator, the first checkbox item and
 * the first submenu - and each of those arrives as another field on the object
 * rather than as the JSX it obviously is.
 */

export const menuPopupVariants = cva(
  [
    'min-w-40 rounded-md border border-line bg-raise p-1 text-text shadow-float',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        sm: 'min-w-32',
        md: 'min-w-40',
        lg: 'min-w-56',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** One row of the menu. `danger` draws the destructive one apart from the
 * rest - in the colour of something that cannot be undone. */
export const menuItemVariants = cva(
  [
    'flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm',
    'outline-none transition-colors',
    // Base UI marks the item under the pointer or the keyboard the same way,
    // so one rule covers both and they cannot disagree.
    'data-[highlighted]:bg-soft data-[highlighted]:text-text',
    'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
    '[&_svg]:size-3.5 [&_svg]:shrink-0',
  ],
  {
    variants: {
      tone: {
        default: 'text-dim data-[highlighted]:text-text',
        danger: 'text-bad data-[highlighted]:bg-bad-soft data-[highlighted]:text-bad',
      },
    },
    defaultVariants: { tone: 'default' },
  },
)

/** The root. Uncontrolled by default; `open` and `onOpenChange` make it
 * controlled. */
export const Menu = Base.Root

/** What opens it. Give it `render` to use your own button. */
export const MenuTrigger = Base.Trigger

/** A labelled group of items, for a menu long enough to need headings. */
export const MenuGroup = Base.Group

/** A submenu, opened from a `MenuSubTrigger` inside the parent. */
export const MenuSub = Base.SubmenuRoot

export interface MenuPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof menuPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Where to portal to. Defaults to the document body, which keeps the menu
   * from being clipped by a row with `overflow: hidden` - which is where most
   * hand-written ones go to die. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled and positioned against the trigger. */
export function MenuPopup({
  size,
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
  ...props
}: MenuPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(menuPopupVariants({ size }), className)} {...props}>
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

export interface MenuItemProps extends Base.Item.Props, VariantProps<typeof menuItemVariants> {}

/** An action. Closing the menu afterwards is Base UI's default, which is
 * almost always right - `closeOnClick={false}` is for the one that is not. */
export function MenuItem({ tone, className, ...props }: MenuItemProps) {
  return <Base.Item className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that opens a submenu. Drawn like any other, because it is one. */
export function MenuSubTrigger({ tone, className, ...props }: MenuItemProps) {
  return <Base.SubmenuTrigger className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** An item that carries a tick. The state is the caller's - a menu does not
 * remember anything. */
export function MenuCheckboxItem({ tone, className, ...props }: MenuItemProps) {
  return <Base.CheckboxItem className={cn(menuItemVariants({ tone }), className)} {...props} />
}

/** The tick itself, drawn only when the item is checked. */
export const MenuCheckboxIndicator = Base.CheckboxItemIndicator

/** A line between groups of items. Decorative, and marked as such: a screen
 * reader announcing "separator" between every pair of actions is noise. */
export function MenuSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

/** The caption above a group. */
export function MenuGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

import type { ReactNode } from 'react'
import { cn } from 'dowel-ui'
import { Select, SelectItem, SelectPopup, SelectTrigger, SelectValue } from './select'

/*
 * How many rows to a page.
 *
 * Its own file rather than a part of `Pagination`, because the two are needed
 * apart often enough: a list that scrolls for ever wants "how many to load at
 * a time" and no page buttons, and a table with a fixed page size wants the
 * buttons and no choice. Together they were also over the size gate, which
 * asked the right question.
 *
 * A `Select`, because the line has no native `<select>` anywhere - and this is
 * the control most likely to reintroduce one, since it is three numbers in a
 * box and looks like the case where it would not matter.
 */

export interface PageSizeProps {
  pageSize: number
  options?: number[]
  onPageSizeChange: (pageSize: number) => void
  /** Names the control for a screen reader, e.g. "Rows per page". */
  label: string
  /** The visible label, when there is room for one. */
  children?: ReactNode
  className?: string
}

export function PageSize({
  pageSize,
  options = [10, 25, 50, 100],
  onPageSizeChange,
  label,
  children,
  className,
}: PageSizeProps) {
  return (
    <div className={cn('flex items-center gap-2 text-sm text-dim', className)}>
      {children}
      <Select
        value={String(pageSize)}
        onValueChange={(value: unknown) => onPageSizeChange(Number(value))}
      >
        <SelectTrigger aria-label={label} className="w-auto min-w-16">
          <SelectValue />
        </SelectTrigger>
        <SelectPopup>
          {options.map((option) => (
            <SelectItem key={option} value={String(option)}>
              {option}
            </SelectItem>
          ))}
        </SelectPopup>
      </Select>
    </div>
  )
}

import { cn } from 'dowel-ui'
import { Button } from './button'

/*
 * Paging through a list, and choosing how much of it to see at once.
 *
 * The arithmetic is exported separately from the component for the same reason
 * `table-sort` is a file of its own: a product that pages on the server needs
 * the page numbers and not the buttons, and computing them a second time in a
 * different place is how the two disagree about where the last page ends.
 *
 * Two things this deliberately does not do.
 *
 * It does not fetch, and it does not slice. It is told the page and the total
 * and it says which page was asked for - because whether paging means an
 * `OFFSET` or an `Array.prototype.slice` is the product's business, and a
 * component that guesses gets it wrong for the other one.
 *
 * It does not show every page number. A list of forty pages drawn in full is a
 * row of forty targets nobody aims at; `pageWindow` gives first, last, the
 * neighbourhood of the current page, and a gap where the rest were.
 *
 * How many rows to a page is next door, in `PageSize`. They are two controls
 * that usually sit together and are needed apart often enough to be separate:
 * a list that scrolls for ever wants "how many to load at a time" and no page
 * buttons, and a table with a fixed page size wants the buttons and no choice.
 */

/** A step in the row of pages: a page to go to, or the gap where pages were
 * left out. The gap is not a page and is never clickable - rendering it as a
 * disabled button gives a keyboard three stops that lead nowhere. */
export type PageStep = number | 'gap'

/** How many pages a list of this size has. At least one: a list with nothing
 * in it is on page 1 of 1, not page 1 of 0, and the second reads as broken. */
export function pageCount(total: number, pageSize: number): number {
  if (pageSize <= 0) return 1
  return Math.max(1, Math.ceil(total / pageSize))
}

/** The row of pages to draw: first, last, the current page and its
 * neighbours, with a gap standing in for the rest.
 *
 * `around` is how many pages sit either side of the current one. The row keeps
 * a steady width as the reader pages through it, because a row that grows and
 * shrinks moves the buttons under the pointer.
 */
export function pageWindow(page: number, pages: number, around = 1): PageStep[] {
  const total = Math.max(1, pages)
  const current = Math.min(Math.max(1, page), total)

  // How many places the row has: first, last, a gap at each end, and the
  // neighbourhood between them. This is the number the row always fills.
  const width = around * 2 + 5
  if (total <= width) {
    return Array.from({ length: total }, (_, index) => index + 1)
  }

  /* The row is built to a fixed number of places, and that is the whole
   * difficulty. A window of a fixed number of *pages* looks right in the
   * middle and comes up short at the ends, where one of the gaps is not
   * needed: the row loses a place, and the "next" button moves as you use it.
   *
   * So the run of middle pages is grown to whatever fills the row - which
   * depends on how many gaps there are, which depends on where the run sits.
   * Rather than iterate towards that (it oscillates on the pages either side
   * of an end, where dropping a gap moves the run and moving the run brings
   * the gap back), each possible number of gaps is tried and the one that
   * describes itself is kept.
   */
  for (const gaps of [2, 1, 0]) {
    // Places for pages: the row, less the two ends, less the gaps.
    const run = width - 2 - gaps
    if (run > total - 2) continue
    // Centre the run on the current page, then slide it inside the ends. The
    // clamp is what pushes the neighbourhood away from an edge rather than
    // clipping it there.
    let from = Math.min(Math.max(2, current - Math.floor((run - 1) / 2)), total - run)

    // A gap that stands for a single page is a lie that costs a click: `1 … 3`
    // hides only page 2, which the row had room for. The fix is to slide the
    // run onto the end rather than to drop the page: leaving it out silently
    // is worse than the gap, because then the row says 1 is followed by 3 and
    // gives no sign that anything is missing.
    if (from === 3) from = 2
    if (from + run - 1 === total - 2) from += 1
    const to = from + run - 1

    const before = from > 2
    const after = to < total - 1
    if (Number(before) + Number(after) !== gaps) continue

    const steps: PageStep[] = [1]
    if (before) steps.push('gap')
    for (let page = from; page <= to; page += 1) steps.push(page)
    if (after) steps.push('gap')
    steps.push(total)
    return steps
  }

  // Unreachable for `total > width`: with no gaps the run covers every middle
  // page, which is the case handled above. Kept so the function has an answer
  // for every input rather than an implicit `undefined`.
  return Array.from({ length: total }, (_, index) => index + 1)
}

/** Which rows this page holds: `[from, to]`, counting from one, for the "1-20
 * of 97" a reader is shown. `to` is clamped to the total, so the last page
 * says what it actually holds rather than what a full page would. */
export function pageRange(page: number, pageSize: number, total: number): [number, number] {
  if (total <= 0) return [0, 0]
  const from = (page - 1) * pageSize + 1
  return [from, Math.min(page * pageSize, total)]
}

export interface PaginationProps {
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  /** How many pages either side of the current one. */
  around?: number
  /** What a screen reader hears for the region and its buttons. Required
   * rather than defaulted: a default here would be English shipped inside a
   * primitive, and these are the only words the control has. */
  labels: PaginationLabels
  className?: string
}

export interface PaginationLabels {
  /** Names the whole control, e.g. "Pages". */
  region: string
  previous: string
  next: string
  /** Names one page button. Given the number, because "Page 3" is a sentence
   * only the product's language can build. */
  page: (page: number) => string
}

export function Pagination({
  page,
  pageSize,
  total,
  onPageChange,
  around = 1,
  labels,
  className,
}: PaginationProps) {
  const pages = pageCount(total, pageSize)
  const current = Math.min(Math.max(1, page), pages)
  const steps = pageWindow(current, pages, around)

  return (
    <nav aria-label={labels.region} className={cn('flex items-center gap-1', className)}>
      <Button
        variant="ghost"
        size="sm"
        aria-label={labels.previous}
        disabled={current <= 1}
        onClick={() => onPageChange(current - 1)}
      >
        ‹
      </Button>

      {steps.map((step, index) =>
        step === 'gap' ? (
          // Not a button, and not `aria-hidden` either: the gap is real
          // information - there are pages here that are not shown - and a
          // reader that skips it hears a jump from 2 to 40 with no reason.
          <span
            // The index is the key on purpose: two gaps in a row are
            // indistinguishable, and there is never more than one at each end.
            key={`gap-${index}`}
            className="px-1 text-dim select-none"
          >
            …
          </span>
        ) : (
          <Button
            key={step}
            variant={step === current ? 'primary' : 'ghost'}
            size="sm"
            // The current page is announced, not only coloured. `aria-current`
            // rather than `aria-selected`, which belongs to a listbox.
            aria-current={step === current ? 'page' : undefined}
            aria-label={labels.page(step)}
            onClick={() => onPageChange(step)}
            className="tabular-nums"
          >
            {step}
          </Button>
        ),
      )}

      <Button
        variant="ghost"
        size="sm"
        aria-label={labels.next}
        disabled={current >= pages}
        onClick={() => onPageChange(current + 1)}
      >
        ›
      </Button>
    </nav>
  )
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Panel.
 *
 * The raised surface everything else sits on. It is the one place a screen
 * gets its structure from, so it stays deliberately plain: a ground, a
 * hairline, a corner.
 *
 * The two products it came from disagreed about that corner - one used 16px,
 * the other 12px, for the component with the same name and the same purpose.
 * It is `lg` here, and `SectionLabel` is included because a panel almost
 * always has one and every product wrote its own.
 */
export const panelVariants = cva('bg-raise', {
  variants: {
    variant: {
      /* The default: a surface that sits on the page. */
      raised: 'rounded-lg border border-line',
      /* For something that has left the page - a menu, a popover. The shadow
       * is what says how far away it is. */
      floating: 'rounded-lg border border-line shadow-raise',
      /* Inside another panel, where a second border would be a box in a box. */
      inset: 'rounded-inner bg-soft',
    },
  },
  defaultVariants: { variant: 'raised' },
})

export interface PanelProps
  extends HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof panelVariants> {}

export function Panel({ variant, className, ...props }: PanelProps) {
  return <div className={cn(panelVariants({ variant }), className)} {...props} />
}

/**
 * The small uppercase caption above a block of content.
 *
 * Its tracking is the one the products argued about - 0.08em in six files and
 * 0.09em in three - and it is a token now, so the argument cannot recur.
 */
export function SectionLabel({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        'flex items-center gap-2 text-2xs font-medium uppercase tracking-caption text-faint',
        className,
      )}
      {...props}
    />
  )
}

import { useId, useState, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * PasswordField - a password, and the button that shows it.
 *
 * The reveal is the whole component, and it is not a convenience. A masked
 * field is the only one in a form where a typo cannot be seen, so people
 * either paste (fine) or type slowly and get it wrong anyway; the toggle is
 * what turns an unverifiable field into a checkable one, and it is why long
 * passphrases became usable at all.
 *
 * What it costs is a moment where the password is on the screen, so the
 * component states its two rules rather than leaving them to each product:
 *
 *   - it always starts masked, and there is no prop to start it revealed;
 *   - revealing is the reader's own action, never a default and never
 *     something a form can turn on for them.
 *
 * The button is a real button with a real name, and the name changes with the
 * state - "Show password" / "Hide password". That is what a screen reader
 * announces, and it is the one place the component needs words, so they are
 * required props. A default here would ship English inside a primitive.
 *
 * `autoComplete` is not defaulted either. The right value is the product's
 * to know: `current-password` on a login, `new-password` on a sign-up, and
 * getting it wrong is how a password manager fills the wrong box.
 */

export interface PasswordFieldProps {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** What the reveal button is called while the password is hidden. */
  showLabel: string
  /** ...and while it is showing. */
  hideLabel: string
  /** `current-password` for a login, `new-password` for a sign-up. */
  autoComplete?: string
  placeholder?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  id?: string
  ref?: Ref<HTMLInputElement>
  'aria-label'?: string
  'aria-describedby'?: string
  className?: string
}

export function PasswordField({
  value,
  defaultValue,
  onValueChange,
  showLabel,
  hideLabel,
  className,
  disabled,
  ref,
  ...props
}: PasswordFieldProps) {
  /* Always false to begin with. Deliberately local state with no prop to set
   * it: a password that arrives on screen without the reader asking is the
   * one failure this component must not have. */
  const [revealed, setRevealed] = useState(false)
  const inputId = useId()

  return (
    <div
      className={cn(
        fieldClasses,
        'flex h-9 items-stretch overflow-hidden p-0',
        'focus-within:outline-2 focus-within:outline-offset-0 focus-within:outline-accent',
        className,
      )}
    >
      <input
        {...props}
        ref={ref}
        id={props.id ?? inputId}
        type={revealed ? 'text' : 'password'}
        value={value}
        defaultValue={defaultValue}
        disabled={disabled}
        onChange={(event) => onValueChange?.(event.target.value)}
        className={cn(
          'w-full min-w-0 bg-transparent px-2.5 text-sm text-text placeholder:text-faint',
          'outline-none disabled:cursor-not-allowed',
        )}
      />

      <button
        type="button"
        // Not a submit button, and not in the tab order ahead of the field it
        // belongs to - it sits after the input, which is where Tab reaches it.
        onClick={() => setRevealed((was) => !was)}
        disabled={disabled}
        aria-label={revealed ? hideLabel : showLabel}
        aria-pressed={revealed}
        aria-controls={props.id ?? inputId}
        className={cn(
          'flex w-9 shrink-0 items-center justify-center text-dim',
          'transition-colors hover:bg-soft hover:text-text',
          'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent',
          'disabled:pointer-events-none disabled:opacity-50',
        )}
      >
        {revealed ? (
          /* An eye with a stroke through it: hiding is the action offered
           * while the password is visible. */
          <svg viewBox="0 0 20 20" className="size-4" fill="none" aria-hidden>
            <path
              d="M4 4l12 12M8.5 8.7a2 2 0 002.8 2.8M6.3 6.4C4.4 7.5 3 9.2 2.5 10c1.2 2.2 4 5 7.5 5 1.3 0 2.5-.4 3.5-1M9 5.1c.3 0 .7-.1 1-.1 3.5 0 6.3 2.8 7.5 5-.3.5-.8 1.3-1.6 2.1"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        ) : (
          <svg viewBox="0 0 20 20" className="size-4" fill="none" aria-hidden>
            <path
              d="M2.5 10C3.7 7.8 6.5 5 10 5s6.3 2.8 7.5 5c-1.2 2.2-4 5-7.5 5s-6.3-2.8-7.5-5z"
              stroke="currentColor"
              strokeWidth="1.5"
            />
            <circle cx="10" cy="10" r="2.2" stroke="currentColor" strokeWidth="1.5" />
          </svg>
        )}
      </button>
    </div>
  )
}

import { Popover as Base } from '@base-ui/react/popover'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Popover.
 *
 * A panel anchored to the thing that opened it, for content that belongs
 * beside a control rather than in the middle of the screen: a filter, a small
 * form, a menu of settings that is not a menu.
 *
 * Where Dialog is centred and covers the page, this one is placed, and the
 * placing is the part that is easy to get wrong. It goes through a Positioner
 * between the Portal and the Popup - Base UI measures the trigger, measures
 * the popup, and flips or shifts it when the preferred side does not fit. So
 * `side` and `align` are a preference, not an instruction, and a popover near
 * the bottom of the window will come out above its trigger. That is the
 * behaviour worth having; a popover that stays where it was told is a popover
 * half off the screen.
 *
 * `sideOffset` is a distance from the anchor and belongs to the Positioner,
 * not the Popup, so it is taken here and passed inward. The Arrow is optional
 * and sits inside the Popup, where Base UI rotates it to whichever side the
 * popup actually landed on.
 *
 * It is not modal. The page underneath stays live, and focus is not trapped -
 * which is right for a panel beside a control and wrong for a decision.
 */

export const popoverPopupVariants = cva(
  [
    'rounded-lg border border-line bg-raise p-4 text-text shadow-float',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.97] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.97] data-[starting-style]:opacity-0',
    // Grow out of the edge it is anchored to rather than out of its own
    // middle, so the motion points back at the trigger.
    'origin-[var(--transform-origin)]',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(16rem,calc(100vw-2rem))]',
        md: 'w-[min(20rem,calc(100vw-2rem))]',
        lg: 'w-[min(28rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `PopoverTrigger`. */
export const Popover = Base.Root

/** What opens it, and what the popup is measured against. */
export const PopoverTrigger = Base.Trigger

/** What closes it, for a button inside the panel. */
export const PopoverClose = Base.Close

export interface PopoverPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof popoverPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit,
   * and defaults it to the bottom. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. Base UI centres it by default. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Whether to draw the arrow pointing back at the trigger. */
  arrow?: boolean
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
}

/** The panel. Portalled and positioned, so it is not clipped by an ancestor
 * with `overflow: hidden` - which is where most anchored popups go to die.
 *
 * `side` and `align` are passed straight through rather than defaulted here:
 * Base UI's own defaults are already bottom and centre, and writing them out
 * again would be one more place for the two to disagree. */
export function PopoverPopup({
  size,
  side,
  align,
  sideOffset = 8,
  arrow = true,
  container,
  className,
  children,
  ...props
}: PopoverPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-floating)]"
      >
        <Base.Popup className={cn(popoverPopupVariants({ size }), className)} {...props}>
          {arrow ? <PopoverArrow /> : null}
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The notch pointing back at the trigger. Base UI rotates it to whatever side
 * the popup landed on, which is why the rotation is keyed off `data-side`
 * rather than off the `side` that was asked for. */
export function PopoverArrow({ className, ...props }: Base.Arrow.Props) {
  return (
    <Base.Arrow
      className={cn(
        'h-2 w-2 rotate-45 border border-line bg-raise',
        'data-[side=bottom]:-top-1 data-[side=bottom]:border-r-0 data-[side=bottom]:border-b-0',
        'data-[side=top]:-bottom-1 data-[side=top]:border-t-0 data-[side=top]:border-l-0',
        'data-[side=left]:-right-1 data-[side=left]:border-b-0 data-[side=left]:border-l-0',
        'data-[side=right]:-left-1 data-[side=right]:border-r-0 data-[side=right]:border-t-0',
        className,
      )}
      {...props}
    />
  )
}

/** The heading. Base UI points the popup's `aria-labelledby` at it, so a
 * popover with one is named for a screen reader without anyone arranging it. */
export function PopoverTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-sm font-semibold', className)} {...props} />
}

/** The line under the heading, and the popup's `aria-describedby`. */
export function PopoverDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-1 text-sm text-dim', className)} {...props} />
}

import { PreviewCard as Base } from '@base-ui/react/preview-card'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * PreviewCard.
 *
 * The card that appears when a link is hovered: who the author is, what the
 * issue says, what is behind the URL. Rich content - an avatar, a few lines,
 * a figure or two - rather than the phrase a Tooltip holds.
 *
 * Positioned the same way a Popover is, through a Positioner between the
 * Portal and the Popup, so it flips and shifts to stay on screen. What differs
 * is how it opens: hovering the trigger, after a delay, and it stays open
 * while the pointer travels from the link to the card. That last part is the
 * whole trick - a card that vanishes when the pointer leaves the link cannot
 * be read, let alone clicked into.
 *
 * Same warning as Tooltip, and for the same reason. Base UI treats this as a
 * visual enhancement for sighted mouse and keyboard users: it is not reachable
 * on a touch screen and not announced by a screen reader. So NOTHING IN THE
 * CARD MAY BE THE ONLY PLACE IT APPEARS. Everything in it has to also be on
 * the page the link goes to - the card is a shortcut for people who can see
 * it, never the delivery mechanism for the information itself.
 *
 * If the content has to be reachable by everyone, this is the wrong component;
 * a Popover opened from a real button is the right one.
 */

export const previewCardPopupVariants = cva(
  [
    'rounded-lg border border-line bg-raise p-4 text-sm text-text shadow-float',
    'focus-visible:outline-none',
    // The enter and the leave. `duration-*` reads the token directly because
    // Tailwind's own utility takes a literal number.
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[closed]:scale-[0.97] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.97] data-[starting-style]:opacity-0',
    // Grow out of the edge it is anchored to rather than out of its own
    // middle, so the motion points back at the link.
    'origin-[var(--transform-origin)]',
  ],
  {
    variants: {
      size: {
        sm: 'w-[min(18rem,calc(100vw-2rem))]',
        md: 'w-[min(22rem,calc(100vw-2rem))]',
        lg: 'w-[min(28rem,calc(100vw-2rem))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** The root. Controlled with `open` and `onOpenChange`, or left to manage
 * itself around a `PreviewCardTrigger`. */
export const PreviewCard = Base.Root

/** The link the card previews. Usually rendered as the anchor itself, so it
 * stays a real link: it navigates, it opens in a new tab, and a screen reader
 * announces it as one - which is what the card cannot do. Takes `delay`. */
export const PreviewCardTrigger = Base.Trigger

export interface PreviewCardPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof previewCardPopupVariants> {
  /** Preferred side of the link. Base UI flips it when it does not fit, and
   * defaults it to the bottom. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. Base UI centres it by default. */
  align?: Base.Positioner.Props['align']
  /** Distance from the link, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Whether to draw the arrow pointing back at the link. */
  arrow?: boolean
  /** Where to portal to. Defaults to the document body, which is what keeps
   * the popup from being clipped by an ancestor. Pass an element to put it
   * somewhere else - inside an overlay that is already open, or into a
   * container being screenshotted. */
  container?: Base.Portal.Props['container']
}

/** The card. Portalled and positioned, so it is not clipped by the paragraph
 * the link sits in. */
export function PreviewCardPopup({
  size,
  side,
  align,
  sideOffset = 8,
  arrow = true,
  container,
  className,
  children,
  ...props
}: PreviewCardPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        className="[z-index:var(--z-floating)]"
      >
        <Base.Popup className={cn(previewCardPopupVariants({ size }), className)} {...props}>
          {arrow ? <PreviewCardArrow /> : null}
          {children}
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** The notch pointing back at the link. Base UI rotates it to whatever side
 * the card landed on, which is why the placement is keyed off `data-side`
 * rather than off the `side` that was asked for. */
export function PreviewCardArrow({ className, ...props }: Base.Arrow.Props) {
  return (
    <Base.Arrow
      className={cn(
        'h-2 w-2 rotate-45 border border-line bg-raise',
        'data-[side=bottom]:-top-1 data-[side=bottom]:border-r-0 data-[side=bottom]:border-b-0',
        'data-[side=top]:-bottom-1 data-[side=top]:border-t-0 data-[side=top]:border-l-0',
        'data-[side=left]:-right-1 data-[side=left]:border-b-0 data-[side=left]:border-l-0',
        'data-[side=right]:-left-1 data-[side=right]:border-r-0 data-[side=right]:border-t-0',
        className,
      )}
      {...props}
    />
  )
}

import { Progress as Base } from '@base-ui/react/progress'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * How far along something is.
 *
 * The distinction the component is built on, and the one products collapse:
 *
 *   **determinate** - the fraction is known. The bar fills to it, and a reader
 *   can tell how long is left.
 *
 *   **indeterminate** - something is happening and nobody knows how much is
 *   left. The bar says exactly that, by moving without filling.
 *
 * Collapsing them means picking a number that is not true - a bar that creeps
 * to 90% and waits there is the commonest version, and it is a lie the reader
 * learns to distrust, after which no progress bar in the product means
 * anything. `value={undefined}` is the honest answer, and it is the default.
 *
 * Base UI carries the role, the announcement and the value clamping. What is
 * here is the clothes, and the rule about which of the two states is drawn.
 *
 * Not a Spinner. A spinner says "working" in a corner; this says "working, and
 * here is the shape of it" across a width. Where the shape of what is coming
 * is known, a Skeleton says more than either.
 */

export const progressVariants = cva('w-full overflow-hidden rounded-full bg-soft', {
  variants: {
    size: {
      sm: 'h-1',
      md: 'h-2',
    },
    tone: {
      accent: '',
      good: '',
      warn: '',
      bad: '',
    },
  },
  defaultVariants: { size: 'md', tone: 'accent' },
})

const fillVariants = cva('h-full rounded-full transition-[width] duration-base', {
  variants: {
    tone: {
      accent: 'bg-accent',
      good: 'bg-good',
      warn: 'bg-warn',
      bad: 'bg-bad',
    },
  },
  defaultVariants: { tone: 'accent' },
})

/* The stripes take their colour from `currentColor`, so the tone arrives as a
 * text colour rather than a background - the same four names, said the other
 * way round. */
const stripeVariants = cva('h-full w-full rounded-full opacity-40', {
  variants: {
    tone: {
      accent: 'text-accent',
      good: 'text-good',
      warn: 'text-warn',
      bad: 'text-bad',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export interface ProgressProps
  extends Omit<Base.Root.Props, 'className' | 'value'>,
    VariantProps<typeof progressVariants> {
  /** The fraction done, 0 to `max`. Leave it out when it is not known - that
   * is not a missing value but a different, honest state. */
  value?: number | null
  max?: number
  /** What is progressing, for a screen reader. Required: a bar with no name is
   * announced as a percentage of nothing, and the word belongs to the product. */
  label: string
  className?: string
  /** A visible label beside the bar, when there is room. */
  children?: React.ReactNode
}

export function Progress({
  value,
  max = 100,
  size,
  tone,
  label,
  className,
  children,
  ...props
}: ProgressProps) {
  const indeterminate = value === undefined || value === null

  return (
    <Base.Root
      value={indeterminate ? null : value}
      max={max}
      aria-label={label}
      className={cn('flex w-full flex-col gap-1.5', className)}
      {...props}
    >
      {children !== undefined && (
        <div className="flex items-baseline justify-between text-xs text-dim">
          {children}
          {/* The number only where there is one. Showing "0%" for an unknown
            * amount is the same lie as a bar that creeps to 90%. */}
          {!indeterminate && (
            <span className="tabular-nums">{Math.round((value / max) * 100)}%</span>
          )}
        </div>
      )}

      <Base.Track className={cn(progressVariants({ size, tone }))}>
        {indeterminate ? (
          /* Stripes across the whole track, not a filled bar.
           *
           * A full-width fill was the first version and it was wrong in the
           * one way that matters: measured on the stand, it drew 384px of a
           * 384px track - a reader glancing at it sees "done", which is the
           * opposite of what the state means. Pulsing did not rescue it, and
           * under `prefers-reduced-motion` the pulse stops and a solid,
           * complete-looking bar is all that remains.
           *
           * Stripes cannot be read as a fraction at all: there is no edge to
           * take for a boundary. They are drawn with a gradient rather than a
           * `@keyframes` of their own, because a name in the theme is a
           * contract the line carries forever - and this needs no animation to
           * say what it says. */
          <div
            className={cn(stripeVariants({ tone }))}
            style={{
              backgroundImage:
                'repeating-linear-gradient(45deg, currentColor 0 6px, transparent 6px 12px)',
            }}
          />
        ) : (
          <Base.Indicator className={cn(fillVariants({ tone }))} />
        )}
      </Base.Track>
    </Base.Root>
  )
}

import type { ReactNode } from 'react'
import { EmptyState } from './empty-state'
import { SkeletonList } from './skeleton'

/*
 * The three screens between asking for data and showing it.
 *
 * Every list in every product writes the same ladder - loading, then failed,
 * then nothing found, then the content - and writes it slightly differently
 * each time. What differs is never deliberate: one screen forgets the empty
 * case, another shows a spinner where the shape was known, a third prints the
 * raw error object. This is that ladder, once.
 *
 * **It takes values, not a query.** `useQuery` from TanStack Query hands back
 * `isPending` and `error`, and those are ordinary values - so this component
 * asks for them rather than for the query result, and works the same with SWR,
 * with a reducer, or with two `useState` calls. Taking the result object would
 * put a library in the registry and therefore in every product that installs
 * this primitive, to save one line at the call site:
 *
 *     const works = useQuery({ queryKey, queryFn })
 *     <QueryState pending={works.isPending} error={works.error} empty={!works.data?.length} …>
 *
 * **The order of the cases is the component**, and it is the part that goes
 * wrong by hand: pending first, because a refetch that already has data should
 * not blank the screen; then error, because an error with stale data is still
 * an error; then empty, which is only knowable once something arrived.
 *
 * What it deliberately does not do is fetch, retry or cache. Those belong to
 * whatever owns the data - and a component that guessed at them would be
 * wrong for the product that owns them differently.
 */

export interface QueryStateProps {
  /** Nothing has arrived yet. */
  pending?: boolean
  /** It failed. Anything with a `message`, which is what every error library
   * agrees on - or a string, for a product that carries its own. */
  error?: { message: string } | string | null
  /** Something arrived, and it was nothing. Computed by the caller, because
   * only the caller knows whether empty means `[]`, `null` or a count of
   * zero. */
  empty?: boolean
  /** What stands in while pending. A shape, ideally - the default is a list,
   * because most screens are waiting for one, but a screen waiting for a card
   * should say so. */
  skeleton?: ReactNode
  /** What is shown when nothing came back. */
  emptyState?: ReactNode
  /** What is shown when it failed. Given the message, so a product can put it
   * where it likes - or ignore it. */
  errorState?: (message: string) => ReactNode
  /** The words on the default error screen. Required only in the sense that
   * the default screen needs them; pass `errorState` instead and they are
   * never read. */
  errorLabels?: { title: string; body?: string }
  children: ReactNode
}

export function QueryState({
  pending = false,
  error = null,
  empty = false,
  skeleton,
  emptyState,
  errorState,
  errorLabels,
  children,
}: QueryStateProps) {
  /* `aria-busy` on the wrapper, in every state.
   *
   * This is what tells a screen reader that the region is working, and it is
   * why the Skeletons themselves are `aria-hidden`: the fact belongs to the
   * region, said once, rather than to a dozen empty boxes announced as
   * content. */
  const wrap = (content: ReactNode) => <div aria-busy={pending || undefined}>{content}</div>

  // Pending first: a refetch that still holds data should not blank the screen
  // it is refreshing, and the caller decides that by passing `pending` only
  // when there is nothing to show.
  if (pending) return wrap(skeleton ?? <SkeletonList />)

  if (error) {
    const message = typeof error === 'string' ? error : error.message
    if (errorState) return wrap(errorState(message))
    return wrap(
      <EmptyState
        variant="error"
        title={errorLabels?.title ?? message}
        // The message is shown as the body when there is a title above it, and
        // as the title when there is not - so it is never lost, and never
        // printed twice.
        body={errorLabels?.title ? (errorLabels.body ?? message) : errorLabels?.body}
      />,
    )
  }

  // Empty last of the three: it is the only one that cannot be known until
  // something has arrived.
  if (empty && emptyState) return wrap(emptyState)

  return wrap(children)
}

import type { ReactNode } from 'react'
import { Radio as Base } from '@base-ui/react/radio'
import { RadioGroup as BaseGroup } from '@base-ui/react/radio-group'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * RadioGroup - one of a few, all of them visible.
 *
 * The rule for reaching for this rather than a Select is whether the options
 * are worth the space: a handful of short choices read faster laid out than
 * hidden behind a trigger, and each one becomes a target rather than a step.
 * Past about five, or when the labels are long, a Select is the honest
 * choice - this is not a Select with more pixels.
 *
 * The group is the control, not the button. That is what the arrow keys
 * follow, what a screen reader announces as one thing with a position in it,
 * and why `Radio` on its own is not exported: a radio outside a group is a
 * checkbox that cannot be unchecked.
 *
 * The dot is drawn rather than native, for the same reason as the tick in
 * Checkbox: a real `<input type=radio>` cannot be styled without
 * `appearance: none`, and after that the dot has to be drawn anyway.
 */

export interface RadioGroupProps {
  children: ReactNode
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  /** Lay the options out in a row. For two or three short ones; a column is
   * the default because it stays readable as labels grow. */
  orientation?: VariantProps<typeof radioGroupVariants>['orientation']
  'aria-label'?: string
  className?: string
}

/* The layout lives in `cva` rather than in a destructured default, which is
 * how every other primitive here states one. It also keeps the word out of
 * the component's signature: a string default in a props list is how a
 * primitive ends up shipping English, and the gate that watches for that
 * cannot tell an enum value from a label. */
export const radioGroupVariants = cva('flex', {
  variants: {
    orientation: {
      vertical: 'flex-col gap-2',
      horizontal: 'flex-row flex-wrap gap-4',
    },
  },
  defaultVariants: { orientation: 'vertical' },
})

export function RadioGroup({ children, orientation, className, ...props }: RadioGroupProps) {
  return (
    <BaseGroup className={cn(radioGroupVariants({ orientation }), className)} {...props}>
      {children}
    </BaseGroup>
  )
}

export interface RadioProps {
  value: string
  /** The words next to the dot. */
  children?: ReactNode
  disabled?: boolean
  className?: string
}

export function Radio({ value, children, disabled, className }: RadioProps) {
  const dot = (
    <Base.Root
      value={value}
      disabled={disabled}
      className={cn(
        'flex size-4 shrink-0 items-center justify-center rounded-full border border-line-2 bg-transparent',
        'transition-colors',
        'hover:border-accent',
        'data-[checked]:border-accent',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        'disabled:cursor-not-allowed disabled:opacity-50',
        children === undefined && className,
      )}
    >
      <Base.Indicator className="size-2 rounded-full bg-accent" render={<span />} />
    </Base.Root>
  )

  if (children === undefined) return dot

  return (
    <label
      className={cn(
        'flex cursor-pointer items-center gap-2 text-sm text-text',
        'has-[:disabled]:cursor-not-allowed has-[:disabled]:opacity-50',
        className,
      )}
    >
      {dot}
      {children}
    </label>
  )
}

import { useId, type KeyboardEvent } from 'react'
import { cn } from 'dowel-ui'

/*
 * RatingScale - a judgement on a short scale, and the absence of one.
 *
 * Generalised from kilna, where it is how a work is scored on each of its
 * axes. The shape is a row of marks rather than stars: stars carry a meaning
 * of their own - a review, a public verdict - and this is as often "how hard
 * was this" or "how finished is it" as it is "how good".
 *
 * The part worth keeping from the donor, and the reason this is not a Slider
 * with a small range: **not judged yet is a state, not a zero.** "I have not
 * scored this" and "I scored it nothing" are different facts, and a control
 * that collapses them makes the difference unrecoverable the moment it is
 * saved. So `value` is `number | undefined`, clicking the current mark clears
 * it, and Backspace does the same from the keyboard.
 *
 * One tab stop, arrows within it - the arrangement a radio group has. The
 * marks are not buttons: the container is the control, and a `<button>` inside
 * an element with `role="slider"` is a nested interactive control - axe calls
 * it out, and it is right, because assistive technology is not promised to
 * announce or reach the inner one. The donor had them as `aria-hidden`
 * buttons, which hides them from a reader without making them stop being
 * controls.
 *
 * So a mark is a plain element that happens to accept a click. Everything
 * that makes the control usable - the tab stop, the keyboard, the announced
 * value - belongs to the container, and the pointer is served by the marks.
 */

export interface RatingScaleProps {
  /** How many marks. */
  scale: number
  /** The score, or `undefined` for not judged yet. */
  value: number | undefined
  onValueChange: (value: number | undefined) => void
  /** What is being judged. Required: a bare row of marks names nothing, and
   * this is the only thing a screen reader has to go on. */
  label: string
  /** What a screen reader hears in place of a number when nothing is chosen.
   * Required rather than defaulted, because a default here would be English
   * shipped inside a primitive. */
  emptyLabel: string
  disabled?: boolean
  className?: string
}

export function RatingScale({
  scale,
  value,
  onValueChange,
  label,
  emptyLabel,
  disabled = false,
  className,
}: RatingScaleProps) {
  const id = useId()
  const marks = Math.max(1, Math.round(scale))

  const clamp = (next: number) => Math.min(Math.max(next, 0), marks)

  const step = (delta: number) => {
    if (disabled) return
    // From nothing, a step forward lands on the first mark and a step back on
    // the last - so either arrow starts scoring rather than doing nothing.
    const next = value === undefined ? (delta > 0 ? 1 : marks) : value + delta
    onValueChange(clamp(next))
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (disabled) return
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        event.preventDefault()
        step(1)
        break
      case 'ArrowLeft':
      case 'ArrowDown':
        event.preventDefault()
        step(-1)
        break
      case 'Home':
        event.preventDefault()
        onValueChange(0)
        break
      case 'End':
        event.preventDefault()
        onValueChange(marks)
        break
      case 'Backspace':
      case 'Delete':
        // The keyboard's way back to not judged. Without it the state is
        // reachable only by clicking the mark that is already chosen.
        event.preventDefault()
        onValueChange(undefined)
        break
      default:
        break
    }
  }

  return (
    <div
      id={id}
      role="slider"
      tabIndex={disabled ? -1 : 0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={marks}
      aria-valuenow={value}
      aria-valuetext={value === undefined ? emptyLabel : String(value)}
      aria-disabled={disabled || undefined}
      onKeyDown={onKeyDown}
      className={cn(
        'flex gap-[3px] rounded-md',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        disabled && 'cursor-not-allowed opacity-50',
        className,
      )}
    >
      {Array.from({ length: marks }, (_, index) => {
        const mark = index + 1
        const filled = value !== undefined && mark <= value
        return (
          <span
            key={mark}
            // Deliberately not a button. The container is the control; a
            // nested one would be a second interactive element inside a
            // `slider`, which assistive technology is not promised to handle.
            aria-hidden
            // Clicking the mark already chosen clears the score. That is the
            // pointer's way back to not judged, and it is why a rating is not
            // a five-option radio group.
            onClick={() => {
              if (disabled) return
              onValueChange(value === mark ? undefined : mark)
            }}
            className={cn(
              'h-[22px] flex-1 rounded-sm transition-colors',
              disabled ? 'cursor-not-allowed' : 'cursor-pointer',
              filled ? 'bg-accent' : 'bg-soft',
              !disabled && (filled ? 'hover:bg-accent-2' : 'hover:bg-line-2'),
            )}
          />
        )
      })}
    </div>
  )
}

import { useState, type TimeHTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * "3 minutes ago", in the reader's language, over a date they can still read.
 *
 * The rule the component is built on: **relative time is a convenience, never
 * the only copy of the fact.** "Last week" is quicker to read than a date and
 * useless the moment the reader needs to say when something actually happened
 * - and they cannot get it back, because the page has thrown it away. So the
 * element is a `<time dateTime=…>` with the exact moment in its `title`: the
 * machine-readable value stays, hovering shows the real date, and copying the
 * text still yields something a person can act on.
 *
 * `Intl.RelativeTimeFormat` writes the phrase, which is the whole reason there
 * is no date library here. "yesterday", "3 недели назад", "in 2 months" - the
 * plural rules and the special words for the nearest units are the part a
 * hand-written version gets wrong first, and it gets it wrong only in the
 * languages its author does not read.
 *
 * What `Intl` does not decide is which unit to use: it is told "3" and
 * "weeks". Choosing between them is `relativeParts` below, and it is the one
 * piece of arithmetic here.
 *
 * Deliberately not self-updating. A component that re-renders every second to
 * keep "2 minutes ago" honest costs a timer per instance - a table of fifty
 * rows is fifty timers - to correct a number nobody is watching change. A
 * product that needs it re-renders the list on its own schedule; the `now`
 * prop is there so it can, and so tests are not written against the clock.
 */

/** The thresholds, largest unit first: how many seconds it takes to earn one,
 * and the unit `Intl` should be handed.
 *
 * A month is 30 days and a year is 365. Both are approximations, and they are
 * the right ones: this is a phrase saying roughly how long ago, and a reader
 * who needs the exact interval is reading the date in the `title` instead. */
const UNITS: [seconds: number, unit: Intl.RelativeTimeFormatUnit][] = [
  [60 * 60 * 24 * 365, 'year'],
  [60 * 60 * 24 * 30, 'month'],
  [60 * 60 * 24 * 7, 'week'],
  [60 * 60 * 24, 'day'],
  [60 * 60, 'hour'],
  [60, 'minute'],
  [1, 'second'],
]

/** How long ago, as a count and a unit: what `Intl.RelativeTimeFormat` needs.
 *
 * The sign is the one `Intl` wants - negative for the past - and the count is
 * rounded towards zero. Rounding to nearest is the tempting alternative and
 * says "in 1 hour" 31 minutes before the meeting; truncating never claims more
 * time has passed than has. */
export function relativeParts(
  from: Date | number | string,
  now: Date | number = Date.now(),
): [value: number, unit: Intl.RelativeTimeFormatUnit] {
  const then = new Date(from).getTime()
  const seconds = (then - new Date(now).getTime()) / 1000
  const magnitude = Math.abs(seconds)

  for (const [size, unit] of UNITS) {
    if (magnitude >= size) return [Math.trunc(seconds / size), unit]
  }
  // Under a second either way. Zero seconds rather than the smallest unit,
  // because `Intl` turns that into "now" in every language it knows.
  return [0, 'second']
}

/** The phrase alone, for a `title`, an `aria-label` or a string. */
export function formatRelative(
  from: Date | number | string,
  now: Date | number = Date.now(),
  locale?: string | string[],
  options?: Intl.RelativeTimeFormatOptions,
): string {
  const [value, unit] = relativeParts(from, now)
  return new Intl.RelativeTimeFormat(locale, { numeric: 'auto', ...options }).format(value, unit)
}

export interface RelativeTimeProps extends Omit<TimeHTMLAttributes<HTMLTimeElement>, 'title'> {
  /** The moment being described. A `Date`, epoch milliseconds, or an ISO
   * string - whichever the data already holds. */
  value: Date | number | string
  /** What counts as now. Given rather than read from the clock so a list can
   * re-render on its own schedule, and so a test is not written against the
   * time it runs at. */
  now?: Date | number
  locale?: string | string[]
  /** `'auto'` by default, which is what produces "yesterday" rather than "1
   * day ago" where the language has a word for it. Pass `'always'` for a
   * column where every row should read the same way. */
  numeric?: Intl.RelativeTimeFormatOptions['numeric']
  /** How the exact moment is written in the `title`. The reader's own format
   * by default. */
  titleOptions?: Intl.DateTimeFormatOptions
}

export function RelativeTime({
  value,
  now,
  locale,
  numeric = 'auto',
  titleOptions = { dateStyle: 'medium', timeStyle: 'short' },
  className,
  ...props
}: RelativeTimeProps) {
  /* Read once, at mount, rather than in a default argument.
   *
   * `now = Date.now()` in the parameter list is the obvious spelling and is
   * impure: it is evaluated on every render, so "now" moves whenever the
   * parent happens to re-render and the phrase changes for reasons that have
   * nothing to do with this component. Caught by `react-hooks/purity`, and
   * worth keeping caught - a component that deliberately does not update
   * itself must not update itself by accident either.
   *
   * With `now` given, the state is initialised and never read, which is what a
   * product paging a list wants: every row is measured from the same moment. */
  const [mountedAt] = useState(() => Date.now())
  const moment = new Date(value)
  const invalid = Number.isNaN(moment.getTime())

  if (invalid) {
    // A date that is not a date renders as nothing rather than as "Invalid
    // Date", which is a string no reader can do anything with and which looks
    // like a value. The `<time>` element with no `dateTime` says the same to a
    // machine: there is no moment here.
    return <time className={className} {...props} />
  }

  return (
    <time
      dateTime={moment.toISOString()}
      // The fact itself, kept. The phrase above it is the convenience.
      title={new Intl.DateTimeFormat(locale, titleOptions).format(moment)}
      className={cn('whitespace-nowrap', className)}
      {...props}
    >
      {formatRelative(moment, now ?? mountedAt, locale, { numeric })}
    </time>
  )
}

import { useEffect, useState, type ReactNode } from 'react'
import { cn } from 'dowel-ui'
import { spinnerVariants } from './spinner'

/*
 * SaveState.
 *
 * The quiet line beside a field that saves itself: "saving…", then a tick that
 * fades. It exists because a form without a Save button has to say what it did
 * anyway - otherwise the reader is left guessing whether their edit survived,
 * and the usual answer to that guess is to press Ctrl+S at a page that has no
 * such thing.
 *
 * Taken from kilna, where it has been in production, with the two things a
 * primitive may not keep: its words (they came from the product's i18n, and a
 * component with a string of its own cannot be translated) and its icons.
 *
 * The rules it already got right, and which are the whole reason not to write
 * this fresh:
 *
 * - **The tick decays.** One that never leaves stops meaning "just now" and
 *   becomes furniture.
 * - **Only a real save earns one.** Mounting next to an idle mutation must not
 *   flash a tick for a save that happened before the reader arrived.
 * - **A failure is not a save.** It is announced elsewhere - a toast, an error
 *   on the field - and saying "saved" underneath that is worse than silence.
 * - **The width is held.** The line sits next to a field; if it grew and shrank
 *   with its own text, the layout would twitch on every keystroke's worth of
 *   saving.
 */

/** What the indicator is showing. `idle` is invisible but still occupies its
 * width. */
export type SaveStatus = 'idle' | 'saving' | 'saved'

/**
 * Turns "is a mutation in flight" into the three states this shows.
 *
 * Only the tick is state: `saving` is read straight off the mutation, and the
 * tick decays on its own.
 *
 * @param isPending whether the save is in flight right now
 * @param isError whether the save that just finished failed
 * @param linger how long the tick stays, in milliseconds
 */
export function useSaveStatus(isPending: boolean, isError = false, linger = 2000): SaveStatus {
  const [justSaved, setJustSaved] = useState(false)
  // The falling edge of a real save is the only thing worth a tick. Without
  // this, mounting beside an idle mutation would show one immediately, for a
  // save the reader was not there for.
  const [wasPending, setWasPending] = useState(isPending)

  // Adjusted during render rather than in an effect: this is state that
  // follows a prop, and `react-hooks/set-state-in-effect` is right to say so.
  if (wasPending !== isPending) {
    setWasPending(isPending)
    setJustSaved(!isPending && !isError)
  }

  useEffect(() => {
    if (!justSaved) return
    const timer = setTimeout(() => setJustSaved(false), linger)
    return () => clearTimeout(timer)
  }, [justSaved, linger])

  if (isPending) return 'saving'
  return justSaved ? 'saved' : 'idle'
}

export interface SaveStateProps {
  /** What to show. Usually from `useSaveStatus`. */
  status: SaveStatus
  /** What to say while saving. The product's word, in the product's language. */
  savingLabel?: ReactNode
  /** What to say once it is saved. */
  savedLabel?: ReactNode
  className?: string
}

/**
 * The indicator itself.
 *
 * `aria-live="polite"` rather than `assertive`: this is a background fact, and
 * interrupting someone mid-sentence to tell them a field saved is precisely
 * the kind of announcement that makes people turn a screen reader's verbosity
 * down.
 */
export function SaveState({ status, savingLabel, savedLabel, className }: SaveStateProps) {
  return (
    <span
      aria-live="polite"
      className={cn(
        'inline-flex min-w-16 items-center gap-1 text-xs text-faint transition-opacity',
        // Kept in the layout when idle, so the row does not reflow around it.
        status === 'idle' && 'opacity-0',
        className,
      )}
    >
      {status === 'saving' && (
        <>
          {/* The ring, not `Spinner`.
            *
            * `Spinner` carries its own `role="status"` and `aria-live`, which
            * is right when it stands alone and wrong inside this: nesting one
            * live region in another gives a screen reader two things to
            * announce for one event. So the visual is reused through the
            * variants and the announcing is left to the span around it. */}
          <span aria-hidden className={cn(spinnerVariants({ size: 'sm', tone: 'current' }), 'border-r-transparent')} />
          {savingLabel}
        </>
      )}
      {status === 'saved' && (
        <>
          {/* The tick is the only place this component names a colour, and it
              names the token for "this went well" rather than a green. */}
          <svg
            viewBox="0 0 16 16"
            aria-hidden="true"
            className="size-3 text-good"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M3 8.5 6.5 12 13 4.5" />
          </svg>
          {savedLabel}
        </>
      )}
    </span>
  )
}

import { useCallback, useRef, type InputHTMLAttributes, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { Kbd } from './kbd'
import { useShortcut } from './shortcut'

/*
 * SearchField.
 *
 * An Input that knows it is a search box, which is three small things the
 * products kept not doing:
 *
 *   - a magnifier, so the field is recognisable before it is read;
 *   - a way to clear it that is not "select all and delete" - and one that a
 *     keyboard can reach, which a decorative `<span>` cannot;
 *   - the shortcut that focuses it, shown in the field rather than learned.
 *
 * `type="search"` is deliberate: it is what tells a browser to offer previous
 * queries, and what makes Escape clear the field on the platforms where that
 * is the convention. The browser's own clear button is hidden, because it is
 * drawn in the operating system's chrome and cannot be made to match - the
 * same reason the line does not use a native `<select>`.
 */

export interface SearchFieldProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'value' | 'onChange'> {
  /** The query. Controlled, because a search box that owns its own text
   * cannot be cleared by the thing that owns the results. */
  value: string
  /** Told the new query on every keystroke. */
  onValueChange: (value: string) => void
  /**
   * What the clear button is called, for a screen reader. No default: a word
   * the component invents is a word the product cannot translate.
   *
   * Leave it out and no clear button is drawn - which is the right shape for a
   * field that filters as you type and is cleared by other means.
   */
  clearLabel?: string
  /**
   * The shortcut that focuses the field, as `['Mod', 'K']`. Shown at the right
   * of the field, and bound: pressing it focuses and selects, from anywhere
   * that is not already a field.
   */
  shortcut?: string[]
  ref?: Ref<HTMLInputElement>
}

export function SearchField({
  value,
  onValueChange,
  clearLabel,
  shortcut,
  className,
  ref,
  ...props
}: SearchFieldProps) {
  const own = useRef<HTMLInputElement>(null)

  const setRefs = useCallback(
    (element: HTMLInputElement | null) => {
      own.current = element
      if (typeof ref === 'function') ref(element)
      else if (ref) ref.current = element
    },
    [ref],
  )

  // Focus and select, so the shortcut replaces a stale query rather than
  // appending to it. Not while someone is typing elsewhere - that is
  // `useShortcut`'s default, and it is the half of this people forget.
  const focusAndSelect = useCallback(() => {
    own.current?.focus()
    own.current?.select()
  }, [])
  useShortcut(shortcut ?? [], focusAndSelect, { enabled: shortcut !== undefined })

  const showClear = clearLabel !== undefined && value !== ''

  return (
    <div className={cn('relative', className)}>
      <MagnifierIcon />

      <input
        ref={setRefs}
        type="search"
        value={value}
        onChange={(event) => onValueChange(event.target.value)}
        className={cn(
          fieldClasses,
          'h-9 pl-8',
          // Room on the right for whatever sits there, and none when nothing
          // does - a field with a permanent gap looks broken.
          showClear && 'pr-8',
          !showClear && shortcut && 'pr-14',
          // The browser's own clear affordance, in the operating system's
          // chrome. Ours is below.
          '[&::-webkit-search-cancel-button]:appearance-none',
        )}
        {...props}
      />

      {showClear && (
        <button
          type="button"
          aria-label={clearLabel}
          onClick={() => {
            onValueChange('')
            own.current?.focus()
          }}
          className={cn(
            'absolute right-1.5 top-1/2 grid size-6 -translate-y-1/2 place-items-center',
            'rounded-sm text-faint transition-colors hover:bg-soft hover:text-text',
            'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
          )}
        >
          <CrossIcon />
        </button>
      )}

      {!showClear && shortcut && (
        // Decorative: the shortcut works whether or not it is read out, and a
        // screen reader announcing "Control K" inside a search box is noise.
        <Kbd
          keys={shortcut}
          aria-hidden
          className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2"
        />
      )}
    </div>
  )
}

function MagnifierIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      aria-hidden
      className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-faint"
    >
      <circle cx="7" cy="7" r="4.5" />
      <path d="M10.5 10.5L14 14" strokeLinecap="round" />
    </svg>
  )
}

function CrossIcon() {
  return (
    <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
      <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
    </svg>
  )
}

import { Select as Base } from '@base-ui/react/select'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * Select.
 *
 * The component the oldest rule in the line is about. A native `<select>`
 * cannot be dressed: the browser draws its popup itself, in the operating
 * system's chrome, and no CSS reaches inside. One native dropdown on a screen
 * of the product's own controls reads as a foreign object, and on Windows it
 * reads as a foreign object from 1998.
 *
 * So this renders `<button role="combobox">` and a portalled list of
 * `role="option"` - zero native elements, which is asserted in the test,
 * because it is the entire reason the component exists.
 *
 * What that costs is everything the browser was doing for free: the keyboard,
 * type-ahead, the announcement of the selected value, the scroll into view,
 * and on a phone the whole native picker. Base UI does all of it, which is
 * the only reason this trade is worth making - a hand-rolled dropdown is how
 * a product ships a control that a screen reader cannot see.
 *
 * The trigger wears Input's `fieldClasses`, imported rather than copied. A
 * select and a text field sit next to each other in every form there has ever
 * been, and two class lists that started the same drift within a release.
 *
 * `multiple` is a prop on the Root: it changes what `value` means - an array
 * rather than a single value - so it belongs where the value lives and not on
 * the trigger.
 */

export const selectTriggerVariants = cva([fieldClasses, 'flex items-center justify-between gap-2'], {
  variants: {
    size: {
      sm: 'h-8 text-xs',
      md: 'h-9',
      lg: 'h-10 text-base',
    },
  },
  defaultVariants: { size: 'md' },
})

export const selectPopupVariants = cva(
  [
    'max-h-[min(24rem,var(--available-height))] overflow-y-auto',
    'rounded-md border border-line bg-raise p-1 text-text shadow-float',
    'focus-visible:outline-none',
    '[transition:opacity_var(--duration-quick)_var(--ease-out),transform_var(--duration-quick)_var(--ease-out)]',
    'data-[closed]:scale-[0.98] data-[closed]:opacity-0',
    'data-[starting-style]:scale-[0.98] data-[starting-style]:opacity-0',
  ],
  {
    variants: {
      size: {
        // The popup matches the trigger's width by default, which is what a
        // dropdown should do; the sizes are a floor for a narrow one.
        sm: 'min-w-[max(8rem,var(--anchor-width))]',
        md: 'min-w-[max(10rem,var(--anchor-width))]',
        lg: 'min-w-[max(14rem,var(--anchor-width))]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/** One option. */
export const selectItemVariants = cva([
  'relative flex cursor-pointer select-none items-center gap-2 rounded-sm py-1.5 pl-2 pr-7 text-sm',
  'outline-none transition-colors',
  // Base UI marks the item under the pointer or the keyboard the same way,
  // so one rule covers both and they cannot disagree.
  'data-[highlighted]:bg-soft data-[highlighted]:text-text',
  // What is already chosen has to be visible in the list, and colour alone
  // will not do it: `text-text` on an item that is already `text-text` says
  // nothing. The tick below is the state; this is the emphasis that goes with
  // it, so the row reads as chosen at a glance and not only under the eye.
  'data-[selected]:font-medium data-[selected]:text-accent',
  'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
  '[&_svg]:size-3.5 [&_svg]:shrink-0',
])

/** The root. `multiple` turns `value` into an array; otherwise controlled with
 * `value` and `onValueChange`, or left to manage itself. */
export const Select = Base.Root

/** What the trigger shows: the selected item's label, and the `placeholder`
 * the product gives it until there is one.
 *
 * Two traps, both Base UI's and both quiet. Its `children` is a *function* of
 * the value, not a node - passing a node pins the trigger to that node
 * forever and the selection never appears, so the placeholder goes in
 * `placeholder`. And what it shows is the raw value, `plum` rather than
 * `Plum`, unless the root is given an `items` map to look the label up in.
 *
 * It truncates, and that matters most for `multiple`: nine chosen fruits are
 * one long string, and without this the trigger either grows into a paragraph
 * or spills its text past its own border. One line, an ellipsis, and the full
 * set is still in the list where the ticks are. */
export function SelectValue({ className, ...props }: Base.Value.Props) {
  return <Base.Value className={cn('min-w-0 flex-1 truncate text-left', className)} {...props} />
}

/** The chevron, or whatever the product puts there. Marked decorative by Base
 * UI, since the button is already named by its value. */
export const SelectIcon = Base.Icon

/** A labelled group of options. */
export const SelectGroup = Base.Group

/** The text of an option, which is what the trigger echoes when it is chosen. */
export const SelectItemText = Base.ItemText

/** The tick, drawn only on the chosen option. */
export const SelectItemIndicator = Base.ItemIndicator

export interface SelectTriggerProps
  extends Base.Trigger.Props,
    VariantProps<typeof selectTriggerVariants> {}

/** The control. A `<button role="combobox">` - never a `<select>`. */
export function SelectTrigger({ size, className, ...props }: SelectTriggerProps) {
  return <Base.Trigger className={cn(selectTriggerVariants({ size }), className)} {...props} />
}

export interface SelectPopupProps
  extends Base.Popup.Props,
    VariantProps<typeof selectPopupVariants> {
  /** Preferred side of the trigger. Base UI flips it when it does not fit. */
  side?: Base.Positioner.Props['side']
  /** Alignment along that side. */
  align?: Base.Positioner.Props['align']
  /** Distance from the trigger, in pixels. */
  sideOffset?: Base.Positioner.Props['sideOffset']
  /** Where to portal to. Defaults to the document body, which keeps the list
   * from being clipped by a form with `overflow: hidden`. */
  container?: Base.Portal.Props['container']
}

/** The list. Portalled and positioned against the trigger.
 *
 * `alignItemWithTrigger` is off: Base UI's default lifts the popup so the
 * selected option sits over the button, which is the native macOS behaviour
 * and is disorienting in a web form - the list jumps to a different place
 * depending on what is already chosen. */
export function SelectPopup({
  size,
  side,
  align,
  sideOffset = 4,
  container,
  className,
  children,
  ...props
}: SelectPopupProps) {
  return (
    <Base.Portal container={container}>
      <Base.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignItemWithTrigger={false}
        className="[z-index:var(--z-menu)]"
      >
        <Base.Popup className={cn(selectPopupVariants({ size }), className)} {...props}>
          <Base.List>{children}</Base.List>
        </Base.Popup>
      </Base.Positioner>
    </Base.Portal>
  )
}

/** An option, with the tick that says it is the chosen one.
 *
 * The indicator is built in rather than left to the caller. The item already
 * reserves the room for it (`pr-7`), and a dropdown that does not show what is
 * currently selected is the commonest complaint about a styled select: it
 * opens, and the reader has to remember what they picked last time. Passing
 * `indicator={false}` turns it off for a list where the choice is obvious
 * some other way. */
export function SelectItem({
  indicator = true,
  className,
  children,
  ...props
}: Base.Item.Props & { indicator?: boolean }) {
  return (
    <Base.Item className={cn(selectItemVariants(), className)} {...props}>
      {children}
      {indicator && (
        <Base.ItemIndicator className="absolute right-2 flex text-accent">
          <svg viewBox="0 0 16 16" className="size-3.5" aria-hidden>
            <path
              d="M3.5 8.5l3 3 6-6.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </Base.ItemIndicator>
      )}
    </Base.Item>
  )
}

/** The caption above a group. */
export function SelectGroupLabel({ className, ...props }: Base.GroupLabel.Props) {
  return (
    <Base.GroupLabel
      className={cn('px-2 py-1.5 text-2xs uppercase tracking-caption text-faint', className)}
      {...props}
    />
  )
}

/** A line between groups of options. */
export function SelectSeparator({ className, ...props }: Base.Separator.Props) {
  return <Base.Separator className={cn('-mx-1 my-1 h-px bg-line', className)} {...props} />
}

import { useEffect } from 'react'

/*
 * Shortcut.
 *
 * Two things every product writes and half of them get subtly wrong: deciding
 * whether a keystroke is the shortcut, and deciding whether now is a moment to
 * act on it.
 *
 * The second is the one that bites. A shortcut that fires while someone is
 * typing in a field is a bug nobody can describe afterwards - `Mod+K` inside a
 * text editor means "delete to end of line", and a palette that opens on top
 * of it looks like the application misheard. So a keystroke aimed at an input,
 * a textarea or anything `contenteditable` belongs to that thing, always.
 *
 * A shortcut is written the way it is read: `['Mod', 'K']`. `Mod` is command
 * on Apple platforms and control everywhere else, which is the same rule Kbd
 * draws it by, so what is bound and what is shown cannot disagree.
 */

/** Whether the event landed somewhere that owns its own keys. */
export function isTypingTarget(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null
  if (!element) return false
  const tag = element.tagName
  // Coerced: `isContentEditable` is computed from layout, and an engine that
  // does not lay out - jsdom, and any server render - leaves it `undefined`
  // rather than `false`. Truthiness is enough for the branch below, but a
  // function that says it returns a boolean has to.
  return tag === 'INPUT' || tag === 'TEXTAREA' || Boolean(element.isContentEditable)
}

/** Does this event match the shortcut? Exported because a product sometimes
 * has to ask the question inside a handler it already owns. */
export function matchesShortcut(event: KeyboardEvent, shortcut: string[]): boolean {
  const wants = new Set(shortcut.map((key) => key.toLowerCase()))
  const mod = wants.delete('mod')
  const shift = wants.delete('shift')
  const alt = wants.delete('alt')
  const [key] = [...wants]
  if (key === undefined) return false

  // An exact match on every modifier, in both directions: `Mod+K` must not
  // fire on `Mod+Shift+K`, which is usually a different command entirely.
  if (mod !== (event.metaKey || event.ctrlKey)) return false
  if (shift !== event.shiftKey) return false
  if (alt !== event.altKey) return false
  return event.key.toLowerCase() === key
}

export interface UseShortcutOptions {
  /** Bind it at all. For a shortcut that only exists on some screens. */
  enabled?: boolean
  /**
   * Fire even while someone is typing in a field.
   *
   * Off by default, and the default is the point. Turn it on for a shortcut
   * that belongs to the field itself - `Escape` closing the box it is typed
   * in - and never for one that takes the person somewhere else.
   */
  whileTyping?: boolean
}

/**
 * Run something when a shortcut is pressed.
 *
 * The handler is read from a ref, so a caller that writes it inline does not
 * rebind the listener on every render - which is how these end up firing twice.
 */
export function useShortcut(
  shortcut: string[],
  onPress: (event: KeyboardEvent) => void,
  { enabled = true, whileTyping = false }: UseShortcutOptions = {},
): void {
  useEffect(() => {
    if (!enabled) return

    const onKeyDown = (event: KeyboardEvent) => {
      if (!whileTyping && isTypingTarget(event.target)) return
      if (!matchesShortcut(event, shortcut)) return
      event.preventDefault()
      onPress(event)
    }

    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
    // `shortcut` is an array literal at most call sites, so it is joined
    // rather than compared by identity: otherwise every render rebinds.
  }, [shortcut.join('+'), onPress, enabled, whileTyping]) // eslint-disable-line react-hooks/exhaustive-deps
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * A placeholder shaped like the thing that is still loading.
 *
 * The rule the component is built on, and the reason it takes a shape rather
 * than filling the space:
 *
 *   **A skeleton of the wrong shape is worse than no skeleton.**
 *
 * It promises something the content does not keep, and the promise is paid for
 * in a jump: the page settles, the scrollbar appears, and whatever the reader
 * was about to click has moved. Measured rather than assumed - the line's own
 * calendar showed a list of four short lines where a six-row month grid was
 * about to land, and the skeleton was itself the jump it existed to prevent.
 *
 * So the useful thing here is not `<Skeleton />` - that is four lines anyone
 * can write - but the shapes: a list, a card, a grid. They are what a product
 * reaches for at the call site, and what keeps the placeholder honest.
 *
 * A spinner is the right answer when the shape is *not* known. A skeleton
 * claims to know; if it does not, say less rather than more.
 *
 * Everything here is `aria-hidden`. A screen reader is told the region is busy
 * by whatever owns the loading state - `QueryState` does it with `aria-busy` -
 * and announcing a dozen empty boxes as content would be noise on top of a
 * fact the reader already has.
 */

export type SkeletonProps = HTMLAttributes<HTMLDivElement>

/** One block. Size it with `className` - a skeleton is a shape, and the shape
 * belongs to whatever it stands in for. */
export function Skeleton({ className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden
      className={cn('animate-pulse rounded-md bg-soft', className)}
      {...props}
    />
  )
}

export interface SkeletonTextProps extends HTMLAttributes<HTMLDivElement> {
  /** How many lines of text stand here. */
  lines?: number
}

/** A paragraph's worth of lines.
 *
 * The widths vary, and that is the whole point: a stack of equal bars reads as
 * a loading indicator, while ragged ones read as text. The last line is short,
 * because the last line of a paragraph is. */
export function SkeletonText({ lines = 3, className, ...props }: SkeletonTextProps) {
  const widths = ['w-full', 'w-11/12', 'w-4/5', 'w-full', 'w-3/4']
  return (
    <div aria-hidden className={cn('flex flex-col gap-2', className)} {...props}>
      {Array.from({ length: Math.max(1, lines) }, (_, line) => (
        <Skeleton
          key={line}
          className={cn(
            'h-3',
            line === lines - 1 ? 'w-1/2' : widths[line % widths.length],
          )}
        />
      ))}
    </div>
  )
}

export interface SkeletonListProps extends HTMLAttributes<HTMLDivElement> {
  rows?: number
  /** Draw a second, shorter line under each row - for a list whose rows carry
   * a title and something beneath it. */
  secondary?: boolean
}

/** Rows of a list, which is the shape most screens are waiting for. */
export function SkeletonList({
  rows = 5,
  secondary = true,
  className,
  ...props
}: SkeletonListProps) {
  // Three widths in rotation rather than random: a placeholder that differs
  // between renders is a placeholder that flickers when anything re-renders.
  const widths = ['w-2/3', 'w-4/5', 'w-1/2']
  return (
    <div aria-hidden className={cn('flex flex-col gap-1', className)} {...props}>
      {Array.from({ length: Math.max(1, rows) }, (_, row) => (
        <div key={row} className="flex flex-col gap-1.5 px-3 py-2">
          <Skeleton className={cn('h-3.5', widths[row % widths.length])} />
          {secondary && <Skeleton className="h-2.5 w-1/3" />}
        </div>
      ))}
    </div>
  )
}

export interface SkeletonGridProps extends HTMLAttributes<HTMLDivElement> {
  /** How many cells. */
  cells?: number
  /** How many per row. */
  columns?: number
  /** The aspect of one cell, as a Tailwind class - a gallery of covers is not
   * shaped like a grid of tiles. */
  cellClassName?: string
}

/** A grid of cells: a gallery, a board, a month.
 *
 * Given a cell count and a column count rather than a shape of its own,
 * because the grids a product waits for differ in both and agree in neither. */
export function SkeletonGrid({
  cells = 12,
  columns = 4,
  cellClassName = 'aspect-square',
  className,
  ...props
}: SkeletonGridProps) {
  return (
    <div
      aria-hidden
      // The column count is a style rather than a class, because a class would
      // have to be one of a fixed set - and Tailwind cannot generate
      // `grid-cols-${n}` from a value it never sees.
      style={{ gridTemplateColumns: `repeat(${Math.max(1, columns)}, minmax(0, 1fr))` }}
      className={cn('grid gap-2', className)}
      {...props}
    >
      {Array.from({ length: Math.max(1, cells) }, (_, cell) => (
        <Skeleton key={cell} className={cellClassName} />
      ))}
    </div>
  )
}

import type { SVGAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * A line small enough to sit beside the number it belongs to.
 *
 * The shape of a history, not a chart of it: no axes, no gridlines, no ticks.
 * "61 → 74 → 82" reads perfectly at three points and stops working at ten; a
 * line holds both, and the exact figures stay in the list underneath.
 *
 * Three things here are not free choices.
 *
 * **The box is drawn at the size it is shown at.** A `viewBox` wider than the
 * element scales x and y by different factors: the line bends away from the
 * data and the end dot stretches into a wedge. So the size is a variant rather
 * than a `className`, and each variant states the same numbers twice on
 * purpose - once for the geometry, once for the element - from one place. The
 * donor took a `size` object *and* a class, and every call site repeated
 * itself: `size={{ width: 52, height: 16 }} className="h-4 w-[52px]"`.
 *
 * **The scale comes from outside.** `max` is what the axis allows, not what
 * this line happens to reach, so two works can be compared by eye. Normalised
 * to itself, a line that moved 61 → 63 would climb the whole box and read as a
 * transformation.
 *
 * **The line does not judge.** The donor coloured it green when it ended
 * higher and red when it ended lower, which is a claim the component cannot
 * support: for time-to-answer or error rate, down is the good direction. So
 * the line is drawn in the de-emphasis tone and the newest point in the accent
 * - the eye goes to "where it is now", and what that means is said in words
 * next to it, usually by a StatTile's delta. `tone` is there for a caller who
 * genuinely knows the direction's meaning.
 *
 * Not interactive, and that is the form rather than an omission: a sparkline
 * has no room for a hover target that is not the whole of it. A reader who
 * needs the exact figures gets them from the table beside it.
 */

const GEOMETRY = {
  sm: { width: 52, height: 16, dot: 1.75, stroke: 1.25 },
  md: { width: 120, height: 28, dot: 2.5, stroke: 1.5 },
} as const

export type SparklineSize = keyof typeof GEOMETRY

export const sparklineVariants = cva('shrink-0 overflow-visible', {
  variants: {
    size: {
      /* Beside a figure in a row - an axis of a rubric, a cell in a table. */
      sm: 'h-4 w-[52px]',
      /* Beside a total, where the shape is meant to be read rather than
       * glanced at. */
      md: 'h-7 w-[120px]',
    },
  },
  defaultVariants: { size: 'md' },
})

export const sparklineLineVariants = cva('fill-none', {
  variants: {
    tone: {
      /* The default, and the one a caller should almost always leave alone:
       * the line is context for the number beside it. */
      muted: 'stroke-dim',
      /* For a line that IS the subject - one chart on a page, nothing else to
       * defer to. */
      accent: 'stroke-accent',
      /* Only where the caller knows what the direction means. A component
       * cannot: for time-to-answer, down is the good news. */
      good: 'stroke-good',
      bad: 'stroke-bad',
    },
  },
  defaultVariants: { tone: 'muted' },
})

export const sparklineDotVariants = cva('', {
  variants: {
    tone: {
      /* The newest point carries the accent even under the muted line: it is
       * the one the eye is looking for, and one dot of colour is enough to
       * find it without the line making a claim. */
      muted: 'fill-accent',
      accent: 'fill-accent',
      good: 'fill-good',
      bad: 'fill-bad',
    },
  },
  defaultVariants: { tone: 'muted' },
})

/** Breathing room, so the stroke and the end dot are not clipped by the box. */
const PAD = 3

export interface SparklineProps
  extends Omit<SVGAttributes<SVGSVGElement>, 'values'>,
    VariantProps<typeof sparklineLineVariants> {
  /** Oldest first. Fewer than two points is not a line, and draws nothing. */
  values: number[]
  /** The top of the scale, so two lines can be compared by eye. Defaults to
   * the highest value present, which makes the line self-scaled - fine for one
   * line alone, wrong for a column of them. */
  max?: number
  /** What the line says, for a reader who cannot see it. Required: an unlabelled
   * `img` is an unlabelled image, and this one carries information. */
  label: string
  size?: SparklineSize
}

export function Sparkline({ values, max, label, size, tone, className, ...props }: SparklineProps) {
  // One point is a dot with no direction and no point; zero is nothing at all.
  if (values.length < 2) return null

  /* The default lives in `sparklineVariants` like every other variant in the
   * library; this resolves the same word for the geometry, so the numbers and
   * the classes cannot disagree about which size is being drawn. */
  const { width, height, dot, stroke } = GEOMETRY[size ?? 'md']

  /* The ceiling never sits below the data: a value above `max` would otherwise
   * be drawn outside the box. Clamped rather than rejected, because a score
   * that overshoots its stated scale is the caller's problem to notice, not a
   * reason to draw nothing. */
  const top = Math.max(...values, max ?? 0)
  /* A flat line at zero, or a flat line anywhere with no stated scale, would
   * divide by zero. It is drawn along the bottom, which is where it belongs. */
  const span = width - PAD * 2
  const rise = height - PAD * 2

  const points = values.map((value, index) => {
    const x = PAD + (span * index) / (values.length - 1)
    // SVG's y grows downward, so a larger value has to sit higher up.
    const y = top === 0 ? PAD + rise : PAD + rise - (rise * value) / top
    return [x, y] as const
  })

  const path = points
    .map(([x, y], index) => `${index === 0 ? 'M' : 'L'}${x.toFixed(1)} ${y.toFixed(1)}`)
    .join(' ')
  const [lastX, lastY] = points.at(-1)!

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className={cn(sparklineVariants({ size }), className)}
      role="img"
      aria-label={label}
      {...props}
    >
      <path
        d={path}
        strokeWidth={stroke}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={cn(sparklineLineVariants({ tone }))}
      />
      <circle cx={lastX} cy={lastY} r={dot} className={cn(sparklineDotVariants({ tone }))} />
    </svg>
  )
}

import type { HTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Spinner.
 *
 * Something is happening and the answer has not arrived. It carries no text of
 * its own - what is loading is the product's word, not the system's - but it
 * does have to say *something* to a screen reader, or a page that is busy is
 * silently identical to a page that is empty.
 *
 * Under `prefers-reduced-motion` the theme stops the animation. That is not a
 * detail: for some readers a spinning thing is not decoration but a symptom.
 * A stopped spinner still says "busy" through `role`, which is the part that
 * carried the meaning all along.
 */
export const spinnerVariants = cva('inline-block animate-spin rounded-full border-2 border-current', {
  variants: {
    size: {
      sm: 'size-3.5 border-[1.5px]',
      md: 'size-4',
      lg: 'size-6',
    },
    tone: {
      /* Follows the text it sits in. */
      current: 'text-current',
      dim: 'text-dim',
      accent: 'text-accent',
    },
  },
  defaultVariants: { size: 'md', tone: 'current' },
})

export interface SpinnerProps
  extends HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof spinnerVariants> {
  /** What is being waited for, for a screen reader. The product's word. */
  label?: string
}

export function Spinner({ size, tone, label, className, ...props }: SpinnerProps) {
  return (
    <span role="status" aria-live="polite" className={cn('inline-flex items-center gap-2', className)} {...props}>
      <span
        // The gap in the ring is what makes the rotation visible.
        className={cn(spinnerVariants({ size, tone }), 'border-r-transparent')}
