import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * One figure, and what it is a figure of.
 *
 * The smallest thing on a dashboard and the one every product writes itself:
 * a label above, a number below, sometimes a word about which way it moved.
 * It is here because the first consumer had written it twice - once on the
 * personal page, once on the team one - and the copies had already drifted:
 * one had grown a warning tone the other lacked, and the tone classes in it
 * were concatenated without a space, so a figure that was both accented and
 * warning would have emitted `text-accent-2text-warn` and been styled by
 * neither. Nothing had gone wrong on screen yet; the two flags were simply
 * never passed together.
 *
 * A `<dl>` rather than two divs, for the reason KeyValue is one: the pairing
 * is what a screen reader announces. Loose divs read as two unrelated pieces
 * of text and nothing says the number belongs to the label.
 *
 * Numbers are set in the mono face with tabular figures, so a column of tiles
 * lines up and a value that ticks does not shuffle its neighbours sideways.
 * That matters more than it sounds: a live figure redrawn every few seconds in
 * proportional digits makes the whole row twitch.
 *
 * The delta is a second, quieter line rather than a colour on the value. A
 * number that turns red is a number whose colour has to be explained, and the
 * explanation is never on the screen; a delta says "+12% vs last week" and
 * needs nothing. Its tone is stated by the caller rather than inferred from
 * the sign, because down is good for a figure like "time to first response",
 * and a component cannot know which figure it is holding.
 */

export const statTileVariants = cva('min-w-0', {
  variants: {
    size: {
      /* The dashboard default: a row of these under a heading. */
      md: '',
      /* For a tile that leads a page rather than sitting in a row of six. */
      lg: '',
    },
  },
  defaultVariants: { size: 'md' },
})

export const statTileValueVariants = cva('mt-1 font-mono tabular-nums', {
  variants: {
    size: {
      md: 'text-lg',
      lg: 'text-2xl',
    },
    tone: {
      /* The reading tone: what this figure is, not how it is doing. `accent`
       * marks the one figure a panel is really about; `warn` and `bad` are for
       * a figure that is itself a problem - people with no agent reporting,
       * a queue that is backing up. */
      default: 'text-text',
      accent: 'text-accent-2',
      warn: 'text-warn',
      bad: 'text-bad',
    },
  },
  defaultVariants: { size: 'md', tone: 'default' },
})

export const statTileDeltaVariants = cva('mt-1 text-xs', {
  variants: {
    tone: {
      /* Neutral by default, because most movement is just movement. */
      default: 'text-dim',
      good: 'text-good',
      bad: 'text-bad',
    },
  },
  defaultVariants: { tone: 'default' },
})

export interface StatTileProps
  extends Omit<HTMLAttributes<HTMLDListElement>, 'title'>,
    VariantProps<typeof statTileVariants> {
  /** What the figure is. */
  label: ReactNode
  /** The figure. Already formatted - a duration, a count, a percentage: this
   * component decides how a number looks, never what it says. */
  value: ReactNode
  /** How the value itself reads. */
  tone?: NonNullable<VariantProps<typeof statTileValueVariants>['tone']>
  /** Which way it moved, in words the caller chooses: `+12% vs last week`,
   * `3 fewer than yesterday`. Omitted when there is nothing to compare to -
   * an empty line here reads as "unchanged", which is a claim. */
  delta?: ReactNode
  /** Whether that movement is good news. Stated rather than read off the sign,
   * because for a figure like time-to-answer a fall is the good direction. */
  deltaTone?: NonNullable<VariantProps<typeof statTileDeltaVariants>['tone']>
}

export function StatTile({
  label,
  value,
  tone,
  delta,
  deltaTone,
  size,
  className,
  ...props
}: StatTileProps) {
  return (
    <dl className={cn(statTileVariants({ size }), className)} {...props}>
      <dt className="text-xs font-medium text-dim">{label}</dt>
      <dd className={cn(statTileValueVariants({ size, tone }))}>{value}</dd>
      {/* A second `dd` for the same term: the spec allows several, and this is
       * what they are for - one fact with two parts. A `<div>` here would end
       * the description list's pairing, and the delta would be read as loose
       * text next to the number rather than as part of it. */}
      {delta !== undefined && delta !== null && (
        <dd className={cn(statTileDeltaVariants({ tone: deltaTone }))}>{delta}</dd>
      )}
    </dl>
  )
}

/*
 * A row of tiles.
 *
 * Both donors wrote the identical container - `flex flex-wrap items-baseline
 * gap-x-8 gap-y-3` inside a Panel - and both had to get `items-baseline`
 * right, which is the part that is easy to miss: without it, a tile carrying a
 * delta is taller than its neighbours and the whole row's numbers stop sharing
 * a line.
 *
 * Wrapping rather than a grid, because the number of figures is decided at
 * runtime (one donor hides two of its five until there is something to say),
 * and a grid with a fixed column count leaves a hole where a hidden tile was.
 */
export type StatRowProps = HTMLAttributes<HTMLDivElement>

export function StatRow({ className, ...props }: StatRowProps) {
  return <div className={cn('flex flex-wrap items-baseline gap-x-8 gap-y-3', className)} {...props} />
}

/*
 * How a column is ordered, with no React in it.
 *
 * Split out of the Table for the reason `calendar-math` was split out of the
 * Calendar: these are the sums, and the component is the thing that draws
 * them. A product sorting its own rows - on the server, in a worker, before
 * the data ever reaches a component - imports this and nothing else.
 *
 * No table library, deliberately. The obvious choice here is TanStack Table,
 * and it would be the first dependency a product has to install beyond Base
 * UI. What it offers is a model of columns, pages and sorting state; what the
 * line's one real table needed was the rule below, which the model does not
 * have. So the model is the part that is written here, and it is small.
 *
 * The rule, and the reason this file exists at all:
 *
 *   **Absence sorts last, whichever way the column points.**
 *
 * A row with no value in this column is not the smallest - it is unknown, and
 * the two are different facts. Rank absence with the rest and flip the sign,
 * and a descending sort floats every empty row to the top: the reader asks for
 * "highest first" and is handed the rows that have no value at all. This is
 * measured rather than assumed - it is what the first version of the line's
 * catalogue did, and the fix is the shape below, where presence is settled
 * before the direction is applied.
 *
 * It is the same fact `RatingScale` is built on: not judged yet is a state,
 * not a zero. A table that sorts them together loses it on the first click.
 */

/** Which way a column points. */
export type SortDirection = 'asc' | 'desc'

/** A column, and which way it points. `column` is the caller's own key - the
 * id it gave the column, not an index, so reordering columns cannot silently
 * change what is sorted. */
export interface Sort<Column extends string = string> {
  column: Column
  direction: SortDirection
}

/** What can be compared. `null` and `undefined` both mean absent - a product
 * gets whichever its data uses, and having to normalise them before sorting
 * is the kind of step that gets forgotten in one branch of a switch. */
export type SortValue = string | number | boolean | null | undefined

/** Reads the value of a column out of a row.
 *
 * Given rather than inferred: a column id is not always a field name, and a
 * sortable column is often a computed one - a duration that is stored as two
 * timestamps, a name that sorts by surname. */
export type SortAccessor<Row, Column extends string = string> = (
  row: Row,
  column: Column,
) => SortValue

export interface SortOptions<Row> {
  /** The tiebreaker: what decides the order of rows that compare equal.
   *
   * Without one, `Array.prototype.sort` is stable and therefore leaves ties in
   * input order - which sounds fine until the input is re-fetched and arrives
   * in a different order, and a column of ties reshuffles under the reader
   * with no click. Pass the row's id. */
  tiebreak?: (row: Row) => SortValue
  /** The locale text is compared in. Passed to `Intl.Collator`, so `ä` sorts
   * where the reader expects rather than after `z`. */
  locale?: string
}

/** Order the rows. Returns a new array; the input is not touched, because a
 * component that sorts its own prop in place mutates the caller's state. */
export function sortRows<Row, Column extends string = string>(
  rows: readonly Row[],
  sort: Sort<Column>,
  accessor: SortAccessor<Row, Column>,
  options: SortOptions<Row> = {},
): Row[] {
  const sign = sort.direction === 'asc' ? 1 : -1
  // One collator for the whole sort rather than one `localeCompare` per
  // comparison: building it is the expensive half, and a sort of n rows asks
  // for it n log n times.
  const collator = new Intl.Collator(options.locale)

  return [...rows].sort((a, b) => {
    const left = accessor(a, sort.column)
    const right = accessor(b, sort.column)

    // Presence first, and outside the sign. This is the whole point of the
    // file: absence is last in both directions.
    const absent = presence(left, right)
    if (absent !== 0) return absent

    const ranked = compareValues(left, right, collator) * sign
    if (ranked !== 0) return ranked

    if (options.tiebreak) {
      const tied = compareValues(options.tiebreak(a), options.tiebreak(b), collator)
      // Deliberately not multiplied by the sign. The tiebreaker is there to
      // make the order stable, and an order that reverses with the column is
      // not stable - the rows that tie would swap places on every click.
      if (tied !== 0) return tied
    }
    return 0
  })
}

/** Whether a value counts as absent.
 *
 * Both spellings of nothing, and neither `0` nor `''` nor `false`, which are
 * values a row genuinely has.
 *
 * `NaN` counts too, and that is not tidiness. Subtraction with it returns
 * `NaN`, which `sort` reads as "these two are equal" - so a row whose number
 * is not a number takes whatever place the input happened to give it, and the
 * order changes when the data is re-fetched. A number that is not a number is
 * not a small number; it is unknown, which is what this file already has a
 * place for. */
export function isAbsent(value: SortValue): boolean {
  if (value === null || value === undefined) return true
  return typeof value === 'number' && Number.isNaN(value)
}

/** Which of the two lacks a value; absent sorts last, always. */
function presence(left: SortValue, right: SortValue): number {
  const leftHas = !isAbsent(left)
  const rightHas = !isAbsent(right)
  if (leftHas === rightHas) return 0
  return leftHas ? -1 : 1
}

/** Compare two present values of the same column.
 *
 * Numbers by subtraction, text by collator, and booleans as false-then-true.
 * A column whose values are of mixed type compares as text: that is a data
 * problem the table cannot fix, and ordering by `String` at least gives the
 * same answer twice. */
function compareValues(left: SortValue, right: SortValue, collator: Intl.Collator): number {
  if (isAbsent(left) || isAbsent(right)) return presence(left, right)

  // NaN never reaches here: `isAbsent` counts it as absent, so `presence`
  // settles it above, outside the sign.
  if (typeof left === 'number' && typeof right === 'number') return left - right
  if (typeof left === 'boolean' && typeof right === 'boolean') {
    return Number(left) - Number(right)
  }
  return collator.compare(String(left), String(right))
}

/** What clicking a column heading does.
 *
 * Three states rather than two, and the third is the reason this is a function
 * and not `direction === 'asc' ? 'desc' : 'asc'`: clicking a *different*
 * column starts it ascending rather than inheriting the direction of the one
 * before. Inheriting is what a two-state toggle does, and it means the first
 * click on a new column can hand back an order nobody asked for. */
export function toggleSort<Column extends string>(
  sort: Sort<Column>,
  column: Column,
): Sort<Column> {
  if (sort.column !== column) return { column, direction: 'asc' }
  return { column, direction: sort.direction === 'asc' ? 'desc' : 'asc' }
}

/** What a column heading announces: `ascending`, `descending`, or nothing.
 *
 * The value belongs in `aria-sort` on the `<th>`, and only on the one that is
 * sorted - `aria-sort="none"` on every other heading is allowed by the spec
 * and read out by some screen readers on every cell, which turns a table into
 * a recital. `undefined` removes the attribute. */
export function ariaSort(
  sort: Sort<string> | undefined,
  column: string,
): 'ascending' | 'descending' | undefined {
  if (!sort || sort.column !== column) return undefined
  return sort.direction === 'asc' ? 'ascending' : 'descending'
}

import type { HTMLAttributes, TdHTMLAttributes, ThHTMLAttributes } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { ariaSort, type Sort } from './table-sort'

/*
 * A table of rows, and the heading that reorders them.
 *
 * Parts rather than a `columns` prop, and that is the decision worth stating:
 * a `<DataTable columns={…} rows={…} />` is quicker to write for the first
 * table and then owns every cell in the product forever. The moment one column
 * needs a Badge, another a link, and a third the row's own menu, the prop
 * grows a `render` for each - at which point it is JSX with extra steps, spelt
 * in a shape only this component understands.
 *
 * So the parts are the ones HTML already has, dressed: a caller writes
 * `<TableRow>` and `<TableCell>` and puts whatever it likes inside. What is
 * bought by having them here rather than in the product is that every table of
 * the line has the same row height, the same heading, the same hairline and
 * the same behaviour when a column is sorted - and that a heading that sorts
 * announces it, which is the part hand-rolled tables get wrong.
 *
 * The sorting arithmetic is next door in `table-sort`, with no React in it -
 * a product that sorts on the server imports that and never this.
 *
 * `<TableScroll>` exists because a table cannot scroll itself: `overflow` on a
 * `<table>` does nothing, so the wrapper is not decoration but the only place
 * a scrollbar can live. It is also what makes the sticky heading work, since
 * `position: sticky` needs a scroll container to stick inside.
 */

export const tableVariants = cva('w-full border-collapse text-left text-sm', {
  variants: {
    density: {
      /* Comfortable, and the default: a row a finger can hit, for a table a
       * person reads. */
      base: '[&_td]:py-2.5 [&_th]:py-2.5',
      /* For a table a person scans - a log, a ledger, a list of a thousand
       * things. Half the padding, same font: shrinking the text too is how a
       * dense table becomes an unreadable one. */
      dense: '[&_td]:py-1.5 [&_th]:py-1.5',
    },
  },
  defaultVariants: { density: 'base' },
})

export interface TableProps
  extends HTMLAttributes<HTMLTableElement>,
    VariantProps<typeof tableVariants> {}

export function Table({ density, className, ...props }: TableProps) {
  return <table className={cn(tableVariants({ density }), className)} {...props} />
}

/** The scroll container a table needs, and the one a sticky heading sticks in.
 *
 * The scrollbar is the theme's - an overlay that takes no room in the layout,
 * so a table that grows past the fold does not shift the column beside it. */
export function TableScroll({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('w-full overflow-x-auto', className)} {...props} />
}

export interface TableHeadProps extends HTMLAttributes<HTMLTableSectionElement> {
  /** Keep the heading in view while the body scrolls under it.
   *
   * Off by default. A sticky heading needs a container with a height to stick
   * inside; switched on by default it would silently do nothing in the common
   * case - a table that scrolls with the page - and look broken in the other. */
  sticky?: boolean
}

export function TableHead({ sticky = false, className, ...props }: TableHeadProps) {
  return (
    <thead
      className={cn(
        'text-xs text-dim',
        // The heading needs its own ground when it is sticky: transparent, it
        // would have the body's rows sliding visibly beneath its text.
        sticky && 'sticky top-0 z-sticky bg-bg',
        className,
      )}
      {...props}
    />
  )
}

export function TableBody({ className, ...props }: HTMLAttributes<HTMLTableSectionElement>) {
  return <tbody className={cn('', className)} {...props} />
}

export interface TableRowProps extends HTMLAttributes<HTMLTableRowElement> {
  /** The row the reader has picked out - the one open in the panel beside the
   * table, the one a keyboard cursor is on. Not a hover state. */
  selected?: boolean
}

export function TableRow({ selected = false, className, ...props }: TableRowProps) {
  return (
    <tr
      // Announced rather than only drawn: a row picked out by colour alone is
      // a row nobody using a screen reader knows about.
      aria-selected={selected || undefined}
      className={cn(
        'border-b border-line transition-colors last:border-b-0',
        selected ? 'bg-accent-soft' : 'hover:bg-soft',
        className,
      )}
      {...props}
    />
  )
}

export interface TableCellProps extends TdHTMLAttributes<HTMLTableCellElement> {
  /** Right-align and use the lining figures. For a column of numbers, and the
   * reason it is a prop rather than a class the caller adds: a column of
   * numbers that is not aligned is the most common defect in a table, and the
   * one nobody files a bug about. */
  numeric?: boolean
}

export function TableCell({ numeric = false, className, ...props }: TableCellProps) {
  return (
    <td
      className={cn('px-3 align-middle', numeric && 'text-right tabular-nums', className)}
      {...props}
    />
  )
}

export interface TableHeaderProps extends ThHTMLAttributes<HTMLTableCellElement> {
  numeric?: boolean
}

/** A plain heading, for a column that does not sort. */
export function TableHeader({ numeric = false, className, ...props }: TableHeaderProps) {
  return (
    <th
      scope="col"
      className={cn(
        'px-3 font-medium',
        numeric && 'text-right tabular-nums',
        className,
      )}
      {...props}
    />
  )
}

export interface TableSortHeaderProps extends Omit<TableHeaderProps, 'onClick'> {
  /** This column's id - the key the accessor sorts by. */
  column: string
  /** What is sorted now, across the whole table. */
  sort: Sort | undefined
  onSortChange: (column: string) => void
}

/** A heading that reorders the table when clicked.
 *
 * A real `<button>` inside the `<th>`, not a click handler on the cell: the
 * cell is not focusable, gets no keyboard, and announces nothing. This is the
 * part a hand-rolled table almost always gets wrong, and it is invisible to
 * everyone who reorders with a mouse.
 *
 * The arrow is `aria-hidden`, because `aria-sort` on the cell already says
 * which way the column points - a reader would otherwise hear the direction
 * twice, once as a word and once as a character nobody meant to publish. */
export function TableSortHeader({
  column,
  sort,
  onSortChange,
  numeric = false,
  className,
  children,
  ...props
}: TableSortHeaderProps) {
  const active = sort?.column === column
  const direction = sort?.direction

  return (
    <th
      scope="col"
      // Only on the sorted column. `aria-sort="none"` on every other heading
      // is valid and gets announced by some readers on every cell.
      aria-sort={ariaSort(sort, column)}
      className={cn('px-3 font-medium', numeric && 'tabular-nums', className)}
      {...props}
    >
      <button
        type="button"
        onClick={() => onSortChange(column)}
        className={cn(
          'group -mx-1 inline-flex w-[calc(100%+0.5rem)] cursor-pointer items-center gap-1 rounded-sm px-1',
          'transition-colors hover:text-text',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
          active && 'text-text',
          numeric && 'justify-end',
        )}
      >
        {children}
        <span
          aria-hidden
          className={cn(
            'text-2xs transition-opacity',
            // The arrow of the unsorted column appears on hover rather than
            // never: a heading that gives no sign it can be clicked is one
            // nobody clicks. It stays out of the way until the pointer is on
            // it, so a table of eight columns is not a row of eight arrows.
            active ? 'opacity-100' : 'opacity-0 group-hover:opacity-40',
          )}
        >
          {direction === 'desc' && active ? '▼' : '▲'}
        </span>
      </button>
    </th>
  )
}

/** What the table says when it has no rows.
 *
 * A row spanning every column rather than a block below the table, so the
 * heading stays where it is and the table does not change shape between having
 * rows and not. `colSpan` is required: without it the message sits under the
 * first column and the rest of the header hangs over nothing. */
export interface TableEmptyProps extends TdHTMLAttributes<HTMLTableCellElement> {
  colSpan: number
}

export function TableEmpty({ colSpan, className, ...props }: TableEmptyProps) {
  return (
    <tr>
      <td
        colSpan={colSpan}
        className={cn('px-3 py-10 text-center text-sm text-dim', className)}
        {...props}
      />
    </tr>
  )
}

import { useCallback, useState, type KeyboardEvent, type ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'
import { Chip } from './chip'

/*
 * TagInput.
 *
 * Free text turned into a list: type a word, press Enter, it becomes a chip.
 * This is the field for labels, keywords, recipients - anywhere the set of
 * values is not known in advance, which is exactly what separates it from
 * `Combobox multiple`. Choosing from a list is that component's job; this one
 * is for values that do not exist until someone types them.
 *
 * Base UI has no part for this, and the reason is worth stating: its Combobox
 * chips are for values chosen from a collection, and "create the thing I just
 * typed" is a decision about the product's data, not about the widget. So the
 * behaviour here is written, and written narrowly.
 *
 * What it does, and why each one is not optional:
 *
 * - **Enter commits.** The obvious one, and the reason it is a field at all.
 * - **Backspace on an empty input removes the last tag.** Without it the only
 *   way back is the mouse, and a list built by typing should be unbuildable
 *   by typing too.
 * - **Blur commits what was typed.** A word left in the box when the reader
 *   clicks Save is a word they believe they entered. Losing it silently is
 *   the single commonest complaint about fields of this shape.
 * - **Duplicates are refused, not stacked.** A tag list is a set.
 * - **Whitespace is trimmed and empties dropped**, so Enter on a blank input
 *   does nothing rather than adding a tag nobody can see.
 *
 * What it deliberately does not do: validate. What makes a tag acceptable -
 * length, charset, whether it must already exist - is the product's rule, and
 * a component that guessed would be wrong in both directions. Reject a value
 * by not putting it in `value`.
 */

export const tagInputVariants = cva(
  cn(
    fieldClasses,
    'flex flex-wrap items-center gap-1 py-1',
    'focus-within:outline-2 focus-within:outline-offset-0 focus-within:outline-accent',
  ),
  {
    variants: {
      size: {
        sm: 'min-h-8 text-xs',
        md: 'min-h-9',
        lg: 'min-h-10 text-base',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

/* The box inside the box.
 *
 * `min-h-*` on the container sets a floor; the input inside it has a height of
 * its own, and that is what a reader actually sees. A size that moved only the
 * container moved nothing - measured, `sm` and `md` both came out 38px tall,
 * because the input was `h-7` in all three and its padding decided the rest.
 *
 * `tailwind-merge` does not rescue this either: `h-7` and `min-h-8` are not
 * the same property, so both survive and the fixed height wins. The two have
 * to be declared together.
 */
const tagInputBoxVariants = cva(
  'w-auto min-w-24 flex-1 bg-transparent px-1 text-text outline-none placeholder:text-faint',
  {
    variants: {
      size: {
        sm: 'h-6 text-xs',
        md: 'h-7 text-sm',
        lg: 'h-8 text-base',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

export interface TagInputProps extends VariantProps<typeof tagInputVariants> {
  /** The tags. Controlled: the product owns the list. */
  value: string[]
  /** Called with the next list. */
  onValueChange: (value: string[]) => void
  /** Placeholder for the text box, shown when there is room for it. */
  placeholder?: string
  /** Names the field. Required - a box of chips with no label names nothing. */
  'aria-label'?: string
  /** Or points at a label element, when there is a visible one. */
  'aria-labelledby'?: string
  /** How a tag's remove button is named, for a screen reader. Takes the tag,
   * so the product can say "Remove documentation" in its own language.
   *
   * Required, like `Chip`'s own: a remove button exists only when there is a
   * word for it, and a word this component invented would ship in English to
   * every reader who does not read English. */
  removeLabel: (tag: string) => string
  /** Cap on how many tags may be added. */
  max?: number
  disabled?: boolean
  /** Drawn after the input, inside the box - a counter, a hint. */
  children?: ReactNode
  className?: string
  id?: string
}

export function TagInput({
  value,
  onValueChange,
  placeholder,
  removeLabel,
  max,
  disabled,
  size,
  children,
  className,
  id,
  ...aria
}: TagInputProps) {
  const [draft, setDraft] = useState('')

  const full = max !== undefined && value.length >= max

  const commit = useCallback(
    (raw: string) => {
      const tag = raw.trim()
      // Empty, duplicate, or past the cap: nothing to add. The draft is
      // cleared either way, so Enter always leaves the box ready for the next
      // word rather than leaving a rejected one sitting there.
      if (tag && !value.includes(tag) && !full) onValueChange([...value, tag])
      setDraft('')
    },
    [full, onValueChange, value],
  )

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      // Only when there is something to commit: otherwise Enter belongs to the
      // form around this, and swallowing it would break submitting by keyboard.
      if (draft.trim()) {
        event.preventDefault()
        commit(draft)
      }
      return
    }
    if (event.key === 'Backspace' && draft === '' && value.length > 0) {
      onValueChange(value.slice(0, -1))
    }
  }

  return (
    <div
      className={cn(tagInputVariants({ size }), disabled && 'pointer-events-none opacity-50', className)}
    >
      {value.map((tag) => (
        <Chip
          key={tag}
          removeLabel={removeLabel(tag)}
          onRemove={() => onValueChange(value.filter((entry) => entry !== tag))}
        >
          {tag}
        </Chip>
      ))}
      <input
        id={id}
        value={draft}
        disabled={disabled}
        // The list is the value; the box is how you add to it. Announcing the
        // box as the field would name the wrong thing, so the label goes here
        // where a screen reader meets it.
        {...aria}
        placeholder={full ? undefined : placeholder}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={onKeyDown}
        // A word typed and not committed is a word the reader thinks they
        // entered. Blur is where that belief meets the form's Save button.
        onBlur={() => commit(draft)}
        className={tagInputBoxVariants({ size })}
      />
      {children}
    </div>
  )
}

import { useCallback, useLayoutEffect, useRef, type Ref, type TextareaHTMLAttributes } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * Textarea.
 *
 * A multi-line field that can grow with what is typed into it, which is the
 * only interesting part: a fixed box makes someone scroll inside a scroll,
 * and a box that grows without limit pushes the button they are trying to
 * reach off the screen. `autoResize` grows it; `maxRows` says when to stop
 * and let it scroll after all.
 *
 * The measurement is the usual trick and worth stating: height is reset to
 * `auto` before reading `scrollHeight`, because a box already tall enough
 * reports its own height and never shrinks back.
 */
export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  ref?: Ref<HTMLTextAreaElement>
  /** Grow to fit the content instead of scrolling. */
  autoResize?: boolean
  /** Stop growing here, in lines, and scroll instead. */
  maxRows?: number
}

export function Textarea({
  className,
  ref,
  autoResize = false,
  maxRows,
  onChange,
  ...props
}: TextareaProps) {
  const own = useRef<HTMLTextAreaElement>(null)

  const resize = useCallback(() => {
    const element = own.current
    if (!element || !autoResize) return

    // Reset first: a box that is already tall enough reports its own height as
    // `scrollHeight` and would never shrink again.
    element.style.height = 'auto'

    const styles = getComputedStyle(element)
    const lineHeight = Number.parseFloat(styles.lineHeight) || 0
    const vertical =
      Number.parseFloat(styles.paddingTop) +
      Number.parseFloat(styles.paddingBottom) +
      Number.parseFloat(styles.borderTopWidth) +
      Number.parseFloat(styles.borderBottomWidth)

    const wanted = element.scrollHeight
    const ceiling = maxRows && lineHeight ? maxRows * lineHeight + vertical : Infinity

    element.style.height = `${Math.min(wanted, ceiling)}px`
    element.style.overflowY = wanted > ceiling ? 'auto' : 'hidden'
  }, [autoResize, maxRows])

  // Before paint, so the field never appears at the wrong height and then
  // jumps - including on the first render, when it may already have a value.
  useLayoutEffect(resize, [resize, props.value, props.defaultValue])

  return (
    <textarea
      ref={(element) => {
        own.current = element
        if (typeof ref === 'function') ref(element)
        else if (ref) ref.current = element
      }}
      onChange={(event) => {
        resize()
        onChange?.(event)
      }}
      className={cn(fieldClasses, autoResize ? 'resize-none' : 'resize-y', className)}
      {...props}
    />
  )
}

import { useState, type Ref } from 'react'
import { cn } from 'dowel-ui'
import { fieldClasses } from './input'

/*
 * TimeField - a time of day, typed the way people say it.
 *
 * No donor for this one: neither product of the line had a time field, so
 * this is written from the same shape as DurationField, and for the same
 * reason. Anything a person plausibly types is accepted - `9`, `9:30`, `930`,
 * `9.30`, `9pm`, `21:30` - and what comes back is always `HH:MM`.
 *
 * The value is `HH:MM` in twenty-four hours, always, no matter how it was
 * typed or how it is shown. That is what a database column holds and what
 * sorts correctly as a string; whether the reader sees `9:30 PM` or `21:30`
 * is a matter of where they live, and `Intl` answers it.
 *
 * Not `<input type="time">`, and the reason is the same as NumberField's: the
 * browser draws its own control, its own spinner and its own clock popup,
 * none of which a stylesheet reaches - so a form of the product's own fields
 * gets one that is visibly not.
 *
 * Empty is `null`, like the other fields here: no time is not midnight.
 */

/** Minutes since midnight from whatever was typed, or `null` for empty, or
 * `undefined` when it cannot be read as a time.
 *
 * Exported because the parsing is the component - a test that types into the
 * box checks React's state handling, and what has to be right is this. */
export function parseTime(text: string): string | null | undefined {
  const input = text.trim().toLowerCase().replace(/\s+/g, '')
  if (input === '') return null

  // `pm` means add twelve hours, `am` means midnight is 12. Stripped first so
  // the rest of the parsing does not have to know about them.
  const meridiem = /(am|pm)$/.exec(input)?.[1]
  const body = meridiem ? input.slice(0, -2) : input

  let hours: number
  let minutes: number

  const separated = /^(\d{1,2})[:.](\d{2})$/.exec(body)
  if (separated) {
    hours = Number(separated[1])
    minutes = Number(separated[2])
  } else if (/^\d{1,2}$/.test(body)) {
    // A bare number is an hour: `9` is nine o'clock, not nine minutes past
    // midnight - which is what someone typing a time means.
    hours = Number(body)
    minutes = 0
  } else if (/^\d{3,4}$/.test(body)) {
    // `930` and `0930`, which is how a time gets typed when the colon is a
    // reach on a phone keyboard.
    hours = Number(body.slice(0, body.length - 2))
    minutes = Number(body.slice(-2))
  } else {
    return undefined
  }

  if (minutes > 59) return undefined

  if (meridiem) {
    if (hours < 1 || hours > 12) return undefined
    if (meridiem === 'pm' && hours !== 12) hours += 12
    if (meridiem === 'am' && hours === 12) hours = 0
  } else if (hours > 23) {
    return undefined
  }

  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`
}

/** How a time reads here: `21:30` in most of the world, `9:30 PM` in some of
 * it. The stored value does not change - only what is shown. */
export function formatTime(time: string, locale?: string): string {
  const [hours, minutes] = time.split(':').map(Number) as [number, number]
  return new Intl.DateTimeFormat(locale, { hour: 'numeric', minute: '2-digit' }).format(
    new Date(2024, 0, 1, hours, minutes),
  )
}

export interface TimeFieldProps {
  /** `HH:MM` in twenty-four hours, or `null` for empty. */
  value: string | null
  onValueChange: (value: string | null) => void
  /** How the time is shown while the field is not being typed into. The
   * reader's own unless stated. */
  locale?: string
  placeholder?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  name?: string
  id?: string
  ref?: Ref<HTMLInputElement>
  'aria-label'?: string
  'aria-describedby'?: string
  className?: string
}

export function TimeField({
  value,
  onValueChange,
  locale,
  className,
  ref,
  ...props
}: TimeFieldProps) {
  const display = (time: string | null) => (time === null ? '' : formatTime(time, locale))

  /* Text while it is being typed, a formatted time the rest of the time -
   * the same arrangement as DurationField, and for the same reason: a field
   * that reformats on every keystroke fights the person using it. */
  const [text, setText] = useState(() => display(value))
  const [editing, setEditing] = useState(false)

  /* The value this box last saw from outside, adjusted during render rather
   * than in an effect. Comparing against `value` would be wrong in exactly
   * the case that matters: after a commit the parent may still hold the old
   * one for a tick, and the box would clear itself under the reader. */
  const [seen, setSeen] = useState<string | null>(value)

  if (value !== seen) {
    setSeen(value)
    if (!editing) setText(display(value))
  }

  const commit = () => {
    setEditing(false)
    const parsed = parseTime(text)
    if (parsed === undefined) {
      // Unreadable: put back what the value actually is rather than leaving
      // the box saying something the form does not believe.
      setText(display(value))
      return
    }
    setText(display(parsed))
    if (parsed !== value) onValueChange(parsed)
  }

  return (
    <input
      {...props}
      ref={ref}
      type="text"
      inputMode="numeric"
      value={text}
      onFocus={() => setEditing(true)}
      onChange={(event) => setText(event.target.value)}
      onBlur={commit}
      onKeyDown={(event) => {
        if (event.key === 'Enter') {
          event.preventDefault()
          commit()
        }
      }}
      className={cn(fieldClasses, 'h-9 tabular-nums', className)}
    />
  )
}

import { Toast as Base } from '@base-ui/react/toast'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'

/*
 * Toast.
 *
 * For something that already happened and needs no decision. Anything that
 * needs an answer is a dialog - a toast that asks a question is a question the
 * reader can miss by looking away.
 *
 * The tone is on the toast rather than in five separate components, because
 * the difference between "saved" and "could not save" is emphasis, never
 * meaning: the sentence says which it is, and a reader who cannot separate
 * green from red gets the same message. The stripe down the side exists for
 * the same reason a badge carries a word.
 *
 * `Toast.Root` is `role="dialog"` inside a `role="region"` viewport, and Base
 * UI drives the live region, the timers, the pause on hover and focus, and the
 * swipe. What is here is the clothes and the vocabulary.
 */

export const toastVariants = cva(
  [
    'relative w-[min(22rem,calc(100vw-2rem))] overflow-hidden',
    'rounded-lg border border-line bg-raise p-3 pl-4 text-text shadow-float',
    // The stripe. `before` rather than a border, so the corner radius stays
    // the panel's own.
    'before:absolute before:inset-y-0 before:left-0 before:w-1',
    '[transition:opacity_var(--duration-base)_var(--ease-out),transform_var(--duration-base)_var(--ease-out)]',
    'data-[starting-style]:translate-x-4 data-[starting-style]:opacity-0',
    'data-[ending-style]:translate-x-4 data-[ending-style]:opacity-0',
  ],
  {
    variants: {
      tone: {
        neutral: 'before:bg-line-2',
        good: 'before:bg-good',
        warn: 'before:bg-warn',
        bad: 'before:bg-bad',
        info: 'before:bg-info',
      },
    },
    defaultVariants: { tone: 'neutral' },
  },
)

/** Wraps the part of the application that can raise a toast. One per screen;
 * nesting them gives a product two queues that do not know about each other. */
export const ToastProvider = Base.Provider

/** The manager: `add`, `update`, `close`, and `promise` for the common case of
 * "say this while it runs, that when it lands". */
export const useToastManager = Base.useToastManager

/** A toast raised outside React - from a store, an event handler, a worker.
 * Pass the result to `ToastProvider`'s `toastManager`. */
export const createToastManager = Base.createToastManager

/** The heading. Base UI points the toast's `aria-labelledby` at it. */
export function ToastTitle({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn('text-sm font-semibold', className)} {...props} />
}

/** The sentence under it, and the toast's `aria-describedby`. */
export function ToastDescription({ className, ...props }: Base.Description.Props) {
  return <Base.Description className={cn('mt-0.5 text-xs text-dim', className)} {...props} />
}

/** The one thing the reader can do about it: undo, or go and look. */
export function ToastAction({ className, ...props }: Base.Action.Props) {
  return (
    <Base.Action
      className={cn(
        'mt-2 inline-flex h-7 cursor-pointer items-center rounded-md px-2 text-xs font-medium',
        'bg-accent-soft text-accent transition-colors hover:bg-accent-soft/60',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        className,
      )}
      {...props}
    />
  )
}

/** The dismiss button. Needs a word - a bare cross is announced as nothing. */
export function ToastClose({ className, ...props }: Base.Close.Props) {
  return (
    <Base.Close
      className={cn(
        'absolute right-2 top-2 grid size-6 cursor-pointer place-items-center rounded-sm',
        'text-faint transition-colors hover:bg-soft hover:text-text',
        'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent',
        className,
      )}
      {...props}
    >
      <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden>
        <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
      </svg>
    </Base.Close>
  )
}

export interface ToastProps extends Base.Root.Props, VariantProps<typeof toastVariants> {}

/** One toast. The tone comes from the caller or from `toast.type`, so a
 * product that raises them through the manager gets the stripe for free. */
export function Toast({ tone, className, toast, ...props }: ToastProps) {
  const fromType = TONE_FOR_TYPE[toast.type ?? ''] ?? undefined
  return (
    <Base.Root
      toast={toast}
      className={cn(toastVariants({ tone: tone ?? fromType }), className)}
      {...props}
    />
  )
}

/** Base UI's own `type` values, mapped onto the vocabulary. A product calling
 * `manager.add({ type: 'success' })` should not also have to say which colour
 * that is. */
const TONE_FOR_TYPE: Record<string, 'good' | 'warn' | 'bad' | 'info' | undefined> = {
  success: 'good',
  warning: 'warn',
  error: 'bad',
  info: 'info',
  loading: 'info',
}

export interface ToastViewportProps extends Base.Viewport.Props {
  /** Where to portal to. Defaults to the document body, which is what keeps
   * toasts above everything regardless of where they were raised from. */
  container?: Base.Portal.Props['container']
}

/** Where they stack. Bottom right by default, which is the corner that does
 * not cover a form being filled in or a menu being read. */
export function ToastViewport({ container, className, ...props }: ToastViewportProps) {
  return (
    <Base.Portal container={container}>
      <Base.Viewport
        className={cn(
          'fixed bottom-4 right-4 flex w-[min(22rem,calc(100vw-2rem))] flex-col-reverse gap-2',
          '[z-index:var(--z-toast)]',
          className,
        )}
        {...props}
      />
    </Base.Portal>
  )
}

/*
 * The arithmetic behind Track, with no React in it.
 *
 * Split out for the reason `table-sort` and `tree-rows` are: a product that
 * needs the numbers - to label a segment, to test its own domain code, to draw
 * the same shape somewhere that is not the DOM - should not import a component
 * to get them.
 *
 * What lives here is only the geometry. Turning a day of work into segments,
 * or a set of tiers into them, is the product's own arithmetic and stays with
 * the product: this knows about spans and percentages and nothing else.
 */

/** A segment as the caller states it, in whatever units the caller counts in. */
export interface SegmentInput {
  /** Where it starts. Same units as `end` and as the track's span. */
  start: number
  /** Where it ends. A segment ending before it starts is empty, not backwards. */
  end: number
}

/** A segment as it is drawn: percentages of the track. */
export interface Placed {
  /** Distance from the left edge, 0-100. */
  left: number
  /** Width, 0-100. */
  width: number
  /** Whether the width is the real one, or the floor standing in for it.
   *
   * Worth knowing rather than hiding: a caller labelling segments may want to
   * say "under a minute" instead of a duration the bar is no longer drawing to
   * scale. */
  widened: boolean
}

/** The smallest a segment may be drawn, in percent.
 *
 * A ten-second pause in an eight-hour day is 0.03% of the track, which rounds
 * to no pixels at all: the segment is real, was measured, and would simply not
 * be there. The floor is the width at which a sliver is still visible on a
 * track a few hundred pixels wide. */
export const MIN_SEGMENT_WIDTH = 0.6

export interface PlaceOptions {
  /** The value the left edge stands for. Defaults to the first segment's start. */
  from?: number
  /** The value the right edge stands for. Defaults to the last segment's end. */
  to?: number
  /** Override the floor - `0` to draw every segment exactly to scale. */
  minWidth?: number
}

/**
 * Lay segments out along a track, as percentages.
 *
 * The scale is stated by `from` and `to` rather than inferred, because the two
 * readings differ and both are wanted: a day of work is read against itself
 * (an eight-hour day drawn across a third of the width wastes the space where
 * the breaks are), while a set of tiers is read against the whole 0-100 scale,
 * where the distance to the next tier is the distance you have to close.
 *
 * Widening a sliver to the floor is what makes this worth having once. It also
 * introduces the only subtlety here: a widened segment can run into the one
 * after it, and two segments drawn overlapping is a worse lie than a segment
 * drawn slightly too wide. So the pass is done in order, and each segment is
 * held back to where the next one starts - a floor is a request, not a
 * guarantee, and the last one may be trimmed by the end of the track.
 */
export function place(segments: SegmentInput[], options: PlaceOptions = {}): Placed[] {
  if (segments.length === 0) return []

  const from = options.from ?? Math.min(...segments.map((s) => s.start))
  const to = options.to ?? Math.max(...segments.map((s) => s.end))
  const span = to - from

  // A track with no span has nothing to scale against: every segment would be
  // at the same place with the same width, which is not a drawing of anything.
  if (!(span > 0)) return []

  const floor = options.minWidth ?? MIN_SEGMENT_WIDTH

  const raw = segments.map((segment) => {
    const start = Math.min(Math.max(segment.start, from), to)
    const end = Math.min(Math.max(segment.end, start), to)
    return { left: ((start - from) / span) * 100, width: ((end - start) / span) * 100 }
  })

  if (floor <= 0) return raw.map((segment) => ({ ...segment, widened: false }))

  /*
   * Widening is a layout pass, not a per-segment decision, and the first
   * version of this got it wrong in a way worth recording: it capped each
   * sliver at "where the next segment starts", which protects against overlap
   * and also means a segment that touches its neighbour can never grow at all.
   * Both shapes this component exists for are contiguous - work then break
   * then work, one tier after another - so the floor did nothing for either of
   * them, and the tests missed it because their crowded case had a gap.
   *
   * So a widened segment pushes what follows instead. That borrows room the
   * track does not have, and the debt is paid back at the end by the segments
   * wide enough to afford it - never by another sliver, which would undo the
   * widening we just did.
   */
  const widened: Placed[] = []
  let shift = 0

  for (const segment of raw) {
    const left = segment.left + shift
    if (segment.width >= floor) {
      widened.push({ left, width: segment.width, widened: false })
      continue
    }
    shift += floor - segment.width
    widened.push({ left, width: floor, widened: true })
  }

  if (shift === 0) return widened

  /* The debt is only owed if the track has actually overflowed. A sliver on an
   * otherwise empty track - one segment, or several with gaps between them -
   * grows into room nobody was using, and nothing needs to give way. */
  const end = widened.at(-1)!
  const overflow = end.left + end.width - 100
  if (overflow <= 0) return widened

  /* Who can pay: everything above the floor, by however much it has to spare.
   * Taken in proportion, so one long stretch is not singled out to absorb the
   * whole debt while its neighbour keeps its exact width. */
  const spare = widened.reduce((sum, s) => sum + (s.widened ? 0 : Math.max(0, s.width - floor)), 0)

  /* Nobody can pay: every segment is at or under the floor, and the track is
   * genuinely too crowded to draw honestly at this width. The floor loses -
   * a bar running off its own end is worse than slivers too thin to see. */
  if (spare <= 0) return raw.map((segment) => ({ ...segment, widened: false }))

  let paid = 0
  return widened.map((segment) => {
    const left = segment.left - paid
    if (segment.widened) return { ...segment, left }

    const contribution = (Math.max(0, segment.width - floor) / spare) * overflow
    paid += contribution
    return { left, width: segment.width - contribution, widened: false }
  })
}

/** Where a marker sits on the same scale, as a percentage, or `null` when it
 * falls outside the track.
 *
 * Outside rather than clamped: a marker pinned to the edge says "here, at the
 * very end", which is a different statement from "not on this track at all". */
export function markerAt(value: number, from: number, to: number): number | null {
  const span = to - from
  if (!(span > 0)) return null
  if (value < from || value > to) return null
  return ((value - from) / span) * 100
}

import type { HTMLAttributes, ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from 'dowel-ui'
import { markerAt, place, type SegmentInput } from './track-segments'

/*
 * A bar divided into stretches, with something standing somewhere along it.
 *
 * Two products had written this independently and arrived at the same
 * construction - a rounded track, segments positioned absolutely by percent, a
 * floor under the segment width so a short one does not vanish - differing
 * only in what a segment meant. One drew the tiers of a rubric with the score
 * standing among them; the other drew a working day as alternating work and
 * breaks. Neither could be built from the other, and each knew something the
 * other did not: the tiers had the marker and the three-state reading of a
 * segment (passed, standing in, still ahead), the day had the minimum width
 * and the difference between an empty track and an unknown one.
 *
 * So it is one component, and the two are its two shapes:
 *
 *   **spans** - stretches of a whole, each meaning something in its own right:
 *   work and breaks, phases, occupancy. Adjacent or separated; gaps are the
 *   track showing through.
 *
 *   **thresholds** - a scale cut into bands, with a position on it. Here the
 *   segments are contiguous by construction and the point is not the bands but
 *   where you stand among them: "nearly a clip" is what the reader wants, and
 *   a badge saying which band you are in cannot say it.
 *
 * The arithmetic is in `track-segments`, importable without React.
 *
 * What this does NOT do is own its own height in pixels, and that is
 * deliberate: it is `h-1.5` in one donor and `h-2.5` in the other because the
 * bar carries different weight on the two screens. What it does own is the
 * geometry inside itself - percentages of its own box, never of a parent's -
 * which is the part that broke when a consumer put a percentage-height chart
 * inside a flex row and every bar resolved to zero.
 */

export const trackVariants = cva('relative w-full overflow-hidden rounded-full', {
  variants: {
    size: {
      /* Beside text, where the bar is a detail of a line. */
      sm: 'h-1.5',
      /* On its own row, where the bar is the thing being read. */
      md: 'h-2.5',
    },
  },
  defaultVariants: { size: 'md' },
})

export const trackSegmentVariants = cva('absolute top-0 h-full', {
  variants: {
    tone: {
      /* The subject: work done, the band you are standing in. */
      accent: 'bg-accent',
      /* Behind you, or secondary: a band already passed. Dimmed so the
       * current one carries the eye - a flat wash of "reached" over half the
       * bar says only that you are not at zero. */
      past: 'bg-accent/40',
      /* Ahead, or simply not the subject: a break, a band not yet reached. */
      idle: 'bg-line-2',
      /* Status, for a stretch that is itself a state rather than a quantity. */
      good: 'bg-good',
      warn: 'bg-warn',
      bad: 'bg-bad',
    },
  },
  defaultVariants: { tone: 'accent' },
})

export type TrackTone = NonNullable<VariantProps<typeof trackSegmentVariants>['tone']>

export interface TrackSegment extends SegmentInput {
  /** Distinguishes this segment from its neighbours in the DOM. */
  key: string
  tone?: TrackTone
  /** What this stretch is, in words. Shown on hover, and the only place the
   * segment's meaning exists for a reader who cannot see the colours. */
  label?: string
}

export interface TrackProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    VariantProps<typeof trackVariants> {
  segments: TrackSegment[]
  /** The value the left edge stands for. Defaults to the earliest segment. */
  from?: number
  /** The value the right edge stands for. Defaults to the latest segment. */
  to?: number
  /** Where the position marker stands, on the same scale as the segments.
   * Omitted when there is no such thing - a day of work has no "you are here". */
  marker?: number
  /** What the whole bar says, for a reader who cannot see it. Required: the
   * segments are decoration to a screen reader, and their titles are not
   * announced in order. */
  label: string
  /** Override the floor under a segment's width - `0` draws everything exactly
   * to scale.
   *
   * The floor is right for a day of work, where a short break is a fact worth
   * seeing. It is wrong wherever the widths are being compared to each other,
   * because a widened segment is no longer to scale and a reader measuring by
   * eye would be measuring the floor. */
  minWidth?: number
  /** Separate adjacent segments with a hairline of the ground.
   *
   * On for thresholds, where the bands touch and the boundary between two
   * reached ones would otherwise be invisible. Off for spans, where a gap in
   * the data is meant to look different from a gap between two stretches. */
  divided?: boolean
}

export function Track({
  segments,
  from,
  to,
  marker,
  label,
  minWidth,
  divided = false,
  size,
  className,
  ...props
}: TrackProps) {
  const placed = place(segments, { from, to, minWidth })

  /* The marker rides the same scale as the segments, so it is resolved against
   * the same bounds rather than against its own reading of them. */
  const bounds = {
    from: from ?? Math.min(...segments.map((s) => s.start), Infinity),
    to: to ?? Math.max(...segments.map((s) => s.end), -Infinity),
  }
  const at = marker === undefined ? null : markerAt(marker, bounds.from, bounds.to)

  return (
    <div
      role="img"
      aria-label={label}
      className={cn(trackVariants({ size }), 'bg-soft', className)}
      {...props}
    >
      {placed.map((geometry, index) => {
        const segment = segments[index]!
        return (
          <span
            key={segment.key}
            title={segment.label}
            style={{ left: `${geometry.left}%`, width: `${geometry.width}%` }}
            className={cn(
              trackSegmentVariants({ tone: segment.tone }),
              // The hairline is drawn in the page's own ground rather than in
              // a border colour, so it reads as a cut between two fills
              // instead of a third colour of its own.
              divided && index > 0 && 'border-l border-bg',
            )}
          />
        )
      })}

      {at !== null && (
        /* A dark core inside a light sheath, so the mark keeps its contrast
         * over the accent band it usually stands on as well as over the empty
         * road ahead. Centred on its position rather than starting at it: the
         * mark says "here", and a mark whose left edge is the position reads
         * as half a step further along than it is. */
        <span
          style={{ left: `${at}%` }}
          className="absolute top-1/2 h-[10px] w-[6px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-bg ring-2 ring-text"
        />
      )}
    </div>
  )
}

/*
 * The labels under a track.
 *
 * Separate from the track because the two donors disagreed about whether there
 * are any - the day had none, the tiers had one per band - and because a caller
 * with three bands and a narrow column will want to drop them without giving
 * up the bar.
 */
export interface TrackScaleProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode
}

export function TrackScale({ className, ...props }: TrackScaleProps) {
  return (
    <div
      className={cn('flex justify-between text-[10px] text-faint', className)}
      {...props}
    />
  )
}

import type { ReactNode } from 'react'

/*
 * What a tree shows, with no React in it.
 *
 * Split out of the TreeView for the reason `table-sort` and `calendar-math`
 * were split out of their components: these are the sums, and the component is
 * the thing that draws them. A product that windows a large tree needs to know
 * how many rows it has before rendering any of them - that is this file, and
 * it never touches the DOM.
 */

export interface TreeNode {
  /** Stable identity. Not the label: two folders can hold a file of the same
   * name, and keying by label collapses them into one. */
  id: string
  label: ReactNode
  /** Absent or empty means a leaf. An empty array is deliberately *not* an
   * empty folder - a folder with nothing in it still opens, and saying so
   * needs a real value rather than the absence of one. */
  children?: TreeNode[]
  /** An empty folder: opens, and shows nothing. */
  empty?: boolean
}

/** One visible row: the node, how deep it sits, and the branch it belongs to. */
export interface TreeRow {
  node: TreeNode
  depth: number
  /** The id of the folder this row is inside, if any. What Left uses to get
   * out of a deep branch in one press. */
  parent?: string
}

/** The rows a tree shows, in the order the eye and the keyboard travel.
 *
 * Flattening is what makes the keyboard simple: Down is the next row of this
 * list, Up the previous, and neither has to know about nesting. A recursive
 * walk at every keystroke would ask the same question - what is visually next
 * - and answer it differently at each depth.
 *
 * It is also the answer to "how many rows is this tree", which is what a
 * product needs to put a tree inside a VirtualList. */
export function visibleRows(
  nodes: readonly TreeNode[],
  open: ReadonlySet<string>,
  depth = 0,
  parent?: string,
): TreeRow[] {
  const rows: TreeRow[] = []
  for (const node of nodes) {
    rows.push({ node, depth, parent })
    if (node.children?.length && open.has(node.id)) {
      rows.push(...visibleRows(node.children, open, depth + 1, node.id))
    }
  }
  return rows
}

/** Whether this node is a folder - something that opens, even if empty. */
export function isBranch(node: TreeNode): boolean {
  return Boolean(node.empty) || Boolean(node.children?.length)
}

import { useMemo, useState, type KeyboardEvent } from 'react'
import { cn } from 'dowel-ui'
import { isBranch, visibleRows, type TreeNode } from './tree-rows'

/*
 * A tree: folders that open, one tab stop, arrows to move.
 *
 * The shape products reach for and then get wrong in the same place every
 * time. A tree is not a nest of lists with click handlers - it is one control
 * with a cursor in it, and the difference is the whole component:
 *
 *   **One tab stop, not one per node.** A tree of four hundred files with a
 *   `tabIndex` on each is four hundred stops between the sidebar and the
 *   editor. The container is what the keyboard reaches, and the arrows move a
 *   cursor inside it - the arrangement a `RadioGroup` has, for the same
 *   reason.
 *
 *   **Right and left do different things depending on where you are.** Right
 *   on a closed folder opens it; on an open one it steps into the first child;
 *   on a leaf it does nothing. Left closes an open folder, and on a leaf or a
 *   closed one it jumps to the parent - which is how a reader gets out of a
 *   deep branch without walking back up through every sibling.
 *
 * Both come from the ARIA tree pattern, and neither is guessable from looking
 * at a finished tree, which is why every hand-rolled one implements Up and
 * Down and stops there.
 *
 * The nodes are given, not discovered: a tree that loads its children when a
 * folder opens is a different component with a different problem (a spinner
 * per node, a request per open, an error state inside a row). This one is
 * handed everything and decides what to show.
 *
 * Which rows are visible is next door in `tree-rows`, with no React in it - a
 * product windowing a large tree imports that and never this.
 */

export interface TreeViewProps {
  nodes: readonly TreeNode[]
  /** Which folders are open. Uncontrolled if omitted. */
  open?: ReadonlySet<string>
  onOpenChange?: (open: Set<string>) => void
  /** Which row is chosen - the file being edited, not the one the cursor is
   * on. The two move apart: a reader walks the tree with arrows without
   * opening anything until Enter. */
  selected?: string
  onSelect?: (id: string) => void
  /** What a screen reader calls the tree. Required: a bare tree announces
   * "tree" and nothing else, and the word belongs to the product. */
  label: string
  className?: string
}

export function TreeView({
  nodes,
  open: openProp,
  onOpenChange,
  selected,
  onSelect,
  label,
  className,
}: TreeViewProps) {
  const [openState, setOpenState] = useState<ReadonlySet<string>>(() => new Set())
  const open = openProp ?? openState

  const setOpen = (next: Set<string>) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const rows = useMemo(() => visibleRows(nodes, open), [nodes, open])

  /* Where the keyboard is, which is not where the selection is. The cursor
   * starts on the selected row when there is one, so arrowing into a tree
   * continues from what is open rather than from the top. */
  const [cursor, setCursor] = useState<string | undefined>(undefined)
  const active = rows.find((row) => row.node.id === cursor)
    ? cursor
    : (rows.find((row) => row.node.id === selected)?.node.id ?? rows[0]?.node.id)

  const index = rows.findIndex((row) => row.node.id === active)

  const move = (to: number) => {
    const row = rows[Math.min(Math.max(0, to), rows.length - 1)]
    if (row) setCursor(row.node.id)
  }

  const toggle = (id: string, next: boolean) => {
    const copy = new Set(open)
    if (next) copy.add(id)
    else copy.delete(id)
    setOpen(copy)
  }

  const onKeyDown = (event: KeyboardEvent) => {
    const current = rows[index]
    if (!current) return
    const branch = isBranch(current.node)
    const isOpen = open.has(current.node.id)

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        move(index + 1)
        break
      case 'ArrowUp':
        event.preventDefault()
        move(index - 1)
        break
      case 'ArrowRight':
        event.preventDefault()
        // Open, then step in. Two presses rather than one that does both,
        // because opening a folder and moving into it are different intents -
        // and a reader who wanted only to look inside would have lost the row
        // they were on.
        if (branch && !isOpen) toggle(current.node.id, true)
        else if (branch && isOpen) move(index + 1)
        break
      case 'ArrowLeft': {
        event.preventDefault()
        if (branch && isOpen) {
          toggle(current.node.id, false)
          break
        }
        // Out of the branch rather than up one row. This is the escape from a
        // deep folder, and the part hand-rolled trees leave out: without it
        // the only way back to the parent is through every sibling below.
        const parent = current.parent
        if (parent) setCursor(parent)
        break
      }
      case 'Home':
        event.preventDefault()
        move(0)
        break
      case 'End':
        event.preventDefault()
        move(rows.length - 1)
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        if (branch) toggle(current.node.id, !isOpen)
        else onSelect?.(current.node.id)
        break
      default:
        break
    }
  }

  return (
    <div
      role="tree"
      aria-label={label}
      // One stop for the whole tree. A `tabIndex` per node is how a sidebar of
      // four hundred files becomes four hundred stops before the editor.
      tabIndex={0}
      onKeyDown={onKeyDown}
      // The cursor is published rather than only drawn: this is what a screen
      // reader follows, and what makes the tree one control instead of a
      // collection of rows.
      aria-activedescendant={active ? `tree-${active}` : undefined}
      className={cn(
        'text-sm',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        className,
      )}
    >
      {rows.map(({ node, depth }) => {
        const branch = isBranch(node)
        const isOpen = open.has(node.id)
        return (
          <div
            key={node.id}
            id={`tree-${node.id}`}
            role="treeitem"
            // Only on folders. On a leaf it would announce "collapsed" for
            // something that never opens.
            aria-expanded={branch ? isOpen : undefined}
            aria-selected={node.id === selected || undefined}
            // One-based, and the level a reader is told - the indent is the
            // sighted half of the same fact.
            aria-level={depth + 1}
            onClick={() => {
              setCursor(node.id)
              if (branch) toggle(node.id, !isOpen)
              else onSelect?.(node.id)
            }}
            className={cn(
              'flex cursor-pointer items-center gap-1 rounded-sm py-1 pr-2 transition-colors',
              node.id === selected ? 'bg-accent-soft text-text' : 'hover:bg-soft',
              node.id === active && node.id !== selected && 'bg-softer',
            )}
            // Indent by depth. A padding rather than a nested box, because the
            // rows are one flat list - which is what lets the keyboard treat
            // Down as "the next row" without knowing about nesting.
            style={{ paddingLeft: `${depth * 16 + 8}px` }}
          >
            <span aria-hidden className={cn('w-3 shrink-0 text-2xs text-dim', !branch && 'opacity-0')}>
              {isOpen ? '▾' : '▸'}
            </span>
            <span className="truncate">{node.label}</span>
          </div>
        )
      })}
    </div>
  )
}

import type { HTMLAttributes } from 'react'
import { cn } from 'dowel-ui'

/*
 * Truncate.
 *
 * Text that does not fit, cut with an ellipsis - and, importantly, still
 * readable in full: the element carries its own text as a `title`, so hovering
 * shows what was cut. Every product wrote the one-line version of this and
 * none of them remembered the title.
 *
 * `lines` truncates after that many instead of one, which needs a different
 * mechanism (`line-clamp`) rather than a different value.
 */
export interface TruncateProps extends HTMLAttributes<HTMLSpanElement> {
  /** The text. A string, because the component has to be able to put it in a
   * `title` - arbitrary children could not be. */
  children: string
  /** Cut after this many lines. One by default. */
  lines?: number
  /** Say what the full text is on hover. On by default; turn it off where the
   * text is already visible elsewhere, or the tooltip is noise. */
  title?: string | undefined
}

export function Truncate({ children, lines = 1, className, title, ...props }: TruncateProps) {
  return (
    <span
      // The browser shows this only when the text is actually cut, so it costs
      // nothing when everything fits.
      title={title ?? children}
      className={cn(
        lines === 1 ? 'block truncate' : 'block overflow-hidden',
        className,
      )}
      style={
        lines > 1
          ? { display: '-webkit-box', WebkitLineClamp: lines, WebkitBoxOrient: 'vertical' }
          : undefined
      }
      {...props}
    >
      {children}
    </span>
  )
}

import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react'
import { cn } from 'dowel-ui'

/*
 * A list of a hundred thousand rows that puts a screenful in the DOM.
 *
 * The browser is fine with long lists until it is not: a hundred thousand
 * `<div>`s is a layout the machine recomputes on every change, and the page
 * stops responding while it does. What is drawn instead is the window the
 * reader can actually see, held in place by a tall spacer, so the scrollbar
 * still says how much there is.
 *
 * No virtualisation library. `react-window`, `react-virtuoso` and
 * `@tanstack/react-virtual` all solve the general problem - variable heights
 * measured at runtime, horizontal windows, grids - and the general problem is
 * not the one a design system has: every long list in a product is a column of
 * rows of one height. That case is the arithmetic below, and it is small
 * enough to read.
 *
 * The arithmetic is exported separately, and that is the part worth stating.
 * A window computed inside an effect can only be tested by a browser, and
 * jsdom gives every element a height of zero - so a test would assert against
 * a list that believes it is invisible, and pass whatever the code did. As
 * plain functions the rules are checkable: given a scroll offset and a height,
 * these rows are drawn.
 *
 * Variable row heights are deliberately not supported. Measuring them means
 * rendering to find out, which means a second pass, a cache, and a scrollbar
 * that changes length as the reader travels. When a product needs that, it
 * needs a library rather than a bigger version of this.
 */

export interface Window {
  /** Index of the first row to render. */
  start: number
  /** Index one past the last row to render. */
  end: number
  /** The height of the whole list, drawn or not - what makes the scrollbar
   * honest. */
  totalHeight: number
  /** How far down the first drawn row sits. Applied as a translation rather
   * than as a top margin, so the rows are not re-laid-out on every scroll. */
  offsetTop: number
}

export interface WindowInput {
  /** How many rows there are in total. */
  count: number
  /** How tall one row is, in pixels. One height for every row. */
  rowHeight: number
  /** How tall the scrolling box is. */
  viewportHeight: number
  /** How far the box is scrolled. */
  scrollTop: number
  /** How many extra rows to draw beyond each edge.
   *
   * Not decoration: without it a fast scroll paints blank where rows have not
   * been drawn yet, because the scroll event arrives after the pixels. Three
   * rows is enough to cover a frame at ordinary speeds and cheap enough not to
   * matter. */
  overscan?: number
}

/** Which rows to draw. Pure arithmetic, so it can be checked without a browser.
 *
 * Every edge case here is one that shows as a blank list rather than as an
 * error: a viewport of zero (the box has not been measured yet), a scroll
 * position past the end (the list shrank under the reader), a negative one
 * (elastic scrolling on a trackpad). */
export function windowFor({
  count,
  rowHeight,
  viewportHeight,
  scrollTop,
  overscan = 3,
}: WindowInput): Window {
  const rows = Math.max(0, Math.floor(count))
  const height = Math.max(1, rowHeight)
  const totalHeight = rows * height

  if (rows === 0) return { start: 0, end: 0, totalHeight: 0, offsetTop: 0 }

  // Clamped rather than trusted. A negative scrollTop is what a trackpad hands
  // over at the top of an elastic scroll, and `Math.floor` of it walks the
  // start index backwards into rows that do not exist.
  const top = Math.min(Math.max(0, scrollTop), Math.max(0, totalHeight - 1))

  const first = Math.floor(top / height)
  /* One more row than fits, so the row cut by the bottom edge is drawn rather
   * than appearing as the reader scrolls into it.
   *
   * The `+ 1` is also what keeps the first frame from being empty: before the
   * effect measures the box, `viewportHeight` is 0 and this is 1. A
   * `Math.max(1, ...)` around it looks like the guard for that and is dead
   * code - the expression cannot reach zero. Mutation found it: removing the
   * floor changed nothing at all. */
  const visible = Math.ceil(Math.max(0, viewportHeight) / height) + 1

  const start = Math.max(0, first - overscan)
  const end = Math.min(rows, first + visible + overscan)

  return { start, end, totalHeight, offsetTop: start * height }
}

export interface VirtualListProps<Row> {
  rows: readonly Row[]
  /** How tall one row is. Fixed, and the component enforces it - a row that
   * grows past this height overlaps its neighbour, which is why the value is
   * required rather than measured. */
  rowHeight: number
  children: (row: Row, index: number) => ReactNode
  /** A stable identity per row. Without it React keys by index, and a list
   * that is sorted or filtered reuses the wrong DOM node - the row moves but
   * its input keeps the text that was typed into a different row. */
  rowKey: (row: Row, index: number) => string | number
  overscan?: number
  /** What a screen reader calls the list. Required: a scrolling box of rows
   * with no name is announced as "list" and nothing else, and the word is the
   * product's to give. */
  label: string
  className?: string
}

export function VirtualList<Row>({
  rows,
  rowHeight,
  children,
  rowKey,
  overscan = 3,
  label,
  className,
}: VirtualListProps<Row>) {
  const viewport = useRef<HTMLDivElement>(null)
  const [scrollTop, setScrollTop] = useState(0)
  const [viewportHeight, setViewportHeight] = useState(0)

  const measure = useCallback(() => {
    const element = viewport.current
    if (!element) return
    setViewportHeight(element.clientHeight)
    setScrollTop(element.scrollTop)
  }, [])

  useEffect(() => {
    const element = viewport.current
    if (!element) return
    measure()

    /* The height is watched, not read once. A list inside a panel that opens,
     * a window the reader resizes, a font that loads late - all change the
     * viewport after mount, and a list that measured once draws the wrong
     * number of rows until something scrolls. */
    if (typeof ResizeObserver === 'undefined') return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [measure])

  const { start, end, totalHeight, offsetTop } = windowFor({
    count: rows.length,
    rowHeight,
    viewportHeight,
    scrollTop,
    overscan,
  })

  return (
    <div
      ref={viewport}
      onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
      // `tabIndex` because a box that scrolls has to be reachable: a keyboard
      // user with no focusable row inside cannot otherwise page through it.
      tabIndex={0}
      role="list"
      aria-label={label}
      className={cn(
        'relative overflow-y-auto',
        'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
        className,
      )}
    >
      {/* The spacer is what the scrollbar measures. Without it the box is only
        * as tall as the rows drawn, and the reader can never scroll past the
        * first screenful. */}
      <div style={{ height: totalHeight }} className="relative">
        <div
          // Translated rather than positioned with `top`: a transform is
          // composited, while changing `top` re-lays-out the subtree on every
          // scroll event.
          style={{ transform: `translateY(${offsetTop}px)` }}
          className="absolute inset-x-0 top-0"
        >
          {rows.slice(start, end).map((row, offset) => {
            const index = start + offset
            return (
              <div
                key={rowKey(row, index)}
                role="listitem"
                /* The pair that makes a window honest to a screen reader.
                 *
                 * Without them the reader counts the rows it can see and says
                 * "3 of 20" in a list of a hundred thousand - the rows in the
                 * DOM are a screenful, and that is exactly what a virtual list
                 * hides. `aria-setsize` is the real total, `aria-posinset` the
                 * real position.
                 *
                 * Deliberately not `aria-rowcount`/`aria-rowindex`, which were
                 * the obvious names and are wrong: those belong to `grid`,
                 * `table` and `treegrid`. On a `list` they are unsupported -
                 * axe rejects them, and a reader would simply ignore them,
                 * which is the worse half: the markup would look like it said
                 * something. */
                aria-setsize={rows.length}
                aria-posinset={index + 1}
                style={{ height: rowHeight }}
              >
                {children(row, index)}
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}
